    /******************************************************************
     * v2.41.31：患者级临床缓存统一Tampermonkey GM大容量存储层
     *
     * 设计原则：
     * 1. GM保存完整患者缓存，localStorage只保留极小的同步/迁移信号；
     * 2. 首次读取旧版localStorage完整对象时，先成功写入GM，再替换为信号；
     * 3. GM不可用时保留旧localStorage回退，避免缓存功能成为单点故障；
     * 4. 不做最近患者淘汰、不删除records、不截断正文；清理由用户显式触发；
     * 5. 患者临床缓存不进入现有WebDAV长期配置白名单。
     ******************************************************************/
    const INPATIENT_LARGE_CACHE_GM_PREFIX =
        'medicalInpatientLargeCacheV1::';

    const INPATIENT_LARGE_CACHE_SIGNAL_MODE =
        'tampermonkey-gm-large-cache-v1';

    const INPATIENT_CACHE_MANAGEMENT_CHANGED_EVENT =
        'medical-userscript-cache-data-changed';

    function inpatientLargeCacheGmKey(storageKey) {
        return (
            INPATIENT_LARGE_CACHE_GM_PREFIX +
            String(storageKey || '')
        );
    }

    function inpatientLargeCachePlainStore(value) {
        if (
            value &&
            typeof value === 'object' &&
            !Array.isArray(value)
        ) {
            return value;
        }
        return {};
    }

    function inpatientLargeCacheParseStore(value) {
        if (
            value &&
            typeof value === 'object' &&
            !Array.isArray(value)
        ) {
            return value;
        }
        const raw = String(value == null ? '' : value).trim();
        if (!raw) return {};
        try {
            return inpatientLargeCachePlainStore(
                JSON.parse(raw)
            );
        } catch (error) {
            return {};
        }
    }

    function inpatientLargeCacheSignalObject(value) {
        let parsed = value;
        if (typeof value === 'string') {
            try {
                parsed = JSON.parse(value || 'null');
            } catch (error) {
                return null;
            }
        }
        if (
            parsed &&
            typeof parsed === 'object' &&
            !Array.isArray(parsed) &&
            parsed.storageMode === INPATIENT_LARGE_CACHE_SIGNAL_MODE
        ) {
            return parsed;
        }
        return null;
    }

    function inpatientLargeCacheByteLength(value) {
        const textValue = String(value == null ? '' : value);
        try {
            return new Blob([textValue]).size;
        } catch (error) {
            return textValue.length * 2;
        }
    }

    function inpatientLargeCacheBuildSignal(
        storageKey,
        serialized,
        store
    ) {
        return {
            schemaVersion: 1,
            storageMode: INPATIENT_LARGE_CACHE_SIGNAL_MODE,
            gmKey: inpatientLargeCacheGmKey(storageKey),
            updatedAt: Date.now(),
            entryCount: Object.keys(
                inpatientLargeCachePlainStore(store)
            ).length,
            byteLength:
                inpatientLargeCacheByteLength(serialized)
        };
    }

    function inpatientLargeCacheNotifyChanged(storageKey) {
        try {
            document.dispatchEvent(
                new CustomEvent(
                    INPATIENT_CACHE_MANAGEMENT_CHANGED_EVENT,
                    {
                        detail: {
                            adapterKey: 'inpatient',
                            storageKey: String(storageKey || ''),
                            time: Date.now()
                        }
                    }
                )
            );
        } catch (error) {
            // 管理器未加载或页面正在销毁时不影响缓存读写。
        }
    }

    function inpatientLargeCacheWriteSignal(
        storageKey,
        serialized,
        store
    ) {
        const signalText = JSON.stringify(
            inpatientLargeCacheBuildSignal(
                storageKey,
                serialized,
                store
            )
        );
        try {
            localStorage.setItem(storageKey, signalText);
        } catch (error) {
            /*
             * 旧完整缓存本身可能已经把localStorage撑满。GM已经写成功后，
             * 可以安全删除这个旧大对象，再写回几十/几百字节的同步信号。
             */
            try {
                localStorage.removeItem(storageKey);
                localStorage.setItem(storageKey, signalText);
            } catch (ignored) {
                // GM完整数据已经存在；同步信号失败不影响当前标签页读取。
            }
        }
        return signalText;
    }

    function inpatientLargeCacheReadSerializedFromGmOnly(storageKey) {
        if (
            typeof GM_getValue !== 'function' ||
            !storageKey
        ) {
            return null;
        }
        try {
            const value = GM_getValue(
                inpatientLargeCacheGmKey(storageKey),
                undefined
            );
            if (value === undefined || value === null || value === '') {
                return null;
            }
            if (typeof value === 'string') {
                return value;
            }
            return JSON.stringify(value);
        } catch (error) {
            return null;
        }
    }

    function inpatientLargeCacheReadStore(storageKey) {
        const gmSerialized =
            inpatientLargeCacheReadSerializedFromGmOnly(
                storageKey
            );

        if (gmSerialized) {
            return inpatientLargeCacheParseStore(
                gmSerialized
            );
        }

        let localRaw = '';
        try {
            localRaw = localStorage.getItem(storageKey) || '';
        } catch (error) {
            localRaw = '';
        }

        if (!localRaw) return {};

        if (inpatientLargeCacheSignalObject(localRaw)) {
            /*
             * 已经是GM信号但GM当前不可读（例如脚本授权被撤销）。
             * 信号本身不包含患者正文，不能伪造为空的完整缓存来源。
             */
            return {};
        }

        const legacyStore =
            inpatientLargeCacheParseStore(localRaw);

        /*
         * 旧localStorage完整缓存懒迁移：先写GM成功，再替换旧值。
         * 若GM失败，继续直接使用旧对象，确保版本升级可回退。
         */
        if (
            typeof GM_setValue === 'function' &&
            Object.keys(legacyStore).length
        ) {
            try {
                const serialized = JSON.stringify(legacyStore);
                GM_setValue(
                    inpatientLargeCacheGmKey(storageKey),
                    serialized
                );
                inpatientLargeCacheWriteSignal(
                    storageKey,
                    serialized,
                    legacyStore
                );
                inpatientLargeCacheNotifyChanged(storageKey);
            } catch (error) {
                // 迁移失败时继续保留/读取旧localStorage完整缓存。
            }
        }

        return legacyStore;
    }

    function inpatientLargeCacheWriteStore(
        storageKey,
        store
    ) {
        const normalized =
            inpatientLargeCachePlainStore(store);
        const serialized = JSON.stringify(normalized);
        let gmError = null;

        if (typeof GM_setValue === 'function') {
            try {
                GM_setValue(
                    inpatientLargeCacheGmKey(storageKey),
                    serialized
                );
                inpatientLargeCacheWriteSignal(
                    storageKey,
                    serialized,
                    normalized
                );
                inpatientLargeCacheNotifyChanged(storageKey);
                return {
                    mode: 'tampermonkey-gm',
                    byteLength:
                        inpatientLargeCacheByteLength(serialized),
                    entryCount: Object.keys(normalized).length
                };
            } catch (error) {
                gmError = error;
            }
        }

        /*
         * 兼容非Tampermonkey/授权异常环境。正常安装v2.41.31时不会走这里。
         */
        try {
            localStorage.setItem(storageKey, serialized);
            inpatientLargeCacheNotifyChanged(storageKey);
            return {
                mode: 'localStorage-fallback',
                byteLength:
                    inpatientLargeCacheByteLength(serialized),
                entryCount: Object.keys(normalized).length
            };
        } catch (error) {
            throw new Error(
                '患者缓存保存失败：Tampermonkey GM大容量存储不可用，且浏览器localStorage容量不足' +
                (
                    gmError && gmError.message
                        ? '（GM错误：' + gmError.message + '）'
                        : ''
                )
            );
        }
    }

    function inpatientLargeCacheDeleteStore(storageKey) {
        try {
            if (typeof GM_deleteValue === 'function') {
                GM_deleteValue(
                    inpatientLargeCacheGmKey(storageKey)
                );
            }
        } catch (error) {
            // 继续清理旧localStorage/信号。
        }
        try {
            localStorage.removeItem(storageKey);
        } catch (error) {
            // 忽略。
        }
        inpatientLargeCacheNotifyChanged(storageKey);
        return true;
    }

    function inpatientLargeCacheStats(storageKey) {
        const store =
            inpatientLargeCacheReadStore(storageKey);
        const serialized = JSON.stringify(store);
        return {
            storageKey: String(storageKey || ''),
            gmKey: inpatientLargeCacheGmKey(storageKey),
            storageMode:
                inpatientLargeCacheReadSerializedFromGmOnly(storageKey)
                    ? 'Tampermonkey GM'
                    : 'localStorage兼容',
            entryCount: Object.keys(store).length,
            byteLength:
                inpatientLargeCacheByteLength(serialized)
        };
    }



    /******************************************************************
     * v2.41.23：全局病历格式预处理接口
     *
     * 由患者信息脚本 v12.34.26+ 统一提供规则引擎和可选AI二次修复。
     * 本脚本只消费接口，不复制算法。
     * 仅处理病历叙事正文；医嘱、三测单及其他结构化数据不处理。
     ******************************************************************/

    const INPATIENT_MEDICAL_RECORD_PREPROCESS_BRIDGE_NAME =
        '__OHA_MEDICAL_RECORD_PREPROCESS__';

    function inpatientMedicalRecordPreprocessPage() {
        try {
            if (
                typeof unsafeWindow !== 'undefined' &&
                unsafeWindow
            ) {
                return unsafeWindow;
            }
        } catch (error) {
            // 继续使用window。
        }

        return window;
    }

    async function inpatientGetMedicalRecordPreprocessBridge() {
        const page =
            inpatientMedicalRecordPreprocessPage();

        let bridge =
            page[
                INPATIENT_MEDICAL_RECORD_PREPROCESS_BRIDGE_NAME
            ];

        /*
         * 两脚本均在document-idle执行，安装/加载顺序可能不同。
         * 最多等待约1秒，避免患者信息脚本稍晚发布接口时漏掉本次处理。
         */
        for (
            let index = 0;
            !bridge &&
            index < 10;
            index++
        ) {
            await sleep(100);

            bridge =
                page[
                    INPATIENT_MEDICAL_RECORD_PREPROCESS_BRIDGE_NAME
                ];
        }

        return bridge || null;
    }

    async function inpatientApplyGlobalMedicalRecordPreprocess(
        value,
        sourceLabel
    ) {
        const original =
            String(
                value || ''
            );

        const fallback = {
            text: original,
            applied: false,
            aiApplied: false,
            aiFallback: false,
            aiError: '',
            stats: null
        };

        if (!original.trim()) {
            return fallback;
        }

        try {
            const bridge =
                await inpatientGetMedicalRecordPreprocessBridge();

            if (
                !bridge ||
                typeof bridge.process !== 'function'
            ) {
                return fallback;
            }

            if (
                typeof bridge.isGlobalEnabled === 'function' &&
                !bridge.isGlobalEnabled()
            ) {
                return fallback;
            }

            const result =
                await bridge.process(
                    original,
                    {
                        allowAi: true,
                        source:
                            String(
                                sourceLabel ||
                                '住院信息病历正文'
                            )
                    }
                );

            if (
                !result ||
                typeof result !== 'object'
            ) {
                return fallback;
            }

            return {
                text:
                    String(
                        result.text ||
                        original
                    ),
                applied:
                    result.applied !== false,
                aiApplied:
                    Boolean(
                        result.aiApplied
                    ),
                aiFallback:
                    Boolean(
                        result.aiFallback
                    ),
                aiError:
                    String(
                        result.aiError ||
                        ''
                    ),
                stats:
                    result.stats || null
            };
        } catch (error) {
            /*
             * 格式预处理不能成为住院信息脚本单点故障。
             * 接口异常时返回原始正文，后续业务继续。
             */
            return {
                text: original,
                applied: false,
                aiApplied: false,
                aiFallback: true,
                aiError:
                    String(
                        error &&
                        error.message ||
                        error ||
                        '全局格式预处理调用失败'
                    ),
                stats: null
            };
        }
    }

    function inpatientAttachMedicalRecordPreprocessMeta(
        entry,
        result
    ) {
        const target =
            entry &&
            typeof entry === 'object'
                ? entry
                : {};

        target.preprocessVersion = 1;
        target.preprocessApplied =
            Boolean(
                result &&
                result.applied
            );
        target.preprocessAiApplied =
            Boolean(
                result &&
                result.aiApplied
            );
        target.preprocessAiFallback =
            Boolean(
                result &&
                result.aiFallback
            );

        if (
            result &&
            result.aiError
        ) {
            target.preprocessAiError =
                String(
                    result.aiError
                ).slice(
                    0,
                    300
                );
        } else {
            delete target.preprocessAiError;
        }

        return target;
    }

    function cloneDefaultConfig() {
        return Object.assign(
            {},
            DEFAULT_CONFIG
        );
    }

    function normalizeConfig(
        rawConfig
    ) {
        const config = Object.assign(
            cloneDefaultConfig(),
            rawConfig || {}
        );

        [
            'departmentDirector',
            'chiefPhysician',
            'primaryPhysician',
            'attendingPhysician',
            'residentPhysician',
            'qualityDoctor',
            'qualityNurse',
            'responsibleNurse',
            'coder',
            'readmissionPlan',
            'deepseekApiKey',
            'deepseekModel',
            'medicalAiMode'
        ].forEach(function (key) {
            config[key] = String(
                config[key] === undefined ||
                config[key] === null
                    ? ''
                    : config[key]
            ).trim();
        });

        const offset = Number(
            config.qualityDateOffsetDays
        );

        config.qualityDateOffsetDays =
            Number.isFinite(offset)
                ? Math.trunc(offset)
                : DEFAULT_CONFIG
                    .qualityDateOffsetDays;

        /*
         * v2.38：AI病历生成高级参数统一规范化。
         * Token范围限制在4000～24000，避免误填0或极端大值造成异常请求。
         */
        if (
            ![
                'auto',
                'chat',
                'reasoning'
            ].includes(
                config.medicalAiMode
            )
        ) {
            config.medicalAiMode =
                DEFAULT_CONFIG.medicalAiMode;
        }

        function normalizeMedicalAiToken(
            value,
            fallback
        ) {
            const number = Number(value);

            if (!Number.isFinite(number)) {
                return fallback;
            }

            return Math.max(
                4000,
                Math.min(
                    24000,
                    Math.trunc(number)
                )
            );
        }

        config.medicalAiPlainMaxTokens =
            normalizeMedicalAiToken(
                config.medicalAiPlainMaxTokens,
                DEFAULT_CONFIG.medicalAiPlainMaxTokens
            );

        config.medicalAiRetryMaxTokens =
            normalizeMedicalAiToken(
                config.medicalAiRetryMaxTokens,
                DEFAULT_CONFIG.medicalAiRetryMaxTokens
            );

        config.medicalAiReasoningMaxTokens =
            normalizeMedicalAiToken(
                config.medicalAiReasoningMaxTokens,
                DEFAULT_CONFIG.medicalAiReasoningMaxTokens
            );

        /*
         * 长文重试额度原则上不低于普通正文额度。
         */
        config.medicalAiRetryMaxTokens =
            Math.max(
                config.medicalAiRetryMaxTokens,
                config.medicalAiPlainMaxTokens
            );

        config.medicalAiAutoFallbackChat =
            config.medicalAiAutoFallbackChat !== false &&
            String(
                config.medicalAiAutoFallbackChat
            ).toLowerCase() !== 'false' &&
            String(
                config.medicalAiAutoFallbackChat
            ) !== '0';

        return config;
    }

    function loadConfig() {
        try {
            const saved = JSON.parse(
                localStorage.getItem(
                    CONFIG_STORAGE_KEY
                ) ||
                '{}'
            );

            return normalizeConfig(
                saved
            );
        } catch (error) {
            return cloneDefaultConfig();
        }
    }

    function saveConfig(
        config
    ) {
        const normalized =
            normalizeConfig(config);

        localStorage.setItem(
            CONFIG_STORAGE_KEY,
            JSON.stringify(
                normalized
            )
        );

        return normalized;
    }

    function resetConfig() {
        localStorage.removeItem(
            CONFIG_STORAGE_KEY
        );

        return cloneDefaultConfig();
    }

    function normalize(text) {
        return String(text || '')
            .replace(/\s+/g, '')
            .replace(/[：:*＊]/g, '')
            .replace(/（/g, '(')
            .replace(/）/g, ')')
            .trim();
    }

    function pad2(value) {
        return String(value).padStart(2, '0');
    }

    /*
     * 质控日期：运行脚本的电脑系统日期加指定天数。
     * 默认加1天，输出格式：yyyy-mm-dd。
     */
    function formatDateByOffset(
        offsetDays
    ) {
        const date = new Date();

        const offset = Number(
            offsetDays
        );

        date.setDate(
            date.getDate() +
            (
                Number.isFinite(offset)
                    ? Math.trunc(offset)
                    : 0
            )
        );

        return (
            date.getFullYear() +
            '-' +
            pad2(date.getMonth() + 1) +
            '-' +
            pad2(date.getDate())
        );
    }

    function describeDateOffset(
        offsetDays
    ) {
        const offset = Number(
            offsetDays
        );

        const days = Number.isFinite(offset)
            ? Math.trunc(offset)
            : 0;

        if (days === 0) {
            return '电脑系统当前日期';
        }

        if (days > 0) {
            return (
                '电脑系统当前日期加' +
                days +
                '天'
            );
        }

        return (
            '电脑系统当前日期减' +
            Math.abs(days) +
            '天'
        );
    }

    function isVisible(element) {
        if (
            !element ||
            !element.isConnected
        ) {
            return false;
        }

        const win =
            element.ownerDocument.defaultView;

        const style =
            win.getComputedStyle(element);

        const rect =
            element.getBoundingClientRect();

        return (
            style.display !== 'none' &&
            style.visibility !== 'hidden' &&
            style.opacity !== '0' &&
            rect.width > 0 &&
            rect.height > 0
        );
    }

    /******************************************************************
     * 获取主页面以及所有同源 iframe
     ******************************************************************/

    function getAllDocuments() {
        const documents = [];
        const visited = new Set();

        function collect(doc) {
            if (
                !doc ||
                visited.has(doc)
            ) {
                return;
            }

            visited.add(doc);
            documents.push(doc);

            let frames = [];

            try {
                frames = Array.from(
                    doc.querySelectorAll(
                        'iframe,frame'
                    )
                );
            } catch (error) {
                return;
            }

            frames.forEach(function (frame) {
                try {
                    const childDocument =
                        frame.contentDocument ||
                        frame.contentWindow.document;

                    if (childDocument) {
                        collect(childDocument);
                    }
                } catch (error) {
                    // 跨域 iframe 无法访问时直接跳过。
                }
            });
        }

        collect(document);

        return documents;
    }


    /******************************************************************
     * 仅获取“当前真正可见”的页面与同源iframe。
     *
     * HIS会同时保留多个患者标签页/iframe的DOM。旧版直接遍历所有
     * iframe，即使父iframe已经隐藏，子页面内部元素的getComputedStyle
     * 仍可能显示为visible，从而把上一个患者的住院号误识别为当前患者。
     * 病程AI的患者身份识别必须排除这些后台隐藏iframe。
     ******************************************************************/
    function getVisibleDocuments() {
        const documents = [];
        const visited = new Set();

        function collect(doc) {
            if (!doc || visited.has(doc)) {
                return;
            }

            visited.add(doc);
            documents.push(doc);

            let frames = [];

            try {
                frames = Array.from(
                    doc.querySelectorAll('iframe,frame')
                );
            } catch (error) {
                return;
            }

            frames.forEach(function (frame) {
                try {
                    /*
                     * 关键：先判断iframe元素本身在父页面是否可见。
                     * 隐藏标签页中的iframe不再进入身份识别链。
                     */
                    if (!isVisible(frame)) {
                        return;
                    }

                    const childDocument =
                        frame.contentDocument ||
                        frame.contentWindow.document;

                    if (childDocument) {
                        collect(childDocument);
                    }
                } catch (error) {
                    // 跨域iframe或未加载完成时跳过。
                }
            });
        }

        collect(document);
        return documents;
    }

    /******************************************************************
     * 标签文字定位
     ******************************************************************/

    function findTextElements(
        doc,
        aliases
    ) {
        if (
            !doc ||
            !doc.body
        ) {
            return [];
        }

        const targets =
            aliases.map(normalize)
                .filter(Boolean);

        const exact = [];
        const partial = [];

        const walker =
            doc.createTreeWalker(
                doc.body,
                doc.defaultView.NodeFilter.SHOW_TEXT
            );

        let node;

        while (
            (node = walker.nextNode())
        ) {
            const parent =
                node.parentElement;

            if (
                !parent ||
                !isVisible(parent)
            ) {
                continue;
            }

            const text =
                normalize(node.nodeValue);

            if (!text) {
                continue;
            }

            const exactTarget =
                targets.find(function (target) {
                    return text === target;
                });

            if (exactTarget) {
                exact.push({
                    element: parent,
                    target: exactTarget,
                    exact: true
                });

                continue;
            }

            const partialTarget =
                targets.find(function (target) {
                    return (
                        target.length >= 4 &&
                        text.includes(target)
                    );
                });

            if (partialTarget) {
                partial.push({
                    element: parent,
                    target: partialTarget,
                    exact: false
                });
            }
        }

        /*
         * 某些标签会被浏览器拆分成多个文本节点。
         * 文本节点未匹配时，再扫描常见标签容器。
         */
        if (!exact.length) {
            const selectors = [
                'label',
                'span',
                'div',
                'td',
                'th',
                'p',
                'a'
            ].join(',');

            const containers =
                Array.from(
                    doc.querySelectorAll(
                        selectors
                    )
                );

            containers.forEach(function (element) {
                if (!isVisible(element)) {
                    return;
                }

                const text =
                    normalize(
                        element.innerText ||
                        element.textContent
                    );

                if (!text) {
                    return;
                }

                const target =
                    targets.find(function (item) {
                        return (
                            text === item ||
                            (
                                item.length >= 4 &&
                                text.includes(item)
                            )
                        );
                    });

                if (!target) {
                    return;
                }

                partial.push({
                    element: element,
                    target: target,
                    exact: text === target
                });
            });
        }

        const results =
            exact.length
                ? exact
                : partial;

        const unique = [];
        const visited = new Set();

        results.forEach(function (item) {
            if (
                !visited.has(item.element)
            ) {
                visited.add(item.element);
                unique.push(item);
            }
        });

        unique.sort(function (a, b) {
            if (a.exact !== b.exact) {
                return a.exact
                    ? -1
                    : 1;
            }

            const rectA =
                a.element.getBoundingClientRect();

            const rectB =
                b.element.getBoundingClientRect();

            const areaA =
                rectA.width * rectA.height;

            const areaB =
                rectB.width * rectB.height;

            const textA =
                normalize(
                    a.element.innerText ||
                    a.element.textContent
                );

            const textB =
                normalize(
                    b.element.innerText ||
                    b.element.textContent
                );

            const excessA =
                Math.max(
                    0,
                    textA.length -
                    a.target.length
                );

            const excessB =
                Math.max(
                    0,
                    textB.length -
                    b.target.length
                );

            return (
                excessA * 1000 +
                areaA -
                (
                    excessB * 1000 +
                    areaB
                )
            );
        });

        return unique.map(function (item) {
            return item.element;
        });
    }

    function findLabel(
        doc,
        aliases
    ) {
        return (
            findTextElements(
                doc,
                aliases
            )[0] ||
            null
        );
    }

    /******************************************************************
     * 根据标签坐标寻找右侧最近控件
     ******************************************************************/

    function chooseNearestControl(
        label,
        controls,
        rectGetter
    ) {
        if (
            !label ||
            !controls ||
            !controls.length
        ) {
            return null;
        }

        const getRect =
            rectGetter ||
            function (element) {
                return element.getBoundingClientRect();
            };

        const labelRect =
            label.getBoundingClientRect();

        const labelCenterY =
            labelRect.top +
            labelRect.height / 2;

        const candidates =
            controls.map(function (control) {
                const rect =
                    getRect(control);

                const centerY =
                    rect.top +
                    rect.height / 2;

                const verticalDistance =
                    Math.abs(
                        centerY -
                        labelCenterY
                    );

                let horizontalDistance;

                if (
                    rect.left >=
                    labelRect.right - 20
                ) {
                    horizontalDistance =
                        Math.max(
                            0,
                            rect.left -
                            labelRect.right
                        );
                } else {
                    horizontalDistance =
                        1600 +
                        Math.abs(
                            rect.left -
                            labelRect.left
                        );
                }

                return {
                    control: control,
                    verticalDistance:
                        verticalDistance,
                    score:
                        verticalDistance * 45 +
                        horizontalDistance
                };
            });

        const sameRow =
            candidates.filter(function (item) {
                return (
                    item.verticalDistance <= 42
                );
            });

        const usable =
            sameRow.length
                ? sameRow
                : candidates;

        usable.sort(function (a, b) {
            return a.score - b.score;
        });

        return usable[0]
            ? usable[0].control
            : null;
    }

    /******************************************************************
     * 普通输入框定位
     ******************************************************************/

    function findInputsNearLabel(
        label
    ) {
        const selector = [
            'input:not([type="hidden"]):not([disabled])',
            'textarea:not([disabled])'
        ].join(',');

        const collected = [];
        const seen = new Set();

        function addControls(scope) {
            if (!scope) {
                return;
            }

            let controls = [];

            try {
                controls =
                    Array.from(
                        scope.querySelectorAll(
                            selector
                        )
                    );
            } catch (error) {
                return;
            }

            controls.forEach(function (control) {
                if (
                    isVisible(control) &&
                    !seen.has(control)
                ) {
                    seen.add(control);
                    collected.push(control);
                }
            });
        }

        const cell =
            label.closest('td,th');

        if (cell) {
            addControls(cell);

            let sibling =
                cell.nextElementSibling;

            for (
                let index = 0;
                sibling && index < 5;
                index++
            ) {
                addControls(sibling);

                sibling =
                    sibling.nextElementSibling;
            }

            addControls(
                cell.closest('tr')
            );
        }

        let parent =
            label.parentElement;

        for (
            let level = 0;
            parent && level < 7;
            level++
        ) {
            addControls(parent);

            parent =
                parent.parentElement;
        }

        addControls(
            label.ownerDocument
        );

        return collected;
    }

    function findInputNearLabel(
        label
    ) {
        return chooseNearestControl(
            label,
            findInputsNearLabel(label)
        );
    }

    function findInputByAliases(
        aliases
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    aliases
                );

            for (
                const label of labels
            ) {
                const input =
                    findInputNearLabel(
                        label
                    );

                if (input) {
                    return {
                        doc: doc,
                        label: label,
                        input: input
                    };
                }
            }
        }

        return null;
    }

    /******************************************************************
     * Select2及普通select定位
     ******************************************************************/

    function getSelectVisual(
        select
    ) {
        if (
            select.nextElementSibling &&
            select.nextElementSibling.classList &&
            select.nextElementSibling.classList.contains(
                'select2'
            )
        ) {
            return select.nextElementSibling;
        }

        if (select.parentElement) {
            const visual =
                select.parentElement.querySelector(
                    '.select2-container'
                );

            if (visual) {
                return visual;
            }
        }

        return select;
    }

    function getSelectRect(
        select
    ) {
        return getSelectVisual(
            select
        ).getBoundingClientRect();
    }

    function findSelectNearLabel(
        label
    ) {
        const selector =
            'select.select2-hidden-accessible,select';

        const collected = [];
        const seen = new Set();

        function addSelects(scope) {
            if (!scope) {
                return;
            }

            let selects = [];

            try {
                selects =
                    Array.from(
                        scope.querySelectorAll(
                            selector
                        )
                    );
            } catch (error) {
                return;
            }

            selects.forEach(function (select) {
                const visual =
                    getSelectVisual(select);

                if (
                    isVisible(visual) &&
                    !seen.has(select)
                ) {
                    seen.add(select);
                    collected.push(select);
                }
            });
        }

        const cell =
            label.closest('td,th');

        if (cell) {
            addSelects(cell);

            let sibling =
                cell.nextElementSibling;

            for (
                let index = 0;
                sibling && index < 5;
                index++
            ) {
                addSelects(sibling);

                sibling =
                    sibling.nextElementSibling;
            }

            addSelects(
                cell.closest('tr')
            );
        }

        let parent =
            label.parentElement;

        for (
            let level = 0;
            parent && level < 7;
            level++
        ) {
            addSelects(parent);

            parent =
                parent.parentElement;
        }

        addSelects(
            label.ownerDocument
        );

        return chooseNearestControl(
            label,
            collected,
            getSelectRect
        );
    }

    function findSelectByAliases(
        aliases
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    aliases
                );

            for (
                const label of labels
            ) {
                const select =
                    findSelectNearLabel(
                        label
                    );

                if (select) {
                    return {
                        doc: doc,
                        label: label,
                        select: select
                    };
                }
            }
        }

        return null;
    }

    /******************************************************************
     * 输入框赋值
     ******************************************************************/

    function setNativeInputValue(
        doc,
        input,
        value,
        options
    ) {
        const settings =
            Object.assign(
                {
                    focus: true,
                    blur: true
                },
                options || {}
            );

        const win =
            doc.defaultView;

        const prototype =
            input instanceof
            win.HTMLTextAreaElement
                ? win.HTMLTextAreaElement.prototype
                : win.HTMLInputElement.prototype;

        const descriptor =
            Object.getOwnPropertyDescriptor(
                prototype,
                'value'
            );

        if (settings.focus) {
            try {
                input.focus();
            } catch (error) {
                // 忽略聚焦失败。
            }
        }

        if (
            descriptor &&
            descriptor.set
        ) {
            descriptor.set.call(
                input,
                String(value)
            );
        } else {
            input.value =
                String(value);
        }

        input.setAttribute(
            'value',
            String(value)
        );

        if (win.jQuery) {
            win.jQuery(input)
                .val(String(value))
                .trigger('input')
                .trigger('change')
                .trigger('keyup');
        }

        input.dispatchEvent(
            new win.Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.KeyboardEvent(
                'keyup',
                {
                    bubbles: true,
                    cancelable: true,
                    key: '',
                    keyCode: 0,
                    which: 0
                }
            )
        );

        if (settings.blur) {
            try {
                input.blur();
            } catch (error) {
                // 忽略失焦失败。
            }
        }
    }

    function realClick(
        element
    ) {
        if (!element) {
            return;
        }

        const win =
            element.ownerDocument.defaultView;

        element.dispatchEvent(
            new win.MouseEvent(
                'mousedown',
                {
                    bubbles: true,
                    cancelable: true,
                    view: win
                }
            )
        );

        element.dispatchEvent(
            new win.MouseEvent(
                'mouseup',
                {
                    bubbles: true,
                    cancelable: true,
                    view: win
                }
            )
        );

        element.click();
    }

    function pressKey(
        element,
        key,
        keyCode
    ) {
        const win =
            element.ownerDocument.defaultView;

        const settings = {
            key: key,
            code: key,
            keyCode: keyCode,
            which: keyCode,
            bubbles: true,
            cancelable: true
        };

        element.dispatchEvent(
            new win.KeyboardEvent(
                'keydown',
                settings
            )
        );

        element.dispatchEvent(
            new win.KeyboardEvent(
                'keyup',
                settings
            )
        );
    }

    /******************************************************************
     * 人员输入框自动选择检索结果
     ******************************************************************/

    function findAutocompleteResult(
        doc,
        input,
        desiredText
    ) {
        const target =
            normalize(desiredText);

        const inputRect =
            input.getBoundingClientRect();

        const selector = [
            '[role="option"]',
            '.autocomplete-suggestion',
            '.ui-autocomplete li',
            '.dropdown-menu li',
            '.select2-results__option',
            '.datagrid-row',
            '.layui-table tr',
            'tr'
        ].join(',');

        const candidates =
            Array.from(
                doc.querySelectorAll(
                    selector
                )
            )
                .filter(isVisible)
                .map(function (element) {
                    const text =
                        normalize(
                            element.innerText ||
                            element.textContent
                        );

                    const rect =
                        element.getBoundingClientRect();

                    const containsTarget =
                        text === target ||
                        (
                            text.includes(target) &&
                            text.length <=
                            target.length + 24
                        );

                    if (!containsTarget) {
                        return null;
                    }

                    const verticalDistance =
                        Math.min(
                            Math.abs(
                                rect.top -
                                inputRect.bottom
                            ),
                            Math.abs(
                                rect.bottom -
                                inputRect.top
                            )
                        );

                    const horizontalDistance =
                        Math.abs(
                            rect.left -
                            inputRect.left
                        );

                    if (
                        verticalDistance > 550 ||
                        horizontalDistance > 900
                    ) {
                        return null;
                    }

                    return {
                        element: element,
                        score:
                            verticalDistance +
                            horizontalDistance +
                            (
                                text === target
                                    ? -300
                                    : 0
                            ) +
                            text.length
                    };
                })
                .filter(Boolean);

        if (!candidates.length) {
            return null;
        }

        candidates.sort(function (a, b) {
            return a.score - b.score;
        });

        return candidates[0].element;
    }

    async function tryCommitAutocomplete(
        doc,
        input,
        desiredText
    ) {
        /*
         * 给检索列表留出加载时间。
         */
        await sleep(450);

        let result =
            findAutocompleteResult(
                doc,
                input,
                desiredText
            );

        if (!result) {
            await sleep(350);

            result =
                findAutocompleteResult(
                    doc,
                    input,
                    desiredText
                );
        }

        if (result) {
            realClick(result);

            await sleep(280);
        }

        /*
         * 主动关闭可能残留的人员检索列表。
         */
        input.focus();

        pressKey(
            input,
            'Escape',
            27
        );

        input.blur();

        const win =
            doc.defaultView;

        if (win.jQuery) {
            win.jQuery(input)
                .trigger('change')
                .trigger('blur');
        }

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        await sleep(120);
    }

    async function fillTextField(
        task,
        value
    ) {
        const found =
            findInputByAliases(
                task.aliases
            );

        if (!found) {
            throw new Error(
                '未找到“' +
                task.title +
                '”输入框'
            );
        }

        const input =
            found.input;

        input.scrollIntoView({
            block: 'center',
            behavior: 'auto'
        });

        if (
            normalize(input.value) ===
            normalize(value)
        ) {
            input.blur();

            return value;
        }

        setNativeInputValue(
            found.doc,
            input,
            value,
            {
                focus: true,
                blur: false
            }
        );

        await tryCommitAutocomplete(
            found.doc,
            input,
            value
        );

        /*
         * 检索列表未出现时，直接输入的文字仍然保留。
         */
        if (
            normalize(input.value) !==
            normalize(value)
        ) {
            setNativeInputValue(
                found.doc,
                input,
                value,
                {
                    focus: false,
                    blur: true
                }
            );
        }

        if (
            normalize(input.value) !==
            normalize(value)
        ) {
            throw new Error(
                '写入后被页面修改，当前值：' +
                input.value
            );
        }

        return value;
    }

    /******************************************************************
     * 日期填写
     ******************************************************************/

    async function fillDateField(
        task,
        value
    ) {
        const found =
            findInputByAliases(
                task.aliases
            );

        if (!found) {
            throw new Error(
                '未找到“' +
                task.title +
                '”输入框'
            );
        }

        /*
         * 不主动点击日期输入框，避免弹出日期选择器。
         */
        setNativeInputValue(
            found.doc,
            found.input,
            value,
            {
                focus: false,
                blur: true
            }
        );

        await sleep(150);

        /*
         * 某些日期组件会在第一次change后还原，
         * 因此再次写入。
         */
        setNativeInputValue(
            found.doc,
            found.input,
            value,
            {
                focus: false,
                blur: true
            }
        );

        if (
            normalize(found.input.value) !==
            normalize(value)
        ) {
            throw new Error(
                '日期写入后被页面修改，当前值：' +
                found.input.value
            );
        }

        return value;
    }

    /******************************************************************
     * 下拉框填写
     ******************************************************************/

    function findSelectOption(
        select,
        desiredText,
        fallbackValue
    ) {
        const target =
            normalize(desiredText);

        const options =
            Array.from(
                select.options || []
            );

        let option =
            options.find(function (item) {
                return (
                    normalize(
                        item.textContent
                    ) === target
                );
            });

        if (option) {
            return option;
        }

        /*
         * 支持选项显示为“1.无”“1、无”等形式。
         */
        option =
            options
                .filter(function (item) {
                    const text =
                        normalize(
                            item.textContent
                        );

                    return (
                        text.endsWith(target) ||
                        text.includes(target)
                    );
                })
                .sort(function (a, b) {
                    return (
                        normalize(
                            a.textContent
                        ).length -
                        normalize(
                            b.textContent
                        ).length
                    );
                })[0];

        if (option) {
            return option;
        }

        if (
            fallbackValue !== undefined &&
            fallbackValue !== null
        ) {
            return (
                options.find(function (item) {
                    return (
                        String(item.value) ===
                        String(fallbackValue)
                    );
                }) ||
                null
            );
        }

        return null;
    }

    function triggerSelectValue(
        doc,
        select,
        option
    ) {
        const win =
            doc.defaultView;

        select.value =
            option.value;

        Array.from(
            select.options
        ).forEach(function (item) {
            item.selected =
                item === option;
        });

        if (win.jQuery) {
            const $select =
                win.jQuery(select);

            $select
                .val(option.value)
                .trigger({
                    type: 'select2:select',
                    params: {
                        data: {
                            id: option.value,
                            text: String(
                                option.textContent ||
                                ''
                            ).trim(),
                            element: option
                        }
                    }
                })
                .trigger('change');
        }

        select.dispatchEvent(
            new win.Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        select.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        /*
         * 修正旧版Select2显示文字未同步的问题。
         */
        const visual =
            getSelectVisual(select);

        const rendered =
            visual.querySelector(
                '.select2-selection__rendered'
            );

        if (rendered) {
            const displayText =
                String(
                    option.textContent ||
                    ''
                ).trim();

            rendered.textContent =
                displayText;

            rendered.title =
                displayText;
        }
    }

    async function chooseVisibleOption(
        doc,
        input,
        desiredText
    ) {
        const target =
            normalize(desiredText);

        realClick(input);

        await sleep(220);

        const options =
            Array.from(
                doc.querySelectorAll(
                    [
                        '[role="option"]',
                        '.select2-results__option',
                        '.dropdown-menu li',
                        'option'
                    ].join(',')
                )
            )
                .filter(isVisible)
                .filter(function (element) {
                    const text =
                        normalize(
                            element.innerText ||
                            element.textContent
                        );

                    return (
                        text === target ||
                        text.endsWith(target) ||
                        (
                            text.includes(target) &&
                            text.length <=
                            target.length + 8
                        )
                    );
                });

        if (!options.length) {
            return false;
        }

        const inputRect =
            input.getBoundingClientRect();

        options.sort(function (a, b) {
            const rectA =
                a.getBoundingClientRect();

            const rectB =
                b.getBoundingClientRect();

            const scoreA =
                Math.abs(
                    rectA.left -
                    inputRect.left
                ) +
                Math.abs(
                    rectA.top -
                    inputRect.bottom
                );

            const scoreB =
                Math.abs(
                    rectB.left -
                    inputRect.left
                ) +
                Math.abs(
                    rectB.top -
                    inputRect.bottom
                );

            return scoreA - scoreB;
        });

        realClick(options[0]);

        await sleep(180);

        return true;
    }

    async function fillSelectField(
        task,
        value
    ) {
        const selectFound =
            findSelectByAliases(
                task.aliases
            );

        if (selectFound) {
            const option =
                findSelectOption(
                    selectFound.select,
                    value,
                    task.fallbackValue
                );

            if (!option) {
                const available =
                    Array.from(
                        selectFound.select.options
                    )
                        .map(function (item) {
                            return String(
                                item.textContent ||
                                ''
                            ).trim();
                        })
                        .filter(Boolean)
                        .join('、');

                throw new Error(
                    '下拉框中没有“' +
                    value +
                    '”选项，可选项：' +
                    (
                        available ||
                        '空'
                    )
                );
            }

            triggerSelectValue(
                selectFound.doc,
                selectFound.select,
                option
            );

            await sleep(180);

            if (
                String(
                    selectFound.select.value
                ) !==
                String(option.value)
            ) {
                const visual =
                    getSelectVisual(
                        selectFound.select
                    );

                const clickTarget =
                    visual.querySelector(
                        '.select2-selection'
                    ) ||
                    visual;

                await chooseVisibleOption(
                    selectFound.doc,
                    clickTarget,
                    value
                );
            }

            if (
                String(
                    selectFound.select.value
                ) !==
                String(option.value)
            ) {
                throw new Error(
                    '选项写入后被页面还原'
                );
            }

            return value;
        }

        /*
         * 个别页面使用输入框模拟下拉框。
         */
        const inputFound =
            findInputByAliases(
                task.aliases
            );

        if (!inputFound) {
            throw new Error(
                '未找到“' +
                task.title +
                '”下拉框'
            );
        }

        setNativeInputValue(
            inputFound.doc,
            inputFound.input,
            value,
            {
                focus: true,
                blur: false
            }
        );

        await chooseVisibleOption(
            inputFound.doc,
            inputFound.input,
            value
        );

        inputFound.input.blur();

        if (
            !normalize(
                inputFound.input.value
            ).includes(
                normalize(value)
            )
        ) {
            throw new Error(
                '下拉选项未完成选择，当前值：' +
                inputFound.input.value
            );
        }

        return value;
    }


