    function normalizeInspectionStatus(
        value
    ) {
        const source =
            value &&
            typeof value === 'object'
                ? (
                    value.status ||
                    value.result ||
                    value.value ||
                    ''
                )
                : value;

        const normalized =
            normalize(source);

        if (
            normalized.includes(
                normalize('阳性')
            )
        ) {
            return '阳性';
        }

        if (
            normalized.includes(
                normalize('阴性')
            )
        ) {
            return '阴性';
        }

        if (
            normalized.includes(
                normalize('未做')
            ) ||
            normalized.includes(
                normalize('未检查')
            ) ||
            normalized.includes(
                normalize('未提及')
            )
        ) {
            return '未做';
        }

        return '';
    }

    function extractJsonObject(
        content
    ) {
        const source =
            String(
                content ||
                ''
            )
                .replace(
                    /```(?:json)?/gi,
                    ''
                )
                .replace(
                    /```/g,
                    ''
                )
                .trim();

        try {
            return JSON.parse(
                source
            );
        } catch (error) {
            // 尝试截取首个完整JSON对象。
        }

        const start =
            source.indexOf('{');

        const end =
            source.lastIndexOf('}');

        if (
            start < 0 ||
            end <= start
        ) {
            throw new Error(
                'AI未返回可识别的JSON对象'
            );
        }

        return JSON.parse(
            source.slice(
                start,
                end + 1
            )
        );
    }

    function requestDeepSeek(
        sourceText
    ) {
        const config =
            loadConfig();

        const apiKey =
            String(
                config.deepseekApiKey ||
                ''
            ).trim();

        const model =
            String(
                config.deepseekModel ||
                'deepseek-v4-flash'
            ).trim();

        if (!suiteGlobalAiHasApiKey(apiKey)) {
            return Promise.reject(
                new Error(
                    '尚未配置当前AI服务所需API Key，请先点击“默认值设置”或在悬浮框管理器中配置'
                )
            );
        }

        if (
            typeof GM_xmlhttpRequest !==
            'function'
        ) {
            return Promise.reject(
                new Error(
                    'Tampermonkey未提供GM_xmlhttpRequest，请确认脚本授权后重新安装'
                )
            );
        }

        const systemPrompt = [
            '你是病案首页检查情况分类助手。',
            '请根据用户提供的检查、检验、影像报告文字，仅判断以下8项：CT、PETCT、双源CT、B超、X片、超声心动图、MRI、同位素检查。',
            '每一项只能输出“阳性”“阴性”“未做”之一。',
            '判定规则：',
            '1. 必须有已完成检查的证据，例如报告、检查所见、检查提示、诊断意见或明确写明已做；仅有医嘱、计划、建议、待查、拟查，不算已做。',
            '2. 已完成且存在任一异常所见、病变、结节、狭窄、增厚、积液、退变、梗死、占位等，判为阳性。',
            '3. 已完成且明确未见异常、正常、阴性，且该类别没有其他异常结果，判为阴性。',
            '4. 未提及、无法确认已完成，判为未做。不得推测。',
            '5. 同一类别有多项检查时，只要任一项异常，整体判为阳性；全部明确正常才判为阴性。',
            '6. 血常规、尿常规、肝肾功、血脂、血糖等化验异常，不得据此把任何影像检查判为阳性。',
            '7. 双源CT、PETCT应优先归入其专属类别，不要仅因名称含CT而同时把普通CT判为已做。',
            '8. 普通腹部、甲状腺、颈动脉、下肢血管等超声归入B超；心脏彩超归入超声心动图。',
            '9. SPECT、ECT、骨扫描、核素显像等归入同位素检查。',
            '只返回一个JSON对象，不要输出Markdown或解释。格式必须为：',
            '{',
            '  "CT":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "PETCT":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "双源CT":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "B超":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "X片":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "超声心动图":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "MRI":{"status":"阳性|阴性|未做","basis":"简短依据"},',
            '  "同位素检查":{"status":"阳性|阴性|未做","basis":"简短依据"}',
            '}'
        ].join('\n');

        const payload = {
            model: model,
            messages: [
                {
                    role: 'system',
                    content: systemPrompt
                },
                {
                    role: 'user',
                    content:
                        '请判断以下检查情况：\n\n' +
                        String(
                            sourceText ||
                            ''
                        )
                }
            ],
            temperature: 0,
            stream: false,
            response_format: {
                type: 'json_object'
            }
        };

        return new Promise(
            function (
                resolve,
                reject
            ) {
                suiteGlobalAiXmlhttpRequest({
                    method: 'POST',
                    url: 'https://api.deepseek.com/chat/completions',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization':
                            'Bearer ' +
                            apiKey
                    },
                    data: JSON.stringify(
                        payload
                    ),
                    timeout: 60000,
                    onload: function (response) {
                        let body;

                        try {
                            body = JSON.parse(
                                response.responseText ||
                                '{}'
                            );
                        } catch (error) {
                            reject(
                                new Error(
                                    'DeepSeek返回内容不是有效JSON，HTTP ' +
                                    response.status
                                )
                            );

                            return;
                        }

                        if (
                            response.status < 200 ||
                            response.status >= 300
                        ) {
                            const message =
                                body &&
                                body.error &&
                                body.error.message
                                    ? body.error.message
                                    : (
                                        response.statusText ||
                                        '请求失败'
                                    );

                            reject(
                                new Error(
                                    'DeepSeek API错误（' +
                                    response.status +
                                    '）：' +
                                    message
                                )
                            );

                            return;
                        }

                        const content =
                            body &&
                            body.choices &&
                            body.choices[0] &&
                            body.choices[0].message
                                ? body.choices[0].message.content
                                : '';

                        if (!content) {
                            reject(
                                new Error(
                                    'DeepSeek未返回判断内容'
                                )
                            );

                            return;
                        }

                        try {
                            resolve(
                                extractJsonObject(
                                    content
                                )
                            );
                        } catch (error) {
                            reject(
                                new Error(
                                    '解析DeepSeek结果失败：' +
                                    error.message
                                )
                            );
                        }
                    },
                    onerror: function () {
                        reject(
                            new Error(
                                'DeepSeek网络请求失败，请检查网络、API Key或代理设置'
                            )
                        );
                    },
                    ontimeout: function () {
                        reject(
                            new Error(
                                'DeepSeek请求超时'
                            )
                        );
                    }
                });
            }
        );
    }

    function getInspectionBasis(
        aiResult,
        key
    ) {
        const value =
            aiResult &&
            aiResult[key];

        if (
            value &&
            typeof value === 'object'
        ) {
            return String(
                value.basis ||
                value.reason ||
                ''
            ).trim();
        }

        return '';
    }

    async function fillInspectionStatusByAI(
        sourceText
    ) {
        const textValue =
            String(
                sourceText ||
                ''
            ).trim();

        if (!textValue) {
            throw new Error(
                '请先在弹窗中粘贴检查或化验结果'
            );
        }

        showStatus(
            '正在调用DeepSeek分析检查情况……'
        );

        const aiResult =
            await requestDeepSeek(
                textValue
            );

        const success = [];
        const failed = [];

        for (
            const field of
            INSPECTION_STATUS_FIELDS
        ) {
            const status =
                normalizeInspectionStatus(
                    aiResult[field.key]
                );

            if (!status) {
                failed.push(
                    field.title +
                    '：AI返回值无效'
                );

                continue;
            }

            const task = {
                title: field.title,
                aliases: field.aliases,
                fallbackValue:
                    status === '阳性'
                        ? '1'
                        : status === '阴性'
                            ? '2'
                            : '3'
            };

            try {
                await fillSelectField(
                    task,
                    status
                );

                const basis =
                    getInspectionBasis(
                        aiResult,
                        field.key
                    );

                success.push(
                    field.title +
                    '：' +
                    status +
                    (
                        basis
                            ? '（' + basis + '）'
                            : ''
                    )
                );
            } catch (error) {
                failed.push(
                    field.title +
                    '：' +
                    error.message
                );
            }

            await sleep(160);
        }

        if (failed.length) {
            throw new Error(
                '部分项目填写失败：' +
                failed.join('；') +
                (
                    success.length
                        ? '。已填写：' +
                          success.join('；')
                        : ''
                )
            );
        }

        return success.join('；');
    }

    /******************************************************************
     * 尝试切换至住院信息标签页
     ******************************************************************/

    async function activateInpatientInfoTab() {
        const candidates = [];

        for (
            const doc of
            getAllDocuments()
        ) {
            const elements =
                Array.from(
                    doc.querySelectorAll(
                        'a,li,[role="tab"],span,div'
                    )
                )
                    .filter(isVisible)
                    .filter(function (element) {
                        return (
                            normalize(
                                element.innerText ||
                                element.textContent
                            ) ===
                            normalize('住院信息')
                        );
                    });

            elements.forEach(function (element) {
                const rect =
                    element.getBoundingClientRect();

                candidates.push({
                    element: element,
                    score:
                        rect.top +
                        rect.left / 20 +
                        rect.width * rect.height / 1000
                });
            });
        }

        if (!candidates.length) {
            return false;
        }

        candidates.sort(function (a, b) {
            return a.score - b.score;
        });

        const tab =
            candidates[0].element;

        const classText =
            String(
                tab.className ||
                ''
            ).toLowerCase();

        const parentClass =
            String(
                tab.parentElement
                    ? tab.parentElement.className
                    : ''
            ).toLowerCase();

        const alreadyActive =
            /active|selected|current/.test(
                classText + ' ' + parentClass
            );

        if (!alreadyActive) {
            realClick(tab);

            await sleep(500);
        }

        return true;
    }

    /******************************************************************
     * 状态提示
     ******************************************************************/

    function showStatus(
        message,
        type
    ) {
        const messageType =
            type || 'normal';

        let box =
            document.getElementById(
                STATUS_ID
            );

        if (!box) {
            box =
                document.createElement(
                    'div'
                );

            box.id =
                STATUS_ID;

            document.body.appendChild(
                box
            );
        }

        const colors = {
            normal: '#159bd3',
            success: '#20985b',
            error: '#dc4c40'
        };

        Object.assign(
            box.style,
            {
                position: 'fixed',
                right: '20px',
                bottom: '126px',
                zIndex: '2147483647',
                minWidth: '310px',
                maxWidth: '680px',
                padding: '12px 15px',
                borderRadius: '6px',
                background:
                    colors[messageType] ||
                    colors.normal,
                color: '#ffffff',
                fontSize: '13px',
                lineHeight: '1.7',
                whiteSpace: 'pre-line',
                boxShadow:
                    '0 4px 15px rgba(0,0,0,.28)'
            }
        );

        box.textContent =
            message;

        clearTimeout(
            box.hideTimer
        );

        box.hideTimer =
            setTimeout(
                function () {
                    box.remove();
                },
                messageType === 'error'
                    ? 15000
                    : 7000
            );
    }

    /******************************************************************
     * 勾选项目存储
     ******************************************************************/

    function loadSelections() {
        const defaults = {};

        TASKS.forEach(function (task) {
            defaults[task.key] =
                task.defaultSelected !== false;
        });

        try {
            return Object.assign(
                defaults,
                JSON.parse(
                    localStorage.getItem(
                        STORAGE_KEY
                    ) ||
                    '{}'
                )
            );
        } catch (error) {
            return defaults;
        }
    }

    function saveSelections(
        selections
    ) {
        try {
            localStorage.setItem(
                STORAGE_KEY,
                JSON.stringify(
                    selections
                )
            );
        } catch (error) {
            // 本地存储失败不影响自动填写。
        }
    }

    function syncSelectAll(
        modal
    ) {
        const boxes =
            Array.from(
                modal.querySelectorAll(
                    '.inpatient-category-checkbox'
                )
            );

        const selectAll =
            modal.querySelector(
                '#inpatient-select-all'
            );

        const checkedCount =
            boxes.filter(function (box) {
                return box.checked;
            }).length;

        selectAll.checked =
            checkedCount === boxes.length;

        selectAll.indeterminate =
            checkedCount > 0 &&
            checkedCount < boxes.length;
    }

