    function populateSettingsModal(
        modal,
        config
    ) {
        SETTINGS_FIELDS.forEach(
            function (field) {
                const input =
                    modal.querySelector(
                        '[data-config-key="' +
                        field.key +
                        '"]'
                    );

                if (!input) {
                    return;
                }

                if (field.type === 'checkbox') {
                    input.checked =
                        Boolean(
                            config[field.key]
                        );
                } else {
                    input.value =
                        config[field.key];
                }
            }
        );
    }

    function collectSettingsValues(
        modal
    ) {
        const config = {};

        SETTINGS_FIELDS.forEach(
            function (field) {
                const input =
                    modal.querySelector(
                        '[data-config-key="' +
                        field.key +
                        '"]'
                    );

                if (!input) {
                    return;
                }

                if (field.type === 'number') {
                    config[field.key] =
                        Number(input.value);
                } else if (
                    field.type === 'checkbox'
                ) {
                    config[field.key] =
                        Boolean(input.checked);
                } else {
                    config[field.key] =
                        String(
                            input.value ||
                            ''
                        ).trim();
                }
            }
        );

        return normalizeConfig(
            config
        );
    }

    function validateSettings(
        config
    ) {
        const requiredKeys = [
            'departmentDirector',
            'chiefPhysician',
            'primaryPhysician',
            'attendingPhysician',
            'residentPhysician',
            'qualityDoctor',
            'qualityNurse',
            'responsibleNurse',
            'coder',
            'readmissionPlan'
        ];

        const emptyKey =
            requiredKeys.find(
                function (key) {
                    return !config[key];
                }
            );

        if (emptyKey) {
            const field =
                SETTINGS_FIELDS.find(
                    function (item) {
                        return item.key ===
                            emptyKey;
                    }
                );

            throw new Error(
                '“' +
                (
                    field
                        ? field.label
                        : emptyKey
                ) +
                '”不能为空'
            );
        }

        if (
            !Number.isFinite(
                Number(
                    config.qualityDateOffsetDays
                )
            )
        ) {
            throw new Error(
                '质控日期偏移天数必须是整数'
            );
        }
    }

    function createSettingsModal() {
        let modal =
            document.getElementById(
                SETTINGS_MODAL_ID
            );

        if (modal) {
            populateSettingsModal(
                modal,
                loadConfig()
            );

            return modal;
        }

        ensureSettingsStyle();

        modal =
            document.createElement(
                'div'
            );

        modal.id =
            SETTINGS_MODAL_ID;

        const fieldsHtml =
            SETTINGS_FIELDS.map(
                function (field) {
                    let controlHtml = '';

                    if (field.type === 'select') {
                        const optionsHtml =
                            (field.options || [])
                                .map(function (option) {
                                    return (
                                        '<option value="' +
                                        String(option.value || '') +
                                        '">' +
                                        String(option.label || option.value || '') +
                                        '</option>'
                                    );
                                })
                                .join('');

                        controlHtml =
                            '<select ' +
                                'class="inpatient-settings-input" ' +
                                'data-config-key="' +
                                    field.key +
                                '">' +
                                optionsHtml +
                            '</select>';
                    } else if (
                        field.type === 'checkbox'
                    ) {
                        controlHtml =
                            '<label class="inpatient-settings-checkbox-row">' +
                                '<input ' +
                                    'class="inpatient-settings-checkbox" ' +
                                    'type="checkbox" ' +
                                    'data-config-key="' +
                                        field.key +
                                    '"' +
                                '>' +
                                '<span>启用</span>' +
                            '</label>';
                    } else {
                        controlHtml =
                            '<input ' +
                                'class="inpatient-settings-input" ' +
                                'type="' +
                                    field.type +
                                '" ' +
                                'data-config-key="' +
                                    field.key +
                                '"' +
                            '>';
                    }

                    return (
                        '<label class="inpatient-settings-field">' +
                            '<span class="inpatient-settings-label">' +
                                field.label +
                            '</span>' +
                            controlHtml +
                            '<span class="inpatient-settings-hint">' +
                                (
                                    field.hint ||
                                    '请输入医院系统中实际显示的人员姓名'
                                ) +
                            '</span>' +
                        '</label>'
                    );
                }
            ).join('');

        modal.innerHTML =
            '<div class="inpatient-settings-mask"></div>' +
            '<div class="inpatient-settings-dialog">' +
                '<div class="inpatient-settings-header">' +
                    '<span>住院信息默认值设置</span>' +
                    '<button type="button" class="inpatient-settings-close">×</button>' +
                '</div>' +
                '<div class="inpatient-settings-body">' +
                    '<div class="inpatient-settings-grid">' +
                        fieldsHtml +
                    '</div>' +
                    '<div class="inpatient-settings-note">' +
                        '设置保存在当前浏览器。v2.38默认使用“自动”AI病历模式：首次病程、病程正文、出院记录、病情告知书直接deepseek-chat生成，避免先消耗大量推理Token再降级；病程日期规划仍使用上方DeepSeek模型。Token范围4000～24000。' +
                    '</div>' +
                '</div>' +
                '<div class="inpatient-settings-footer">' +
                    '<button type="button" class="inpatient-settings-reset">恢复初始值</button>' +
                    '<div class="inpatient-settings-footer-right">' +
                        '<button type="button" class="inpatient-settings-cancel">取消</button>' +
                        '<button type="button" class="inpatient-settings-save">保存设置</button>' +
                    '</div>' +
                '</div>' +
            '</div>';

        document.body.appendChild(
            modal
        );

        const closeModal =
            function () {
                modal.classList.remove(
                    'show'
                );
            };

        modal.querySelector(
            '.inpatient-settings-close'
        ).addEventListener(
            'click',
            closeModal
        );

        modal.querySelector(
            '.inpatient-settings-cancel'
        ).addEventListener(
            'click',
            closeModal
        );

        modal.querySelector(
            '.inpatient-settings-mask'
        ).addEventListener(
            'click',
            closeModal
        );

        modal.querySelector(
            '.inpatient-settings-save'
        ).addEventListener(
            'click',
            function () {
                try {
                    const config =
                        collectSettingsValues(
                            modal
                        );

                    validateSettings(
                        config
                    );

                    saveConfig(
                        config
                    );

                    const oldMainModal =
                        document.getElementById(
                            MODAL_ID
                        );

                    if (oldMainModal) {
                        oldMainModal.remove();
                    }

                    closeModal();

                    showStatus(
                        '默认值设置已保存。责任护士：' +
                        config.responsibleNurse +
                        '；编码员：' +
                        config.coder +
                        '；AI病历模式：' +
                        medicalAiModeLabel(
                            config.medicalAiMode
                        ) +
                        '；正文Token：' +
                        config.medicalAiPlainMaxTokens +
                        '；重试Token：' +
                        config.medicalAiRetryMaxTokens,
                        'success'
                    );
                } catch (error) {
                    showStatus(
                        '保存设置失败：' +
                        error.message,
                        'error'
                    );
                }
            }
        );

        modal.querySelector(
            '.inpatient-settings-reset'
        ).addEventListener(
            'click',
            function () {
                const confirmed =
                    window.confirm(
                        '确定恢复脚本初始默认值吗？'
                    );

                if (!confirmed) {
                    return;
                }

                const config =
                    resetConfig();

                populateSettingsModal(
                    modal,
                    config
                );

                const oldMainModal =
                    document.getElementById(
                        MODAL_ID
                    );

                if (oldMainModal) {
                    oldMainModal.remove();
                }

                showStatus(
                    '已恢复脚本初始默认值。',
                    'success'
                );
            }
        );

        populateSettingsModal(
            modal,
            loadConfig()
        );

        return modal;
    }

    function openSettingsModal() {
        const modal =
            createSettingsModal();

        populateSettingsModal(
            modal,
            loadConfig()
        );

        /*
         * 主窗口与默认值设置均使用z-index:2147483647。
         * 若设置窗口更早创建，而主窗口后创建，同层级时后者会覆盖前者。
         *
         * 每次打开设置都把同一个节点重新append到body末尾，
         * 使其成为当前document中最后的同级fixed层，从而稳定显示在主窗口上方。
         * append已有节点只会移动位置，不会复制节点，也不会丢失事件监听。
         */
        if (
            modal.parentNode !==
                document.body ||
            document.body.lastElementChild !==
                modal
        ) {
            document.body.appendChild(
                modal
            );
        }

        modal.classList.add(
            'show'
        );
    }

