    function loadProgressVitalSignsCacheStore() {
        return inpatientLargeCacheReadStore(
            PROGRESS_VITAL_SIGNS_CACHE_STORAGE_KEY
        );
    }

    function saveProgressVitalSignsCache(entry) {
        const identity = entry && entry.identity || {};
        const key = patientIdentityKey(identity);

        if (!key) {
            throw new Error('无法生成三测单患者缓存键');
        }

        const store = loadProgressVitalSignsCacheStore();
        const previous = store[key] && typeof store[key] === 'object'
            ? store[key]
            : {};

        store[key] = Object.assign(
            {},
            previous,
            entry,
            {
                identity: identity,
                schemaVersion: 1
            }
        );

        inpatientLargeCacheWriteStore(
            PROGRESS_VITAL_SIGNS_CACHE_STORAGE_KEY,
            store
        );

        return store[key];
    }

    function findProgressVitalSignsCache(identity) {
        const store = loadProgressVitalSignsCacheStore();
        const directKey = patientIdentityKey(identity);

        if (directKey && store[directKey]) {
            return store[directKey];
        }

        return Object.keys(store)
            .map(function (key) {
                return store[key];
            })
            .find(function (entry) {
                return entry &&
                    patientIdentityMatches(
                        entry.identity,
                        identity
                    );
            }) || null;
    }

    function clearProgressVitalSignsCache(identity) {
        const store = loadProgressVitalSignsCacheStore();
        const directKey = patientIdentityKey(identity);
        let changed = false;

        Object.keys(store).forEach(function (key) {
            const entry = store[key];
            if (
                (directKey && key === directKey) ||
                (entry && patientIdentityMatches(entry.identity, identity))
            ) {
                delete store[key];
                changed = true;
            }
        });

        if (changed) {
            inpatientLargeCacheWriteStore(
                PROGRESS_VITAL_SIGNS_CACHE_STORAGE_KEY,
                store
            );
        }

        return changed;
    }

    function loadProgressLisPacsCacheStore() {
        return inpatientLargeCacheReadStore(PROGRESS_LIS_PACS_CACHE_STORAGE_KEY);
    }

    function findProgressLisPacsCache(identity) {
        const no = progressPlain(identity && identity.inpatientNo);
        if (!no) return null;
        const store = loadProgressLisPacsCacheStore();
        const direct = store[patientIdentityKey(identity)];
        if (direct && progressLisPacsPacsAdmissionMatches(
            direct.identity && direct.identity.inpatientNo, no
        )) return direct;
        return Object.values(store).find(function (entry) {
            return entry && progressLisPacsPacsAdmissionMatches(
                entry.identity && entry.identity.inpatientNo, no
            );
        }) || null;
    }

    function saveProgressLisPacsCache(entry) {
        const identity = entry && entry.identity || {};
        const no = progressPlain(identity.inpatientNo);
        if (!no) throw new Error('LIS/PACS缓存必须具有住院号');
        const store = loadProgressLisPacsCacheStore();
        const key = patientIdentityKey(identity);
        const previous = findProgressLisPacsCache(identity);
        if (previous) {
            Object.keys(store).forEach(function (oldKey) {
                if (store[oldKey] === previous && oldKey !== key) delete store[oldKey];
            });
        }
        store[key] = Object.assign({}, previous || {}, entry, {
            identity: identity, schemaVersion: 1
        });
        inpatientLargeCacheWriteStore(PROGRESS_LIS_PACS_CACHE_STORAGE_KEY, store);
        return store[key];
    }

    function clearProgressLisPacsCache(identity) {
        const no = progressPlain(identity && identity.inpatientNo);
        if (!no) throw new Error('请先锁定有住院号的患者');
        const store = loadProgressLisPacsCacheStore();
        let changed = false;
        Object.keys(store).forEach(function (key) {
            const entry = store[key];
            if (entry && progressLisPacsPacsAdmissionMatches(
                entry.identity && entry.identity.inpatientNo, no
            )) {
                delete store[key];
                changed = true;
            }
        });
        if (changed) inpatientLargeCacheWriteStore(
            PROGRESS_LIS_PACS_CACHE_STORAGE_KEY, store
        );
        return changed;
    }

    function progressPlain(value) {
        return String(value == null ? '' : value)
            .replace(/\u00a0/g, ' ')
            .replace(/\r/g, '')
            .replace(/[ \t]+/g, ' ')
            .trim();
    }

    function progressNormalize(value) {
        return progressPlain(value)
            .replace(/\s+/g, '')
            .replace(/[：:，,。；;（）()【】\[\]\/\\|｜_-]+/g, '')
            .toLowerCase();
    }

