    /*
     * 所有后创建的AI窗口都通过事件委托响应同一全局开关。
     * 因此在任意一个模块修改后，已经打开的其他模块会立即同步显示。
     */
    document.addEventListener('change', function (event) {
        const target = event && event.target;
        if (
            !target ||
            !target.matches ||
            !target.matches('.inpatient-filter-voided-temp-orders')
        ) {
            return;
        }

        const enabled = Boolean(target.checked);
        inpatientSaveFilterVoidedTemporaryOrders(enabled);
        inpatientSyncFilterVoidedTemporaryOrderCheckboxes(enabled);

        showStatus(
            '过滤临时作废医嘱：' +
            (enabled ? '已开启' : '已关闭') +
            '。后续DOM提取和HIS接口读取将按此设置生成新的医嘱缓存。',
            'success'
        );
    });

    document.addEventListener('change', function (event) {
        const target = event && event.target;
        if (
            !target || !target.matches ||
            !target.matches('.inpatient-filter-no-print-orders')
        ) return;
        const enabled = Boolean(target.checked);
        inpatientSaveFilterNoPrintOrders(enabled);
        inpatientSyncFilterNoPrintOrderCheckboxes(enabled);
        showStatus(
            '过滤不打印医嘱：' + (enabled ? '已开启' : '已关闭') +
            '并已记忆。后续HIS接口或包含“不打印”列的DOM提取生成新缓存时生效；已有缓存不自动改写。',
            'success'
        );
    });

    document.addEventListener('change', function (event) {
        const target = event && event.target;
        if (
            !target || !target.matches ||
            !target.matches('.inpatient-filter-custom-orders')
        ) return;
        const enabled = Boolean(target.checked);
        inpatientSaveFilterCustomOrders(enabled);
        inpatientSyncFilterCustomOrderCheckboxes(enabled);
        showStatus(
            '过滤自定义医嘱：' + (enabled ? '已开启' : '已关闭') +
            '并已记忆。后续HIS接口或DOM提取生成新缓存时按自定义规则生效；已有缓存不自动改写。',
            'success'
        );
    });

    document.addEventListener('change', function (event) {
        const target = event && event.target;
        if (
            !target ||
            !target.matches ||
            !target.matches('.inpatient-include-pending-orders')
        ) {
            return;
        }

        const enabled = Boolean(target.checked);
        inpatientSaveIncludePendingOrders(enabled);
        inpatientSyncIncludePendingOrderCheckboxes(enabled);

        showStatus(
            '包含待审核医嘱：' +
            (enabled ? '已开启' : '已关闭') +
            '并已独立记忆。后续DOM提取/HIS接口读取生成新缓存时生效；已有缓存不会自动改写。',
            'success'
        );
    });

    window.addEventListener('storage', function (event) {
        if (!event) return;
        if (
            event.key === INPATIENT_FILTER_VOIDED_TEMPORARY_ORDERS_STORAGE_KEY
        ) {
            inpatientSyncFilterVoidedTemporaryOrderCheckboxes(
                inpatientLoadFilterVoidedTemporaryOrders()
            );
        }
        if (
            event.key === INPATIENT_INCLUDE_PENDING_ORDERS_STORAGE_KEY
        ) {
            inpatientSyncIncludePendingOrderCheckboxes(
                inpatientLoadIncludePendingOrders()
            );
        }
        if (event.key === INPATIENT_FILTER_NO_PRINT_ORDERS_STORAGE_KEY) {
            inpatientSyncFilterNoPrintOrderCheckboxes(
                inpatientLoadFilterNoPrintOrders()
            );
        }
        if (event.key === INPATIENT_FILTER_CUSTOM_ORDERS_STORAGE_KEY) {
            inpatientSyncFilterCustomOrderCheckboxes(
                inpatientLoadFilterCustomOrders()
            );
        }
    });

    function progressOrderIsTemporary(record) {
        const category = progressPlain(
            record && record.orderCategory
        );

        return /临|临时/.test(category) && !/长|长期/.test(category);
    }

    function progressOrderIsPendingReview(record) {
        if (record && record._pendingReview === true) return true;

        /*
         * DOM路径仍可依据页面明确显示的“未审核/待审核”识别；接口路径
         * 则由wsh=true分支写入_pendingReview。yzlx不再参与审核判断。
         */
        const status = progressNormalize(
            record && record.status
        );
        return status === progressNormalize('未审核') ||
            status === progressNormalize('待审核');
    }

    function progressFilterPendingReviewRecords(records, enabledOverride) {
        const source = Array.isArray(records) ? records : [];
        const enabled = typeof enabledOverride === 'boolean'
            ? enabledOverride
            : inpatientLoadIncludePendingOrders();

        if (enabled) {
            return {
                enabled: true,
                records: source.slice(),
                filteredCount: 0
            };
        }

        const kept = [];
        let filteredCount = 0;
        source.forEach(function (record) {
            if (progressOrderIsPendingReview(record)) {
                filteredCount += 1;
                return;
            }
            kept.push(record);
        });

        return {
            enabled: false,
            records: kept,
            filteredCount: filteredCount
        };
    }

    function progressOrderIsVoidedTemporary(record) {
        if (!progressOrderIsTemporary(record)) {
            return false;
        }

        if (record && record._voidedTemporaryByClinicalPath) {
            return true;
        }

        const normalizedStatus = progressNormalize(
            record && record.status
        );

        /*
         * 本院HIS实测：临时医嘱状态4表示停止/作废。
         * 同时兼容页面/接口直接返回“作废”“已作废”的情况。
         * 不使用模糊includes('作废')，避免把“未作废”误判为作废。
         */
        return (
            normalizedStatus === '4' ||
            normalizedStatus === progressNormalize('作废') ||
            normalizedStatus === progressNormalize('已作废')
        );
    }

    function progressFilterVoidedTemporaryRecords(records, enabledOverride) {
        const source = Array.isArray(records) ? records : [];
        const enabled = typeof enabledOverride === 'boolean'
            ? enabledOverride
            : inpatientLoadFilterVoidedTemporaryOrders();

        if (!enabled) {
            return {
                enabled: false,
                records: source.slice(),
                filteredCount: 0
            };
        }

        const kept = [];
        let filteredCount = 0;

        source.forEach(function (record) {
            if (progressOrderIsVoidedTemporary(record)) {
                filteredCount += 1;
                return;
            }
            kept.push(record);
        });

        return {
            enabled: true,
            records: kept,
            filteredCount: filteredCount
        };
    }

    /* 自定义医嘱过滤：一行一条；只把 * / ＊ 解释为通配符，其余按名称文字处理。 */
    const MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY = 'medicalSuiteCustomOrderPatternsV1';

    function medicalOrderLoadSharedPatterns() {
        const shared = localStorage.getItem(MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY);
        if (shared !== null) return medicalOrderFilterNormalizePatterns(shared);
        let patient = {};
        try { patient = JSON.parse(localStorage.getItem('medicalPatientRoundBookProgramPreprocessV1') || '{}') || {}; } catch (error) { /* 使用另一脚本已有规则。 */ }
        return medicalOrderFilterNormalizePatterns(patient.customOrderPatterns ||
            localStorage.getItem('medicalInpatientCustomOrderPatternsV1') || '');
    }

    function medicalOrderNotifySharedPatterns() {
        if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function' && typeof CustomEvent === 'function') {
            window.dispatchEvent(new CustomEvent('medical-suite-custom-order-patterns-change'));
        }
    }

    function medicalOrderSaveSharedPatterns(value) {
        const patterns = medicalOrderFilterNormalizePatterns(value);
        localStorage.setItem(MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY, patterns);
        /* 保留旧键镜像，让单独部署与旧配置恢复仍可衔接。过滤开关各自保存。 */
        localStorage.setItem('medicalInpatientCustomOrderPatternsV1', patterns);
        let patient = {};
        try { patient = JSON.parse(localStorage.getItem('medicalPatientRoundBookProgramPreprocessV1') || '{}') || {}; } catch (error) { /* 仅重建轻量配置。 */ }
        if (typeof patient !== 'object' || Array.isArray(patient)) patient = {};
        patient.customOrderPatterns = patterns;
        patient.updatedAt = Date.now();
        localStorage.setItem('medicalPatientRoundBookProgramPreprocessV1', JSON.stringify(patient));
        medicalOrderNotifySharedPatterns();
        return patterns;
    }

    function medicalOrderRestoreSharedPatterns(local) {
        const values = local && typeof local === 'object' ? local : {};
        const has = function (key) { return Object.prototype.hasOwnProperty.call(values, key); };
        if (has(MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY)) {
            medicalOrderSaveSharedPatterns(values[MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY]);
        } else if (has('medicalPatientRoundBookProgramPreprocessV1')) {
            try {
                const config = JSON.parse(values.medicalPatientRoundBookProgramPreprocessV1 || '{}');
                if (config && Object.prototype.hasOwnProperty.call(config, 'customOrderPatterns')) medicalOrderSaveSharedPatterns(config.customOrderPatterns);
            } catch (error) { /* 无效旧配置不覆盖现有规则。 */ }
        } else if (has('medicalInpatientCustomOrderPatternsV1')) {
            medicalOrderSaveSharedPatterns(values.medicalInpatientCustomOrderPatternsV1);
        }
    }

    window.addEventListener('storage', function (event) {
        if (event.key === MEDICAL_CUSTOM_ORDER_PATTERNS_STORAGE_KEY || event.key === null) medicalOrderNotifySharedPatterns();
    });

    function medicalOrderFilterNormalizeName(value) {
        return String(value == null ? '' : value)
            .replace(/[★☆]/g, '')
            .replace(/[（）()【】\[\]{}]/g, '')
            .replace(/[\s·•・,，;；:：\/\\_\-]+/g, '')
            .toLowerCase();
    }

    function medicalOrderFilterNormalizePatterns(value) {
        return Array.from(new Set(String(value == null ? '' : value)
            .replace(/\r\n?/g, '\n').split('\n')
            .map(function (line) { return line.trim().replace(/＊/g, '*'); })
            .filter(Boolean))).join('\n');
    }

    function medicalOrderFilterFieldSpecs() {
        return [
            { key: 'name', label: '医嘱名称', aliases: ['名称', '项目名称'] },
            { key: 'route', label: '用法', aliases: ['给药途径'] },
            { key: 'dose', label: '剂量', aliases: ['每次剂量', '每次治疗量'] },
            { key: 'spec', label: '药品规格', aliases: ['规格'] },
            { key: 'frequency', label: '频次', aliases: ['频率'] },
            { key: 'doctor', label: '医生', aliases: ['开立医生', '医师'] },
            { key: 'department', label: '执行科室', aliases: ['科室'] },
            { key: 'groupNo', label: '同组', aliases: ['组号', '组别'] },
            { key: 'orderCategory', label: '医嘱类别', aliases: ['长临', '长临嘱'] },
            { key: 'orderType', label: '医嘱类型', aliases: ['类型'] },
            { key: 'startTime', label: '开始时间', aliases: ['开立时间'] },
            { key: 'stopTime', label: '停止时间', aliases: ['停嘱时间', '结束时间'] },
            { key: 'stopDoctor', label: '停止医生', aliases: ['停嘱医生'] },
            { key: 'executor', label: '执行者', aliases: ['执行人'] },
            { key: 'controlled', label: '精麻', aliases: [] },
            { key: 'total', label: '药品总量', aliases: ['总量', '数量'] },
            { key: 'billing', label: '计费', aliases: [] },
            { key: 'skinTest', label: '皮试', aliases: [] },
            { key: 'selfPay', label: '转自费', aliases: [] },
            { key: 'source', label: '药品来源', aliases: ['来源'] },
            { key: 'lastExecutionTime', label: '最后执行时间', aliases: ['末次执行时间'] },
            { key: 'noPrint', label: '不打印', aliases: ['不打印医嘱'] },
            { key: 'status', label: '状态', aliases: ['执行状态', '同步状态'] }
        ];
    }

    function medicalOrderFilterParsePattern(pattern) {
        const original = String(pattern == null ? '' : pattern).trim().replace(/＊/g, '*');
        let field = 'name';
        let value = original;
        if (/^[\[［]/.test(original)) {
            const prefix = original.match(/^[\[［]([^\]］\r\n]*)[\]］]\s*([\s\S]*)$/);
            if (!prefix) return { pattern: original, error: '字段前缀格式不完整' };
            const fieldName = medicalOrderFilterNormalizeName(prefix[1]);
            const spec = medicalOrderFilterFieldSpecs().find(function (item) {
                return [item.key, item.label].concat(item.aliases).some(function (alias) {
                    return medicalOrderFilterNormalizeName(alias) === fieldName;
                });
            });
            if (!spec) return { pattern: original, error: '不支持的字段：' + prefix[1] };
            field = spec.key;
            value = prefix[2].trim();
            const quotePairs = { '"': '"', "'": "'", '“': '”', '‘': '’' };
            const endQuote = quotePairs[value.charAt(0)];
            if (endQuote) {
                if (value.length < 2 || value.charAt(value.length - 1) !== endQuote) {
                    return { pattern: original, error: '匹配内容的引号未配对' };
                }
                value = value.slice(1, -1).trim();
            }
        }
        if (!value || !medicalOrderFilterNormalizeName(value.replace(/\*/g, '')) && value.indexOf('*') < 0) {
            return { pattern: original, error: '匹配内容为空' };
        }
        return { pattern: original, field: field, value: value, error: '' };
    }

    function medicalOrderFilterCompilePatterns(value) {
        const text = medicalOrderFilterNormalizePatterns(value);
        const cache = medicalOrderFilterCompilePatterns._cache;
        if (cache && cache.text === text) return cache.rules;
        const rules = text ? text.split('\n').map(function (pattern) {
            const parsed = medicalOrderFilterParsePattern(pattern);
            if (parsed.error) return null;
            const wildcard = parsed.value.indexOf('*') >= 0;
            const exactKey = wildcard ? '' : medicalOrderFilterNormalizeName(parsed.value);
            const parts = parsed.value.split('*').map(function (part) {
                return medicalOrderFilterNormalizeName(part)
                    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            });
            return {
                pattern: parsed.pattern,
                field: parsed.field,
                exactKey: exactKey,
                regex: wildcard ? new RegExp('^' + parts.join('.*') + '$', 'i') : null
            };
        }).filter(function (rule) { return rule && (rule.regex || rule.exactKey); }) : [];
        medicalOrderFilterCompilePatterns._cache = { text: text, rules: rules };
        return rules;
    }

    function medicalOrderFilterFindRule(record, patterns) {
        const source = record && typeof record === 'object' && !Array.isArray(record)
            ? record : { name: record };
        const match = medicalOrderFilterCompilePatterns(patterns).find(function (rule) {
            const value = source[rule.field];
            if (value === null || value === undefined || typeof value === 'object') return false;
            const key = medicalOrderFilterNormalizeName(value);
            if (!key) return false;
            return rule.regex ? rule.regex.test(key) : rule.exactKey === key;
        });
        return match ? match.pattern : '';
    }


    function medicalOpenCustomOrderFilterSettings(options) {
        const settings = options || {};
        const old = document.getElementById(settings.id);
        if (old && typeof old._closeCustomOrderFilter === 'function') old._closeCustomOrderFilter();
        else if (old) old.remove();
        const previousFocus = document.activeElement;
        const layer = document.createElement('div');
        layer.id = settings.id;
        layer.setAttribute('role', 'dialog');
        layer.setAttribute('aria-modal', 'true');
        layer.setAttribute('aria-label', '自定义医嘱过滤设置');
        layer.style.cssText = 'position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.46);font-family:"Microsoft YaHei",Arial,sans-serif;';
        layer.innerHTML =
            '<div class="custom-order-filter-dialog" style="width:min(760px,calc(100vw - 28px));height:min(620px,calc(100vh - 28px));display:flex;flex-direction:column;overflow:hidden;background:#fff;border-radius:8px;box-shadow:0 12px 42px rgba(0,0,0,.35);">' +
                '<div style="flex:none;display:flex;align-items:center;justify-content:space-between;padding:13px 16px;background:#159bd3;color:#fff;"><strong class="custom-order-filter-title"></strong><button type="button" class="custom-order-filter-close" aria-label="关闭" style="border:0;background:transparent;color:#fff;font-size:26px;cursor:pointer;">×</button></div>' +
                '<div style="display:flex;flex:1;min-height:0;flex-direction:column;gap:10px;padding:14px;overflow:auto;">' +
                    '<div style="font-size:13px;line-height:1.7;color:#475569;">一行填写一条规则。<b>不加 [字段]</b> 时沿用原医嘱名称匹配：不带 * 为完整名称精确匹配，带 * 为名称通配匹配。<b>加 [字段]</b> 后仅检索指定字段，例如 <code>[用法]“领药”</code> 精确匹配用法，<code>[用法]“*领药*”</code> 匹配用法中包含“领药”的医嘱。内容可用中文或英文引号包围，也可省略引号。<b>*</b>（也支持全角＊）代表零个或任意多个字符；忽略空格、大小写及部分标点。多条规则任意一条命中即过滤。</div>' +
                    '<details style="font-size:12px;line-height:1.7;color:#64748b;"><summary style="cursor:pointer;">可用字段</summary><div class="custom-order-filter-fields"></div></details>' +
                    '<textarea class="custom-order-filter-patterns" aria-label="自定义医嘱规则" spellcheck="false" style="box-sizing:border-box;width:100%;flex:1;min-height:160px;resize:none;border:1px solid #b9d9e7;border-radius:6px;padding:10px;font:13px/1.7 Consolas,\'Microsoft YaHei\',monospace;"></textarea>' +
                    '<div class="custom-order-filter-status" aria-live="polite" style="min-height:20px;color:#475569;font-size:12px;line-height:1.6;"></div>' +
                    '<div class="custom-order-filter-hint" style="font-size:12px;line-height:1.6;color:#64748b;"></div>' +
                    '<div style="display:flex;justify-content:flex-end;gap:8px;"><button type="button" class="custom-order-filter-cancel" style="height:34px;padding:0 16px;border:1px solid #cbd5e1;border-radius:5px;background:#fff;color:#475569;cursor:pointer;">取消</button><button type="button" class="custom-order-filter-save" style="height:34px;padding:0 16px;border:1px solid #159bd3;border-radius:5px;background:#159bd3;color:#fff;cursor:pointer;">保存规则</button></div>' +
                '</div>' +
            '</div>';
        layer.querySelector('.custom-order-filter-title').textContent = settings.title || '自定义医嘱过滤设置';
        layer.querySelector('.custom-order-filter-hint').textContent = settings.hint || '';
        layer.querySelector('.custom-order-filter-fields').textContent = medicalOrderFilterFieldSpecs().map(function (field) { return field.label; }).join('、');
        const editor = layer.querySelector('.custom-order-filter-patterns');
        const status = layer.querySelector('.custom-order-filter-status');
        editor.placeholder = '一次性使用精密过滤输液器\n*溶药注射器*\n[用法]“领药”\n[频次]“*qd*”';
        editor.value = medicalOrderFilterNormalizePatterns(settings.readPatterns());
        let savedPatterns = editor.value;
        const update = function () {
            const rules = medicalOrderFilterCompilePatterns(editor.value);
            const invalid = medicalOrderFilterNormalizePatterns(editor.value).split('\n').filter(Boolean).map(function (pattern) {
                return medicalOrderFilterParsePattern(pattern);
            }).filter(function (rule) { return rule.error; });
            status.style.color = invalid.length ? '#b45309' : '#475569';
            status.textContent = '有效规则：' + rules.length + ' 条。空行及完全重复行自动忽略；规则为空时不额外过滤。' +
                (invalid.length ? ' 另有' + invalid.length + '条规则未生效：' + invalid.slice(0, 3).map(function (rule) { return rule.pattern + '（' + rule.error + '）'; }).join('；') : '');
        };
        const syncRules = function () {
            const incoming = medicalOrderFilterNormalizePatterns(settings.readPatterns());
            if (incoming === savedPatterns) return;
            if (editor.value === savedPatterns) {
                editor.value = incoming;
                savedPatterns = incoming;
                update();
            } else {
                status.textContent = '另一入口已更新规则；当前未保存的编辑已保留，保存后将同步到两个脚本。';
            }
        };
        const close = function () {
            window.removeEventListener('medical-suite-custom-order-patterns-change', syncRules);
            layer.remove();
            if (previousFocus && previousFocus.isConnected && previousFocus.focus) previousFocus.focus();
        };
        layer._closeCustomOrderFilter = close;
        window.addEventListener('medical-suite-custom-order-patterns-change', syncRules);
        layer.querySelector('.custom-order-filter-close').addEventListener('click', close);
        layer.querySelector('.custom-order-filter-cancel').addEventListener('click', close);
        layer.addEventListener('keydown', function (event) {
            if (event.key === 'Escape') { event.stopPropagation(); close(); }
        });
        editor.addEventListener('input', update);
        layer.querySelector('.custom-order-filter-save').addEventListener('click', function () {
            try {
                settings.savePatterns(medicalOrderFilterNormalizePatterns(editor.value));
                close();
            } catch (error) {
                status.style.color = '#b93830';
                status.textContent = '保存失败：' + String(error && error.message || error);
            }
        });
        document.body.appendChild(layer);
        update();
        editor.focus();
        return layer;
    }

    function inpatientLoadCustomOrderPatterns() {
        return medicalOrderLoadSharedPatterns();
    }

    function inpatientSaveCustomOrderPatterns(patterns) {
        medicalOrderSaveSharedPatterns(patterns);
    }

    function inpatientOpenCustomOrderSettings() {
        return medicalOpenCustomOrderFilterSettings({
            id: 'medical-inpatient-custom-order-filter-settings',
            title: '住院信息－自定义医嘱过滤',
            readPatterns: inpatientLoadCustomOrderPatterns,
            savePatterns: function (patterns) {
                inpatientSaveCustomOrderPatterns(patterns);
                showStatus('自定义医嘱规则已保存；请重新提取医嘱或从接口调用医嘱，生成应用新规则的缓存。', 'success');
            },
            hint: '规则与患者信息脚本共用，任一入口保存后同步更新并随配置备份。过滤开关独立记忆；保存规则不自动开启过滤，重新提取后用于病历AI医嘱正文。可视化“隐藏自定义医嘱”只控制展示，手工医嘱正文不自动删除。'
        });
    }

    window.addEventListener('medical-suite-custom-order-patterns-change', function () {
        const visual = document.getElementById(INPATIENT_BASELINE_ORDER_VISUAL_MODAL_ID);
        if (visual && typeof visual._refreshOrderVisual === 'function') visual._refreshOrderVisual();
    });

    function progressFilterCustomRecords(records, enabledOverride, patternsOverride) {
        const source = Array.isArray(records) ? records : [];
        const enabled = typeof enabledOverride === 'boolean' ? enabledOverride : inpatientLoadFilterCustomOrders();
        const patterns = typeof patternsOverride === 'string' ? patternsOverride : inpatientLoadCustomOrderPatterns();
        const kept = enabled ? source.filter(function (record) {
            return !medicalOrderFilterFindRule(record, patterns);
        }) : source.slice();
        return { enabled: enabled, records: kept, filteredCount: source.length - kept.length, patterns: patterns };
    }

    function inpatientFilteredOrderAudit(records, settings) {
        const source = Array.isArray(records) ? records : [];
        const config = settings || {};
        const excluded = [];
        source.forEach(function (record) {
            const reasons = [];
            if (config.filterVoidedTemporaryOrders && progressOrderIsVoidedTemporary(record)) reasons.push('临时作废医嘱');
            if (config.filterNoPrintOrders && progressOrderIsNoPrint(record)) reasons.push('不打印医嘱');
            const rule = config.filterCustomOrders ? medicalOrderFilterFindRule(record, config.customOrderPatterns) : '';
            if (rule) reasons.push('自定义医嘱（' + rule + '）');
            if (reasons.length) excluded.push(Object.assign({}, record, { _medicalOrderFilterReasons: reasons }));
        });
        return excluded;
    }

    document.addEventListener('click', function (event) {
        const button = event.target && event.target.closest && event.target.closest('[data-inpatient-custom-order-settings]');
        if (button) inpatientOpenCustomOrderSettings();
    });

    function progressOrderIsNoPrint(record) {
        return progressPlain(record && record.noPrint) === '1';
    }

    function progressFilterNoPrintRecords(records, enabledOverride) {
        const source = Array.isArray(records) ? records : [];
        const enabled = typeof enabledOverride === 'boolean'
            ? enabledOverride
            : inpatientLoadFilterNoPrintOrders();
        const kept = enabled
            ? source.filter(function (record) {
                return !progressOrderIsNoPrint(record);
            })
            : source.slice();
        return {
            enabled: enabled,
            records: kept,
            filteredCount: source.length - kept.length
        };
    }

    function inpatientOrderFilterResultSuffix(result) {
        const voidedCount = Number(
            result && result.filteredVoidedTemporaryCount || 0
        );
        const noPrintCount = Number(
            result && result.filteredNoPrintCount || 0
        );
        const customCount = Number(
            result && result.filteredCustomCount || 0
        );
        const pendingCount = Number(
            result && result.pendingReviewCount || 0
        );
        const filteredPendingCount = Number(
            result && result.filteredPendingReviewCount || 0
        );
        let text = voidedCount > 0
            ? '；已过滤临时作废医嘱' + voidedCount + '条'
            : '';
        if (noPrintCount > 0) {
            text += '；已过滤不打印医嘱' + noPrintCount + '条';
        }
        if (customCount > 0) {
            text += '；已过滤自定义医嘱' + customCount + '条';
        }
        if (result && result.includePendingOrders) {
            text += '；已包含待审核医嘱' + pendingCount + '条';
        } else if (filteredPendingCount > 0) {
            text += '；已排除待审核医嘱' + filteredPendingCount + '条';
        }
        return text;
    }

    function inpatientOrderCacheFilterSuffix(cache) {
        if (!cache || cache.captureMode === 'manual') {
            return '';
        }
        const count = Number(
            cache.filteredVoidedTemporaryCount || 0
        );
        const noPrintCount = Number(
            cache.filteredNoPrintCount || 0
        );
        const customCount = Number(
            cache.filteredCustomCount || 0
        );

        const hasPendingCount = cache.pendingReviewCount !== undefined &&
            Number.isFinite(Number(cache.pendingReviewCount));
        const pendingCount = hasPendingCount
            ? Number(cache.pendingReviewCount)
            : 0;
        const filteredPendingCount = Number(
            cache.filteredPendingReviewCount || 0
        );
        /* 旧缓存缺少筛选元数据时，不能把 undefined 当成“关闭”。 */
        const state = function (value) {
            return typeof value === 'boolean'
                ? (value ? '开启' : '关闭')
                : '未记录（旧缓存）';
        };
        const queryMode = String(cache.queryMode || '');
        const orderText = String(cache.orderText || '');
        let includePending = cache.includePendingOrders;
        if (typeof includePending !== 'boolean') {
            if (/待审核wsh=true/.test(queryMode) ||
                /说明：已启用“包含待审核医嘱”/.test(orderText)) {
                includePending = true;
            } else if (/不含待审核/.test(queryMode) ||
                /说明：未启用“包含待审核医嘱”/.test(orderText)) {
                includePending = false;
            }
        }
        return (
            '；缓存提取时：过滤临时作废医嘱=' +
            state(cache.filterVoidedTemporaryOrders) +
            (count > 0 ? '（已过滤' + count + '条）' : '') +
            '；过滤不打印医嘱=' +
            state(cache.filterNoPrintOrders) +
            (noPrintCount > 0 ? '（已过滤' + noPrintCount + '条）' : '') +
            '；过滤自定义医嘱=' + state(cache.filterCustomOrders) +
            (customCount > 0 ? '（已过滤' + customCount + '条）' : '') +
            '；包含待审核医嘱=' +
            state(includePending) +
            (includePending === true
                ? (hasPendingCount
                    ? '（待审核' + pendingCount + '条）'
                    : '（数量未记录）')
                : (filteredPendingCount > 0
                    ? '（已排除' + filteredPendingCount + '条）'
                    : ''))
        );
    }

    /*
     * HIS部分页面会把“姓名、性别、年龄”等相邻字段压在同一个文本节点中，
     * 例如“姓名：周爱菊性别：女”。旧逻辑会把“周爱菊性别”误当作姓名，
     * 继而导致门诊页与已锁定住院患者被判定为不同患者。
     */
    function progressCleanPatientName(value) {
        const source = progressPlain(value)
            .replace(/^(?:患者姓名|姓名|患者)\s*[：:]?\s*/, '')
            .replace(
                /(?:性别|年龄|床号|病床|住院号|门诊号|就诊号|病案号|身份证号|医保类型|医保|职业|科别|病区)\s*[：:]?[\s\S]*$/,
                ''
            )
            .trim();

        const match = source.match(/^[\u3400-\u9fff·]{2,10}/);
        return match ? match[0] : source;
    }

    function collectVisiblePageText(doc, limit) {
        if (!doc || !doc.body) return '';

        const maximum = Math.max(3000, Number(limit) || 50000);
        const chunks = [];
        let length = 0;
        const win = doc.defaultView;
        const nodeFilter = win && win.NodeFilter
            ? win.NodeFilter
            : NodeFilter;
        let walker;

        try {
            walker = doc.createTreeWalker(
                doc.body,
                nodeFilter.SHOW_TEXT,
                {
                    acceptNode: function (node) {
                        const parent = node && node.parentElement;

                        if (!parent) return nodeFilter.FILTER_REJECT;

                        if (
                            parent.closest('#' + PANEL_ID) ||
                            parent.closest('#' + MODAL_ID) ||
                            parent.closest('#' + SETTINGS_MODAL_ID) ||
                            parent.closest('#' + PROGRESS_MODAL_ID) ||
                            parent.closest('#medical-patient-ai-custom-editor') ||
                            parent.closest('#medical-inpatient-first-course-ai-modal') ||
                            parent.closest('#medical-inpatient-discharge-record-ai-modal') ||
                            parent.closest('#medical-inpatient-condition-disclosure-ai-modal') ||
                            parent.closest('#medical-inpatient-admission-record-ai-modal') ||
                            parent.closest('#' + STATUS_ID) ||
                            parent.closest('script,style,noscript,template')
                        ) {
                            return nodeFilter.FILTER_REJECT;
                        }

                        if (!isVisible(parent)) {
                            return nodeFilter.FILTER_REJECT;
                        }

                        return progressPlain(node.nodeValue || '')
                            ? nodeFilter.FILTER_ACCEPT
                            : nodeFilter.FILTER_REJECT;
                    }
                }
            );
        } catch (error) {
            walker = null;
        }

        if (walker) {
            let node = walker.nextNode();

            while (node && length < maximum) {
                const value = progressPlain(node.nodeValue || '');

                if (value) {
                    chunks.push(value);
                    length += value.length + 1;
                }

                node = walker.nextNode();
            }
        }

        Array.from(doc.querySelectorAll(
            'input:not([type="hidden"]),textarea,[contenteditable="true"]'
        ))
            .filter(function (element) {
                return isVisible(element) &&
                    !element.closest('#' + PANEL_ID) &&
                    !element.closest('#' + MODAL_ID) &&
                    !element.closest('#' + SETTINGS_MODAL_ID) &&
                    !element.closest('#' + PROGRESS_MODAL_ID) &&
                    !element.closest('#medical-patient-ai-custom-editor') &&
                    !element.closest('#medical-inpatient-first-course-ai-modal') &&
                    !element.closest('#medical-inpatient-discharge-record-ai-modal') &&
                    !element.closest('#medical-inpatient-condition-disclosure-ai-modal') &&
                    !element.closest('#medical-inpatient-admission-record-ai-modal');
            })
            .forEach(function (element) {
                if (length >= maximum) return;

                const value = progressPlain(
                    element.isContentEditable
                        ? element.textContent
                        : element.value
                );

                if (!value) return;

                chunks.push(value);
                length += value.length + 1;
            });

        return chunks.join('\n').slice(0, maximum);
    }

    function extractPatientIdentityFromText(textValue) {
        const text = String(textValue || '').replace(/\u00a0/g, ' ');
        const identity = {
            name: '',
            inpatientNo: '',
            bed: '',
            sex: '',
            age: ''
        };

        /*
         * 住院医嘱页面顶部常见格式：
         *   孔繁华 / 女 / 87岁 / 职工医保 / 80284
         * 或：患者信息：孔繁华 / 女 / 87岁 / 职工医保 / 80284
         *
         * 这一行比整页中散落的“住院号”可靠得多，优先一次性解析。
         */
        const compactHeaderMatch = text.match(
            /(?:患者信息\s*[：:]\s*)?([\u3400-\u9fff·]{2,10})\s*\/\s*(男|女)\s*\/\s*([0-9]{1,3})\s*岁(?:\s*\/\s*[^\/\n]{0,50})?\s*\/\s*([0-9]{5,10})(?=\s|$|\/)/
        );

        if (compactHeaderMatch) {
            identity.name = progressCleanPatientName(compactHeaderMatch[1]);
            identity.sex = compactHeaderMatch[2];
            identity.age = compactHeaderMatch[3];
            identity.inpatientNo = progressPlain(compactHeaderMatch[4]);
        }

        const namePatterns = [
            /患者信息\s*[：:]\s*([\u3400-\u9fff·]{2,10})/,
            /姓名\s*[：:]\s*([\u3400-\u9fff·]{2,10})/,
            /患者\s*([\u3400-\u9fff·]{2,10})\s*[，,]\s*[男女]/
        ];

        if (!identity.name) {
            for (const pattern of namePatterns) {
                const match = text.match(pattern);

                if (match && match[1]) {
                    identity.name = progressCleanPatientName(match[1]);
                    break;
                }
            }
        }

        const inpatientPatterns = [
            /住院号\s*[：:]\s*([A-Za-z0-9-]{4,24})/i,
            /患者信息\s*[：:][^\n]{0,160}\/\s*([0-9]{5,10})(?:\s*\/|\s|$)/,
            /\b([0-9]{5,8})-[0-9A-Za-z-]{3,20}\b/
        ];

        if (!identity.inpatientNo) {
            for (const pattern of inpatientPatterns) {
                const match = text.match(pattern);

                if (match && match[1]) {
                    identity.inpatientNo = progressPlain(match[1]);
                    break;
                }
            }
        }

        const bedMatch = text.match(
            /(?:床号|病床)\s*[：:]?\s*([0-9]{1,4})\s*床?/i
        ) || text.match(/\b([0-9]{2,4})床\b/);

        if (bedMatch && bedMatch[1]) {
            identity.bed = progressPlain(bedMatch[1]);
        }

        const sexMatch = text.match(
            /(?:患者信息\s*[：:][^\n]{0,60}\/\s*|患者[^\n]{0,20}[，,]\s*)(男|女)/
        );

        if (!identity.sex && sexMatch && sexMatch[1]) {
            identity.sex = sexMatch[1];
        }

        const ageMatch = text.match(/\b([0-9]{1,3})\s*岁\b/);

        if (!identity.age && ageMatch && ageMatch[1]) {
            identity.age = ageMatch[1];
        }

        return identity;
    }

    function extractCurrentPatientIdentity() {
        const candidates = [];

        function pushCandidate(identity, textValue, score, source) {
            if (!identity || (!identity.name && !identity.inpatientNo)) {
                return;
            }

            candidates.push({
                identity: identity,
                text: textValue || '',
                score: score || 0,
                source: source || ''
            });
        }

        /*
         * 只扫描当前可见iframe，彻底排除HIS后台保留的其他患者标签页。
         */
        getVisibleDocuments().forEach(function (doc, docIndex) {
            /*
             * 第一优先级：寻找顶部蓝色“患者信息/姓名/性别/年龄/医保/住院号”
             * 这种短文本。截图中的“孔繁华 / 女 / 87岁 / 职工医保 / 80284”
             * 会在这里获得远高于整页文本的分数。
             */
            let elements = [];

            try {
                elements = Array.from(doc.querySelectorAll(
                    'span,div,a,p,label,strong,b,td'
                ));
            } catch (error) {
                elements = [];
            }

            elements
                .filter(function (element) {
                    if (!isVisible(element)) return false;
                    if (
                        element.closest('#' + PANEL_ID) ||
                        element.closest('#' + MODAL_ID) ||
                        element.closest('#' + SETTINGS_MODAL_ID) ||
                        element.closest('#' + PROGRESS_MODAL_ID) ||
                        element.closest('#medical-patient-ai-custom-editor') ||
                        element.closest('#medical-inpatient-first-course-ai-modal') ||
                        element.closest('#medical-inpatient-discharge-record-ai-modal') ||
                        element.closest('#medical-inpatient-condition-disclosure-ai-modal') ||
                        element.closest('#medical-inpatient-admission-record-ai-modal') ||
                        element.closest('#' + STATUS_ID)
                    ) {
                        return false;
                    }

                    const value = progressPlain(
                        element.innerText || element.textContent || ''
                    );

                    return value.length >= 8 && value.length <= 180;
                })
                .forEach(function (element) {
                    const value = progressPlain(
                        element.innerText || element.textContent || ''
                    );

                    const looksLikeCompactHeader =
                        /[\u3400-\u9fff·]{2,10}\s*\/\s*[男女]\s*\/\s*[0-9]{1,3}\s*岁/.test(value) &&
                        /\/\s*[0-9]{5,10}(?:\s|$|\/)/.test(value);

                    const looksLikeExplicitIdentity =
                        /患者信息|住院号|床号|姓名/.test(value);

                    if (!looksLikeCompactHeader && !looksLikeExplicitIdentity) {
                        return;
                    }

                    const identity = extractPatientIdentityFromText(value);
                    let score = 0;

                    if (looksLikeCompactHeader) score += 420;
                    if (/患者信息/.test(value)) score += 120;
                    if (identity.inpatientNo) score += 180;
                    if (identity.name) score += 140;
                    if (identity.sex) score += 25;
                    if (identity.age) score += 20;
                    if (identity.bed) score += 20;

                    /* 顶层/更靠前的活动文档略微优先。 */
                    score -= docIndex * 2;

                    pushCandidate(identity, value, score, 'patient-header');
                });

            /*
             * 第二优先级：当前可见文档的完整可见文字兜底。
             */
            const textValue = collectVisiblePageText(doc, 18000);

            if (textValue) {
                const identity = extractPatientIdentityFromText(textValue);
                let score = 0;

                if (identity.inpatientNo) score += 100;
                if (identity.name) score += 80;
                if (identity.bed) score += 20;
                if (identity.sex) score += 10;
                if (identity.age) score += 10;
                if (/患者信息/.test(textValue)) score += 25;
                if (/住院号|姓名/.test(textValue)) score += 10;
                score -= docIndex * 2;

                pushCandidate(identity, textValue, score, 'visible-page');
            }
        });

        candidates.sort(function (a, b) {
            if (a.score !== b.score) {
                return b.score - a.score;
            }

            /* 同分时优先信息更完整者。 */
            const completeA =
                Boolean(a.identity.inpatientNo) +
                Boolean(a.identity.name) +
                Boolean(a.identity.sex) +
                Boolean(a.identity.age) +
                Boolean(a.identity.bed);
            const completeB =
                Boolean(b.identity.inpatientNo) +
                Boolean(b.identity.name) +
                Boolean(b.identity.sex) +
                Boolean(b.identity.age) +
                Boolean(b.identity.bed);

            return completeB - completeA;
        });

        return candidates[0] && candidates[0].score >= 80
            ? candidates[0].identity
            : {
                name: '',
                inpatientNo: '',
                bed: '',
                sex: '',
                age: ''
            };
    }

    function mergePatientIdentity(primary, secondary) {
        const first = primary || {};
        const second = secondary || {};

        return {
            name: progressPlain(first.name || second.name || ''),
            inpatientNo: progressPlain(first.inpatientNo || second.inpatientNo || ''),
            bed: progressPlain(first.bed || second.bed || ''),
            sex: progressPlain(first.sex || second.sex || ''),
            age: progressPlain(first.age || second.age || '')
        };
    }

    function patientIdentityLabel(identity) {
        const item = identity || {};
        const parts = [];

        if (item.name) parts.push(item.name);
        if (item.sex) parts.push(item.sex);
        if (item.age) parts.push(item.age + '岁');
        if (item.bed) parts.push(item.bed + '床');
        if (item.inpatientNo) {
            parts.push(
                (/^CUSTOM-/i.test(item.inpatientNo)
                    ? '本地档案号'
                    : '住院号') + item.inpatientNo
            );
        }

        return parts.join(' / ') || '未识别患者身份';
    }

    function patientIdentityKey(identity) {
        const item = identity || {};

        if (item.inpatientNo) {
            return 'no:' + progressNormalize(item.inpatientNo);
        }

        if (item.name && item.bed) {
            return 'namebed:' +
                progressNormalize(item.name) + ':' +
                progressNormalize(item.bed);
        }

        if (item.name) {
            return 'name:' + progressNormalize(item.name);
        }

        return '';
    }

    function loadProgressTargetPatient() {
        try {
            const value = JSON.parse(
                localStorage.getItem(
                    PROGRESS_TARGET_PATIENT_STORAGE_KEY
                ) || 'null'
            );

            return value && typeof value === 'object'
                ? value
                : null;
        } catch (error) {
            return null;
        }
    }

    function saveProgressTargetPatient(identity) {
        if (!identity || (!identity.name && !identity.inpatientNo)) {
            return;
        }

        try {
            localStorage.setItem(
                PROGRESS_TARGET_PATIENT_STORAGE_KEY,
                JSON.stringify(identity)
            );
        } catch (error) {
            // 本地保存失败不阻止其他功能。
        }
    }

    function patientIdentityMatches(first, second) {
        const a = first || {};
        const b = second || {};
        const aNo = progressNormalize(a.inpatientNo);
        const bNo = progressNormalize(b.inpatientNo);
        const aName = progressNormalize(a.name);
        const bName = progressNormalize(b.name);
        const aBed = progressNormalize(a.bed);
        const bBed = progressNormalize(b.bed);

        /* 自定义档案不能仅凭同名与未带住院号的页面患者匹配。 */
        if ((a.customPatient || b.customPatient) &&
            (!aNo || !bNo || aNo !== bNo)) {
            return false;
        }

        if (aNo && bNo) {
            return aNo === bNo;
        }

        if (aName && bName && aName !== bName) {
            return false;
        }

        if (aName && bName) {
            if (aBed && bBed && aBed !== bBed) {
                return false;
            }

            return true;
        }

        return false;
    }

    /*
     * v2.41.1：五个AI模块共用的患者解锁与长文本手工编辑工具。
     * “解锁”只旁路患者身份一致性校验，不清除已经锁定的目标患者，
     * 因此缓存仍可继续按原目标患者归档；重新锁定即可恢复校验。
     */
    function patientAiLoadUnlocked(storageKey) {
        try {
            return sessionStorage.getItem(storageKey) === '1';
        } catch (error) {
            return false;
        }
    }

    function patientAiSaveUnlocked(storageKey, unlocked) {
        try {
            sessionStorage.setItem(storageKey, unlocked ? '1' : '0');
        } catch (error) {
            // 本地保存失败不阻止本次操作。
        }
    }

    function patientAiManualIdentity(target) {
        const current = extractCurrentPatientIdentity();
        const identity = target && (target.name || target.inpatientNo)
            ? target
            : current;

        if (!identity || (!identity.name && !identity.inpatientNo)) {
            throw new Error('尚未识别或锁定患者，无法保存手动资料');
        }

        return identity;
    }

    /* 五个病历AI模块共用自定义患者名册，患者正文缓存仍按原住院号隔离。 */
    const PATIENT_AI_CUSTOM_STORAGE_KEY =
        'medicalInpatientAiCustomPatientsV1';
    const PATIENT_AI_CUSTOM_APPLY_ALL_STORAGE_KEY =
        'medicalInpatientAiCustomApplyAllV1';

    function patientAiLoadCustomPatients() {
        let source;
        try {
            source = JSON.parse(
                localStorage.getItem(PATIENT_AI_CUSTOM_STORAGE_KEY) || '{}'
            );
        } catch (error) {
            source = {};
        }

        const registry = Object.create(null);
        if (!source || typeof source !== 'object' || Array.isArray(source)) {
            return registry;
        }

        Object.keys(source).forEach(function (key) {
            const item = source[key];
            if (!item || !item.name || !item.inpatientNo) return;
            const normalized = progressNormalize(item.inpatientNo);
            if (normalized) {
                registry[normalized] = Object.assign({}, item, {
                    customPatient: true
                });
            }
        });
        return registry;
    }

    function patientAiIsCustomTarget(identity) {
        if (!identity || !identity.customPatient || !identity.inpatientNo) {
            return false;
        }
        const key = progressNormalize(identity.inpatientNo);
        return Boolean(patientAiLoadCustomPatients()[key]);
    }

    function patientAiIdentityWithoutPage(current, target) {
        return current && (current.name || current.inpatientNo)
            ? current
            : patientAiIsCustomTarget(target)
                ? target
                : current;
    }

    function patientAiCustomModules() {
        return [
            {
                id: PROGRESS_MODAL_ID,
                name: '病程记录AI',
                key: PROGRESS_TARGET_PATIENT_STORAGE_KEY,
                unlockKey: PROGRESS_PATIENT_UNLOCKED_STORAGE_KEY,
                load: loadProgressTargetPatient,
                refresh: updateProgressModalPatientStatus,
                open: openProgressModal
            },
            {
                id: FIRST_COURSE_MODAL_ID,
                name: '首次病程AI',
                key: FIRST_COURSE_TARGET_PATIENT_STORAGE_KEY,
                unlockKey: FIRST_COURSE_PATIENT_UNLOCKED_STORAGE_KEY,
                load: loadFirstCourseTargetPatient,
                refresh: updateFirstCourseModalStatus,
                open: openFirstCourseModal
            },
            {
                id: DISCHARGE_RECORD_MODAL_ID,
                name: '出院记录AI',
                key: DISCHARGE_RECORD_TARGET_PATIENT_STORAGE_KEY,
                unlockKey: DISCHARGE_RECORD_PATIENT_UNLOCKED_STORAGE_KEY,
                load: dischargeLoadTargetPatient,
                refresh: updateDischargeRecordModalStatus,
                open: openDischargeRecordModal
            },
            {
                id: CONDITION_DISCLOSURE_MODAL_ID,
                name: '病情告知AI',
                key: CONDITION_DISCLOSURE_TARGET_PATIENT_STORAGE_KEY,
                unlockKey: CONDITION_DISCLOSURE_PATIENT_UNLOCKED_STORAGE_KEY,
                load: loadConditionDisclosureTargetPatient,
                refresh: updateConditionDisclosureModalStatus,
                open: openConditionDisclosureModal
            },
            {
                id: ADMISSION_RECORD_AI_MODAL_ID,
                name: '入院记录AI',
                key: ADMISSION_RECORD_AI_TARGET_STORAGE_KEY,
                unlockKey: ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY,
                load: admissionRecordAiLoadTargetPatient,
                refresh: updateAdmissionRecordAiModalStatus,
                open: openAdmissionRecordAiModal
            }
        ];
    }

    function openPatientAiCustomEditor(moduleId) {
        const oldLayer = document.getElementById(
            'medical-patient-ai-custom-editor'
        );
        if (oldLayer) oldLayer.remove();

        const modules = patientAiCustomModules();
        const sourceModule = modules.find(function (item) {
            return item.id === moduleId;
        });
        if (!sourceModule) return;

        const layer = document.createElement('div');
        layer.id = 'medical-patient-ai-custom-editor';
        layer.style.cssText =
            'position:fixed;inset:0;z-index:2147483647;display:flex;' +
            'align-items:center;justify-content:center;background:rgba(0,0,0,.42);' +
            'font-family:"Microsoft YaHei",Arial,sans-serif;';
        layer.innerHTML =
            '<div style="box-sizing:border-box;width:min(680px,calc(100vw - 24px));max-height:calc(100vh - 24px);overflow:auto;background:#fff;border-radius:8px;box-shadow:0 12px 42px rgba(0,0,0,.35);">' +
                '<div style="height:52px;background:' + NATIVE_SIMPLE_DARK_BLUE_STYLE.primaryColor + ';color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font-size:17px;font-weight:bold;">' +
                    '<span>自定义患者 · 五个病历AI模块共用</span>' +
                    '<button type="button" class="custom-close" aria-label="关闭" style="border:0;background:transparent;color:#fff;font-size:28px;cursor:pointer;">×</button>' +
                '</div>' +
                '<div style="padding:17px;display:flex;flex-direction:column;gap:13px;color:#243b50;font-size:13px;">' +
                    '<div style="line-height:1.6;color:#5c6c78;">当前页面无法识别患者时，在这里创建或选择档案。自定义患者名册由五个模块共用，默认只锁定当前模块；已有患者资料缓存不会删除。随后请使用各模块的“手动录入/修改”填写病历基线。</div>' +
                    '<label style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;">已有自定义患者 <select class="custom-list" style="flex:1;min-width:180px;height:34px;border:1px solid #b9d9e7;border-radius:5px;background:#fff;padding:0 8px;font:inherit;"><option value="">新建患者</option></select>' +
                        '<button type="button" class="custom-new" style="height:34px;border:1px solid #b9d9e7;border-radius:5px;background:#f3fbfe;color:#117fac;padding:0 11px;cursor:pointer;">新建</button></label>' +
                    '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;">' +
                        '<label>姓名 <span style="color:#b93830;">*</span><input class="custom-name" maxlength="30" autocomplete="off" style="box-sizing:border-box;width:100%;height:34px;margin-top:5px;border:1px solid #b9d9e7;border-radius:5px;padding:0 9px;font:inherit;"></label>' +
                        '<label>住院号／本地档案号 <span style="color:#b93830;">*</span><span style="display:flex;gap:5px;margin-top:5px;"><input class="custom-number" maxlength="24" autocomplete="off" style="box-sizing:border-box;min-width:0;flex:1;height:34px;border:1px solid #b9d9e7;border-radius:5px;padding:0 9px;font:inherit;"><button type="button" class="custom-generate-number" title="无住院号时生成仅用于本机资料缓存的档案号" style="border:1px solid #b9d9e7;border-radius:5px;background:#f3fbfe;color:#117fac;padding:0 8px;cursor:pointer;white-space:nowrap;">生成本地号</button></span></label>' +
                        '<label>性别 <select class="custom-sex" style="box-sizing:border-box;width:100%;height:34px;margin-top:5px;border:1px solid #b9d9e7;border-radius:5px;background:#fff;padding:0 8px;font:inherit;"><option value="">未填写</option><option value="男">男</option><option value="女">女</option></select></label>' +
                        '<label>年龄 <input class="custom-age" type="number" min="0" max="130" placeholder="可选" style="box-sizing:border-box;width:100%;height:34px;margin-top:5px;border:1px solid #b9d9e7;border-radius:5px;padding:0 9px;font:inherit;"></label>' +
                        '<label>床号 <input class="custom-bed" maxlength="20" placeholder="可选" style="box-sizing:border-box;width:100%;height:34px;margin-top:5px;border:1px solid #b9d9e7;border-radius:5px;padding:0 9px;font:inherit;"></label>' +
                    '</div>' +
                    '<div style="font-size:12px;line-height:1.55;color:#6c7480;">没有住院号可生成本地档案号；本地号仅用于区分手动资料，不能用于HIS接口检索。若AI结果包含本地号，写入正式病历前请核对并替换。已建档患者的档案号不可更改，其他字段可修改。删除只移出患者名册并解除锁定，不清除病历资料缓存；重建同号档案时旧缓存仍可能读回。</div>' +
                    '<label style="display:flex;align-items:center;gap:7px;color:#117fac;"><input type="checkbox" class="custom-apply-all" style="width:17px;height:17px;">同时应用到五个模块（记住上次选择）</label>' +
                    '<div class="custom-error" role="alert" style="display:none;padding:8px;border-radius:5px;background:#fff0ef;color:#b93830;"></div>' +
                    '<div style="display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;">' +
                        '<button type="button" class="custom-delete" disabled style="height:35px;border:1px solid #c85b52;border-radius:5px;background:#fff1f0;color:#b93830;padding:0 15px;cursor:pointer;margin-right:auto;">删除选中患者</button>' +
                        '<button type="button" class="custom-cancel" style="height:35px;border:1px solid #b9d9e7;border-radius:5px;background:#f3fbfe;color:#117fac;padding:0 15px;cursor:pointer;">取消</button>' +
                        '<button type="button" class="custom-save" style="height:35px;border:1px solid #159bd3;border-radius:5px;background:#159bd3;color:#fff;padding:0 15px;cursor:pointer;">保存并用于当前模块</button>' +
                    '</div>' +
                '</div>' +
            '</div>';
        document.body.appendChild(layer);

        const list = layer.querySelector('.custom-list');
        const nameBox = layer.querySelector('.custom-name');
        const numberBox = layer.querySelector('.custom-number');
        const sexBox = layer.querySelector('.custom-sex');
        const ageBox = layer.querySelector('.custom-age');
        const bedBox = layer.querySelector('.custom-bed');
        const applyAllBox = layer.querySelector('.custom-apply-all');
        const saveButton = layer.querySelector('.custom-save');
        const deleteButton = layer.querySelector('.custom-delete');
        const errorBox = layer.querySelector('.custom-error');
        const registry = patientAiLoadCustomPatients();

        try {
            applyAllBox.checked = localStorage.getItem(
                PATIENT_AI_CUSTOM_APPLY_ALL_STORAGE_KEY
            ) === '1';
        } catch (error) {
            applyAllBox.checked = false;
        }
        saveButton.textContent = applyAllBox.checked
            ? '保存并用于五个模块'
            : '保存并用于当前模块';

        Object.keys(registry).sort(function (a, b) {
            return patientIdentityLabel(registry[a]).localeCompare(
                patientIdentityLabel(registry[b]), 'zh-CN'
            );
        }).forEach(function (key) {
            const option = document.createElement('option');
            option.value = key;
            option.textContent = patientIdentityLabel(registry[key]);
            list.appendChild(option);
        });

        function selectPatient(key) {
            const entry = registry[key] || {};
            list.value = key || '';
            nameBox.value = entry.name || '';
            numberBox.value = entry.inpatientNo || '';
            numberBox.readOnly = Boolean(key);
            layer.querySelector('.custom-generate-number').disabled = Boolean(key);
            deleteButton.disabled = !key;
            deleteButton.style.opacity = key ? '1' : '0.5';
            sexBox.value = entry.sex || '';
            ageBox.value = entry.age || '';
            bedBox.value = entry.bed || '';
            errorBox.style.display = 'none';
        }

        const active = sourceModule.load();
        const activeKey = active && active.customPatient
            ? progressNormalize(active.inpatientNo)
            : '';
        selectPatient(registry[activeKey] ? activeKey : '');

        function closeEditor() { layer.remove(); }
        layer.querySelector('.custom-close').addEventListener('click', closeEditor);
        layer.querySelector('.custom-cancel').addEventListener('click', closeEditor);
        layer.querySelector('.custom-new').addEventListener('click', function () {
            selectPatient('');
            nameBox.focus();
        });
        list.addEventListener('change', function () {
            selectPatient(list.value);
        });
        applyAllBox.addEventListener('change', function () {
            saveButton.textContent = applyAllBox.checked
                ? '保存并用于五个模块'
                : '保存并用于当前模块';
            try {
                localStorage.setItem(
                    PATIENT_AI_CUSTOM_APPLY_ALL_STORAGE_KEY,
                    applyAllBox.checked ? '1' : '0'
                );
            } catch (error) {
                errorBox.textContent = '勾选状态未能保存，当前窗口仍可继续使用。';
                errorBox.style.display = 'block';
            }
        });
        layer.addEventListener('click', function (event) {
            if (event.target === layer) closeEditor();
        });
        layer.querySelector('.custom-generate-number')
            .addEventListener('click', function () {
                numberBox.value = 'CUSTOM-' +
                    Date.now().toString(36).toUpperCase() +
                    Math.random().toString(36).slice(2, 6).toUpperCase();
            });

        deleteButton.addEventListener('click', function () {
            try {
                const key = list.value;
                const latestRegistry = patientAiLoadCustomPatients();
                const entry = latestRegistry[key];
                if (!key || !entry) {
                    throw new Error('请先从上方列表选择要删除的自定义患者。');
                }
                const busy = document.querySelector(
                    '.progress-abort:not(:disabled),.first-abort:not(:disabled),' +
                    '.discharge-abort:not(:disabled),.condition-abort:not(:disabled),' +
                    '.admission-ai-abort:not(:disabled),.admission-ai-expand-abort:not(:disabled)'
                );
                if (busy) {
                    throw new Error('有病历AI任务正在运行，请先中止或等待完成后再删除患者。');
                }

                const affected = modules.filter(function (item) {
                    const target = item.load();
                    return target && target.customPatient &&
                        progressNormalize(target.inpatientNo) === key;
                });
                const resultSelectors =
                    '.progress-result,.first-result,.discharge-result,' +
                    '.condition-result,.admission-ai-result,.admission-ai-expand-result';
                const hasResults = affected.some(function (item) {
                    const modal = document.getElementById(item.id);
                    return modal && Array.from(
                        modal.querySelectorAll(resultSelectors)
                    ).some(function (box) {
                        return Boolean(String(box.value || '').trim());
                    });
                });
                if (!window.confirm(
                    '确定删除自定义患者“' + patientIdentityLabel(entry) + '”吗？\n' +
                    '将解除' + affected.length + '个模块对该档案的锁定。' +
                    (hasResults ? '\n受影响窗口中尚未复制的生成结果会关闭。' : '') +
                    '\n病历资料缓存仍保留；若重新建立相同档案号，旧缓存仍可能读回。'
                )) return;

                const registrySnapshot = localStorage.getItem(
                    PATIENT_AI_CUSTOM_STORAGE_KEY
                );
                const snapshots = affected.map(function (item) {
                    return {
                        key: item.key,
                        value: localStorage.getItem(item.key)
                    };
                });
                try {
                    affected.forEach(function (item) {
                        localStorage.removeItem(item.key);
                    });
                    delete latestRegistry[key];
                    localStorage.setItem(
                        PATIENT_AI_CUSTOM_STORAGE_KEY,
                        JSON.stringify(latestRegistry)
                    );
                } catch (error) {
                    snapshots.concat([{
                        key: PATIENT_AI_CUSTOM_STORAGE_KEY,
                        value: registrySnapshot
                    }]).forEach(function (snapshot) {
                        try {
                            if (snapshot.value === null) {
                                localStorage.removeItem(snapshot.key);
                            } else {
                                localStorage.setItem(snapshot.key, snapshot.value);
                            }
                        } catch (ignored) { /* 存储已不可写，提示用户重试。 */ }
                    });
                    throw new Error('删除失败，请检查浏览器本地存储。');
                }

                affected.forEach(function (item) {
                    patientAiSaveUnlocked(item.unlockKey, false);
                    const modal = document.getElementById(item.id);
                    if (modal) modal.remove();
                });
                closeEditor();
                if (affected.indexOf(sourceModule) >= 0) {
                    sourceModule.open();
                }
                showStatus(
                    '已删除自定义患者“' + patientIdentityLabel(entry) +
                    '”，解除' + affected.length +
                    '个模块的对应锁定；病历资料缓存已保留。',
                    'success'
                );
            } catch (error) {
                errorBox.textContent = error && error.message || String(error);
                errorBox.style.display = 'block';
            }
        });

        saveButton.addEventListener('click', function () {
            try {
                const name = progressCleanPatientName(nameBox.value);
                const number = progressPlain(numberBox.value).toUpperCase();
                const age = progressPlain(ageBox.value);
                const key = progressNormalize(number);
                if (!name) throw new Error('请填写患者姓名。');
                if (!/^[A-Z0-9-]{3,24}$/.test(number) || !key) {
                    throw new Error('住院号／本地档案号需为3～24位字母、数字或连字符。');
                }
                if (age && (!/^\d{1,3}$/.test(age) || Number(age) > 130)) {
                    throw new Error('年龄应为0～130之间的整数。');
                }
                const latestRegistry = patientAiLoadCustomPatients();
                if (!list.value && latestRegistry[key]) {
                    throw new Error('该档案号已存在，请从上方列表选择后修改。');
                }
                if (list.value && list.value !== key) {
                    throw new Error('已建档患者的档案号不可更改，请新建患者。');
                }
                if (list.value && !latestRegistry[key]) {
                    throw new Error('该档案已在其他窗口删除，请重新打开自定义患者界面。');
                }

                const busy = layer.ownerDocument.querySelector(
                    '.progress-abort:not(:disabled),.first-abort:not(:disabled),' +
                    '.discharge-abort:not(:disabled),.condition-abort:not(:disabled),' +
                    '.admission-ai-abort:not(:disabled),.admission-ai-expand-abort:not(:disabled)'
                );
                if (busy) {
                    throw new Error('有病历AI任务正在运行，请先中止或等待完成后再切换患者。');
                }

                const identity = {
                    name: name,
                    inpatientNo: number,
                    sex: sexBox.value,
                    age: age,
                    bed: progressPlain(bedBox.value),
                    customPatient: true
                };
                const applyAll = applyAllBox.checked;
                const switchModules = applyAll
                    ? modules
                    : [sourceModule];
                const writeModules = modules.filter(function (item) {
                    if (switchModules.indexOf(item) >= 0) return true;
                    const previous = item.load();
                    return previous && previous.customPatient &&
                        progressNormalize(previous.inpatientNo) === key;
                });
                const different = switchModules.filter(function (item) {
                    const previous = item.load();
                    return previous &&
                        !patientIdentityMatches(previous, identity);
                });
                if (different.length && !window.confirm(
                    '以下将要切换的模块当前锁定了其他患者：\n' +
                    different.map(function (item) {
                        return item.name + '：' + patientIdentityLabel(item.load());
                    }).join('\n') +
                    '\n\n确定切换至“' +
                    patientIdentityLabel(identity) + '”吗？原有资料缓存不会删除。'
                )) return;

                const resultSelectors =
                    '.progress-result,.first-result,.discharge-result,' +
                    '.condition-result,.admission-ai-result,.admission-ai-expand-result';
                const hasResults = switchModules.some(function (item) {
                    const modal = document.getElementById(item.id);
                    return modal && Array.from(
                        modal.querySelectorAll(resultSelectors)
                    ).some(function (box) {
                        return Boolean(String(box.value || '').trim());
                    });
                });
                if (hasResults && !window.confirm(
                    '切换后将清空当前窗口尚未复制的AI生成结果，是否继续？'
                )) return;

                latestRegistry[key] = identity;
                const snapshots = writeModules.map(function (item) {
                    return {
                        key: item.key,
                        value: localStorage.getItem(item.key)
                    };
                });
                const registrySnapshot = localStorage.getItem(
                    PATIENT_AI_CUSTOM_STORAGE_KEY
                );
                try {
                    writeModules.forEach(function (item) {
                        localStorage.setItem(item.key, JSON.stringify(identity));
                    });
                    localStorage.setItem(
                        PATIENT_AI_CUSTOM_STORAGE_KEY,
                        JSON.stringify(latestRegistry)
                    );
                } catch (error) {
                    snapshots.concat([{
                        key: PATIENT_AI_CUSTOM_STORAGE_KEY,
                        value: registrySnapshot
                    }]).forEach(function (snapshot) {
                        try {
                            if (snapshot.value === null) {
                                localStorage.removeItem(snapshot.key);
                            } else {
                                localStorage.setItem(snapshot.key, snapshot.value);
                            }
                        } catch (ignored) { /* 存储已不可写，提示用户重试。 */ }
                    });
                    throw new Error('自定义患者保存失败，请检查浏览器本地存储空间。');
                }

                switchModules.forEach(function (item) {
                    patientAiSaveUnlocked(item.unlockKey, false);
                    const modal = document.getElementById(item.id);
                    if (modal) modal.remove();
                });
                writeModules.forEach(function (item) {
                    if (switchModules.indexOf(item) >= 0) return;
                    const modal = document.getElementById(item.id);
                    if (modal) item.refresh(modal);
                });
                closeEditor();
                sourceModule.open();
                showStatus(
                    '已将' + (applyAll ? '五个病历AI模块' : sourceModule.name) +
                    '锁定到自定义患者：' +
                    patientIdentityLabel(identity) +
                    '。请按需手动录入/修改各模块资料。',
                    'success'
                );
            } catch (error) {
                errorBox.textContent = error && error.message || String(error);
                errorBox.style.display = 'block';
            }
        });

        window.requestAnimationFrame(function () {
            nameBox.focus();
        });
        return layer;
    }

    function patientAiManualLineCount(textValue) {
        return String(textValue || '')
            .split(/\r?\n/)
            .filter(function (line) {
                return String(line || '').trim();
            }).length;
    }

    function patientAiManualProgressSource(textValue) {
        const text = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();
        const records = findAllProgressRecordMetasInText(text);
        const latestDate = records.length
            ? records[records.length - 1].date
            : findLatestDateInText(text);
        const firstCourse = records.find(function (item) {
            return item && item.title === '首次病程记录';
        });

        return {
            text: text,
            latestDate: latestDate || '',
            currentRecordDate:
                records[0] && records[0].date || '',
            currentRecordTitle:
                records[0] && records[0].title || '',
            admissionDate:
                firstCourse && firstCourse.date ||
                extractAdmissionDateFromProgressText(text) || '',
            sourceMode: 'manual-input',
            existingRecords: records,
            manual: true
        };
    }

    /* 各AI模块共用的只读基线可视化；复用患者信息脚本的趋势、医嘱及报告视图。 */
    const INPATIENT_BASELINE_VISUAL_OPTIONS_STORAGE_KEY = 'medicalInpatientBaselineVisualOptionsV1';
    const INPATIENT_BASELINE_VITAL_VISUAL_MODAL_ID = 'medical-inpatient-baseline-vital-visual';
    const INPATIENT_BASELINE_VITAL_VISUAL_STYLE_ID = 'medical-inpatient-baseline-vital-visual-style';
    const INPATIENT_BASELINE_LIS_PACS_VISUAL_MODAL_ID = 'medical-inpatient-baseline-lis-pacs-visual';
    const INPATIENT_BASELINE_LIS_PACS_VISUAL_STYLE_ID = 'medical-inpatient-baseline-lis-pacs-visual-style';
    const INPATIENT_BASELINE_ORDER_VISUAL_MODAL_ID = 'medical-inpatient-baseline-order-visual';
    const INPATIENT_BASELINE_ORDER_VISUAL_STYLE_ID = 'medical-inpatient-baseline-order-visual-style';

    function inpatientVisualEscapeHtml(value) {
        return String(value == null ? '' : value).replace(/[&<>"']/g,function (char) {
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char];
        });
    }

    function inpatientVisualOneLine(value) {
        return progressPlain(value).replace(/\s+/g,' ').trim();
    }

    function inpatientVisualCleanBed(value) {
        return inpatientVisualOneLine(value).replace(/床/g,'');
    }

    function inpatientVisualLoadOption(key) {
        try {
            const value = JSON.parse(localStorage.getItem(INPATIENT_BASELINE_VISUAL_OPTIONS_STORAGE_KEY) || '{}');
            return value && value[key] === true;
        } catch (error) {return false;}
    }

    function inpatientVisualSetOption(unused, key, enabled) {
        let value = {};
        try {value = JSON.parse(localStorage.getItem(INPATIENT_BASELINE_VISUAL_OPTIONS_STORAGE_KEY) || '{}') || {};} catch (error) {}
        if (typeof value !== 'object' || Array.isArray(value)) value = {};
        value[key] = Boolean(enabled);
        localStorage.setItem(INPATIENT_BASELINE_VISUAL_OPTIONS_STORAGE_KEY,JSON.stringify(value));
    }

    function inpatientVisualHideStopped() {return inpatientVisualLoadOption('orderVisualHideStopped');}
    function inpatientVisualHideVoided() {return inpatientVisualLoadOption('orderVisualHideVoided');}
    function inpatientVisualReverse() {return inpatientVisualLoadOption('orderVisualReverse');}

    function inpatientVisualSection() {return null;}

    function inpatientBindBaselineVisualButton(modal, selector, readOptions) {
        const button = modal.querySelector(selector);
        if (!button) return;
        button.addEventListener('click',function () {
            try {
                inpatientOpenBaselineVisualization(readOptions());
            } catch (error) {
                showStatus('可视化渲染失败：'+(error && error.message || error),'error');
            }
        });
    }

    function inpatientVisualParseExtendedLis(value) {
        const text = String(value || '').trim();
        if (!text) return {format:'empty',reports:[],rawText:''};
        const data = JSON.parse(text);
        if (!data || !Array.isArray(data.reports)) throw new Error('扩展LIS基线缺少reports数组');
        const reports = data.reports.filter(function (report) {
            return report && typeof report === 'object';
        }).map(function (report) {
            return Object.assign({},report,{
                _extendedLis:true,
                reagentTrayRaw:report.reagentTrayRaw || report.reagentTray || '',
                reagentTrayDisplay:report.reagentTrayDisplay || report.name || ''
            });
        });
        return {format:'structured',reports:reports,rawText:text};
    }

    function inpatientVisualParseOrders(textValue) {
        const source = String(textValue || '').replace(/\r\n?/g,'\n');
        const records = [], fields = {};
        PROGRESS_ORDER_FIELD_SPECS.forEach(function (spec) {
            [spec.label].concat(spec.aliases || []).forEach(function (label) {
                fields[progressNormalize(label)] = spec.key;
            });
        });
        const pattern = /【医嘱\d+】([\s\S]*?)(?=【医嘱\d+】|$)/g;
        let match;
        while ((match = pattern.exec(source))) {
            const record = {};
            match[1].split('\n').forEach(function (line) {
                const separator = line.search(/[：:]/);
                if (separator < 0) return;
                const label = progressNormalize(line.slice(0,separator));
                const value = line.slice(separator+1).trim();
                if (fields[label]) record[fields[label]] = value;
                if (label === progressNormalize('审核状态') && /未审核|待审核/.test(value)) record._pendingReview = true;
                if (label === progressNormalize('页面显示备注') && /隐藏/.test(value)) record._hiddenByClinicalPath = true;
            });
            if (progressPlain(record.name)) records.push(record);
        }
        return records;
    }

    function inpatientVisualTextSections(textValue) {
        const source = String(textValue || '').replace(/\r\n?/g,'\n');
        const parts = [], lines = [];
        let title = '正文';
        const heading = /^(?:[一二三四五六七八九十\d]+[、.．]\s*)?(?:主诉|现病史|既往史|个人史|过敏史|家族史|婚育史|体格检查|中医四诊|专科情况|辅助检查|初步诊断|入院情况|入院诊断|诊疗经过|出院诊断|出院情况|出院医嘱|病例特点|诊断依据|鉴别诊断|诊疗计划|中医辨病辨证依据)\s*[：:]/;
        function flush() {
            if (lines.length) parts.push({title:title,text:lines.join('\n')});
            lines.length = 0;
        }
        source.split('\n').forEach(function (line) {
            const trimmed = line.trim();
            if (heading.test(trimmed) || /^【[^】]{1,70}】/.test(trimmed) ||
                (/^20\d{2}[-年/.]/.test(trimmed) && /病程|查房|记录/.test(trimmed))) {
                flush();title = trimmed.slice(0,100);
            }
            lines.push(line);
        });
        flush();
        return parts;
    }

    function inpatientOpenTextBaselineVisual(value, settings) {
        const options = settings || {}, id = 'medical-inpatient-baseline-text-visual';
        const old = document.getElementById(id);
        if (old) old.remove();
        const layer = document.createElement('div');
        layer.id = id;layer.tabIndex = -1;
        layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');
        layer.style.cssText = 'position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.48);font-family:"Microsoft YaHei",Arial,sans-serif;';
        layer.innerHTML = '<div style="position:relative;display:flex;flex-direction:column;width:min(1080px,calc(100vw - 28px));height:min(860px,calc(100vh - 28px));background:#f6f8fa;border-radius:8px;overflow:hidden;box-shadow:0 14px 42px rgba(0,0,0,.38);">'+
            '<div style="flex:none;display:flex;align-items:center;justify-content:space-between;padding:13px 16px;background:'+ MODAL_HEADER_COLOR +';color:#fff;font-size:16px;"><strong>'+inpatientVisualEscapeHtml(options.title || '基线资料可视化')+'</strong><button type="button" class="inpatient-text-visual-close" style="border:0;background:transparent;color:#fff;font-size:25px;cursor:pointer;">×</button></div>'+
            '<div style="padding:9px 14px;background:#fff;border-bottom:1px solid #dfe6eb;font-size:13px;">'+inpatientVisualEscapeHtml(patientIdentityLabel(options.identity || {}))+'</div>'+
            '<div style="flex:1;min-height:0;overflow:auto;padding:12px 14px;">'+inpatientVisualTextSections(value).map(function (part) {
                return '<section style="margin-bottom:12px;background:#fff;border:1px solid #d7e0e5;border-radius:7px;overflow:hidden;"><h3 style="margin:0;padding:8px 10px;background:#eef9fd;color:#117fac;font-size:13px;">'+inpatientVisualEscapeHtml(part.title)+'</h3><pre style="margin:0;padding:10px;white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:13px;line-height:1.65;">'+inpatientVisualEscapeHtml(part.text)+'</pre></section>';
            }).join('')+'</div><div style="padding:8px 14px;background:#fff;border-top:1px solid #dfe6eb;color:#64748b;font-size:11px;line-height:1.55;">按当前基线原文分段展示，可核对日期与内容；未调用AI。'+inpatientVisualEscapeHtml(options.note || '')+'</div></div>';
        document.body.appendChild(layer);
        const close = function () {layer.remove();};
        layer.querySelector('.inpatient-text-visual-close').addEventListener('click',close);
        layer.addEventListener('click',function (event) {if (event.target === layer) close();});
        layer.addEventListener('keydown',function (event) {if (event.key === 'Escape') close();});
        layer.focus();
        return layer;
    }

    function inpatientVisualClassifyLisItem(item) {
        if (!progressPlain(item && item.value) && !progressPlain(item && item.flag)) {
            return {abnormal:false, direction:''};
        }
        return progressLisPacsLisClassifyItem(item);
    }

    function inpatientVisualValidateCacheIdentity(identity, cache) {
        const expected = progressPlain(identity && identity.inpatientNo);
        const actual = progressPlain(cache && cache.identity && cache.identity.inpatientNo);
        if (expected && actual && !progressLisPacsPacsAdmissionMatches(expected, actual)) {
            throw new Error('基线缓存住院号与当前目标患者不一致，请重新提取');
        }
    }

    function inpatientOpenBaselineVisualization(settings) {
        const options = settings || {};
        const value = String(options.value || '').trim();
        if (!value) throw new Error('当前没有基线数据，请先提取或录入资料');
        const identity = options.identity || {};
        const originalCache = options.cache || {};
        inpatientVisualValidateCacheIdentity(identity, originalCache);
        const sourceText = options.kind === 'order' ? originalCache.orderText : originalCache.rawText;
        const changed = typeof sourceText === 'string' && sourceText.trim() !== value;
        const cache = changed ? {} : originalCache;
        const record = {name:identity.name || '',bedNo:progressPlain(identity.bed || identity.bedNo).replace(/床/g,''),
            admissionNo:identity.inpatientNo || '',
            baselineVitalSignsRange:cache.queryStart && cache.queryEnd ? cache.queryStart+' 至 '+cache.queryEnd : '',
            baselineVitalSignsSource:cache.captureMode || '当前三测单基线',
            baselineVitalSignsCapturedAt:cache.capturedAt || '',
            baselineLisPacsRange:cache.queryStart && cache.queryEnd ? cache.queryStart+' 至 '+cache.queryEnd : '',
            baselineExtendedLisText:changed ? '' : options.extendedText || ''};
        const kind = options.kind || 'text';
        if (kind === 'vital') {
            let data;
            try {data = JSON.parse(value);} catch (error) {
                throw new Error('三测单原始基线不是有效JSON，请核对后再渲染');
            }
            if (Array.isArray(data)) data = {list:data};
            if (!data || !Array.isArray(data.list)) throw new Error('三测单原始JSON缺少list数组，无法绘制趋势');
            progressVitalSignsValidatePatient(data,identity);
            const returnedNo = progressPlain(data.patInfo && (data.patInfo.zyh || data.patInfo.ZYH || data.patInfo.住院号));
            if (returnedNo && identity.inpatientNo && !progressLisPacsPacsAdmissionMatches(returnedNo, identity.inpatientNo)) {
                throw new Error('三测单基线住院号与当前目标患者不一致');
            }
            return inpatientBaselineVisualOpenVitalVisual(null,data,record);
        }
        if (kind === 'lis') {
            const data = progressLisPacsLisPacsParseBaseline(value);
            const number = data.patient && (data.patient.inpatientNo || data.patient.admissionNo);
            if (number && identity.inpatientNo && !progressLisPacsPacsAdmissionMatches(number,identity.inpatientNo)) {
                throw new Error('LIS/PACS基线住院号与目标患者不一致');
            }
            if (Array.isArray(data.pacs.reports)) {
                data.pacs.reports.forEach(function (report) {
                    const reportNo = report && report.hisId;
                    if (reportNo && identity.inpatientNo && !progressLisPacsPacsAdmissionMatches(reportNo,identity.inpatientNo)) {
                        throw new Error('PACS报告住院号与目标患者不一致');
                    }
                });
            }
            if (record.baselineExtendedLisText) {
                const ext = JSON.parse(record.baselineExtendedLisText);
                const extNo = ext.patient && (ext.patient.admissionNo || ext.patient.inpatientNo);
                if (extNo && identity.inpatientNo && !progressLisPacsPacsAdmissionMatches(extNo,identity.inpatientNo)) {
                    throw new Error('扩展LIS基线住院号与目标患者不一致');
                }
                if (Array.isArray(ext.reports)) ext.reports.forEach(function (report) {
                    const reportNo = report && report.patientNo;
                    if (reportNo && identity.inpatientNo && !progressLisPacsPacsAdmissionMatches(reportNo,identity.inpatientNo)) {
                        throw new Error('扩展LIS报告住院号与目标患者不一致');
                    }
                });
            }
            const layer = inpatientBaselineVisualOpenLisPacsVisual(null,data,record);
            const warnings = Array.from(new Set(
                (Array.isArray(data.warnings) ? data.warnings : [])
                .concat(Array.isArray(cache.warnings) ? cache.warnings : []).filter(Boolean)));
            if (warnings.length) {
                const note = document.createElement('div');note.className = 'lis-pacs-visual-note';
                note.textContent = '接口读取提示：'+warnings.join('；')+'。缺失报告不能视为阴性结果。';
                layer.querySelector('.lis-pacs-visual-body').prepend(note);
            }
            return layer;
        }
        if (kind === 'order') {
            let records = !changed && Array.isArray(cache.records) && cache.records.length
                ? cache.records.filter(function (row) {return row && progressPlain(row.name);})
                : inpatientVisualParseOrders(value);
            if (/^[\[{]/.test(value)) {
                try {
                    const data = JSON.parse(value);
                    const rows = Array.isArray(data) ? data : data.records;
                    if (Array.isArray(rows)) records = rows.filter(function (row) {return row && progressPlain(row.name);});
                } catch (error) {}
            }
            if (!changed && Array.isArray(cache.filteredRecords)) {
                records = records.concat(cache.filteredRecords.filter(function (row) { return row && progressPlain(row.name); }));
            }
            if (records.length) return inpatientBaselineVisualOpenOrderVisual(null,{records:records},record);
            return inpatientOpenTextBaselineVisual(value,Object.assign({},options,{note:'未识别到结构化医嘱字段，保留原文展示。'}));
        }
        return inpatientOpenTextBaselineVisual(value,options);
    }
    function inpatientBaselineVisualVitalDate(value) {
        const text = String(value == null ? '' : value).trim();
        let match = text.match(/(20\d{2})[-\/.年](\d{1,2})[-\/.月](\d{1,2})/);
        if (!match) return '';
        return match[1] + '-' +
            String(Number(match[2])).padStart(2, '0') + '-' +
            String(Number(match[3])).padStart(2, '0');
    }

    function inpatientBaselineVisualVitalValue(row, keys) {
        const source = row && typeof row === 'object' ? row : {};
        for (const key of keys) {
            if (
                Object.prototype.hasOwnProperty.call(source, key) &&
                source[key] !== null && source[key] !== undefined &&
                String(source[key]).trim() !== ''
            ) {
                return String(source[key]).trim();
            }
        }
        const lower = {};
        Object.keys(source).forEach(function (key) {
            lower[String(key).toLowerCase()] = source[key];
        });
        for (const key of keys) {
            const value = lower[String(key).toLowerCase()];
            if (value !== null && value !== undefined && String(value).trim() !== '') {
                return String(value).trim();
            }
        }
        return '';
    }

    function inpatientVisualVitalDisplayTime(value) {
        const text = inpatientVisualOneLine(value);
        if (!text) return '';
        if (/^\d{1,2}$/.test(text)) {
            const hour = Math.max(0, Math.min(23, Number(text)));
            return String(hour).padStart(2, '0') + ':00';
        }
        if (/^\d{3,4}$/.test(text)) {
            const padded = text.padStart(4, '0');
            const hour = Number(padded.slice(0, 2));
            const minute = Number(padded.slice(2, 4));
            if (hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59) {
                return padded.slice(0, 2) + ':' + padded.slice(2, 4);
            }
        }
        const match = text.match(/(?:^|\s)(\d{1,2}):(\d{2})(?::\d{2})?/);
        if (match) {
            return String(match[1]).padStart(2, '0') + ':' + match[2];
        }
        return text;
    }

    function inpatientBaselineVisualVitalNumericValue(value) {
        const text = String(value == null ? '' : value)
            .replace(/，/g, ',')
            .replace(/,/g, '.')
            .trim();
        if (!text) return null;
        const match = text.match(/-?\d+(?:\.\d+)?/);
        if (!match) return null;
        const number = Number(match[0]);
        return Number.isFinite(number) ? number : null;
    }

    function inpatientBaselineVisualVitalVisualSortValue(date, time, fallbackIndex) {
        const parts = String(date || '').split('-').map(Number);
        if (parts.length !== 3 || parts.some(function (item) {
            return !Number.isFinite(item);
        })) {
            return Number(fallbackIndex) || 0;
        }
        let hour = 12;
        let minute = 0;
        const match = String(time || '').match(/^(\d{1,2}):(\d{2})/);
        if (match) {
            hour = Math.max(0, Math.min(23, Number(match[1])));
            minute = Math.max(0, Math.min(59, Number(match[2])));
        }
        return Date.UTC(
            parts[0],
            Math.max(0, parts[1] - 1),
            Math.max(1, parts[2]),
            hour,
            minute
        ) + (Number(fallbackIndex) || 0) / 1000;
    }

    function inpatientBaselineVisualVitalVisualPayload(data, record) {
        const source = data && typeof data === 'object' ? data : {};
        const sourceRecord = record && typeof record === 'object' ? record : {};
        const rows = Array.isArray(source.list)
            ? source.list.filter(function (row) {
                return row && typeof row === 'object' && !Array.isArray(row);
            })
            : [];
        const merged = new Map();
        rows.forEach(function (row, index) {
            const date = inpatientBaselineVisualVitalDate(
                inpatientBaselineVisualVitalValue(row, ['rq', 'RQ', 'date', 'Date'])
            );
            if (!date) return;
            const rawTime = inpatientBaselineVisualVitalValue(
                row,
                ['sj', 'SJ', 'time', 'Time']
            );
            const time = inpatientVisualVitalDisplayTime(rawTime);
            const mergeKey = date + '|' + (time || ('row-' + index));
            const point = merged.get(mergeKey) || {
                date: date,
                time: time,
                label: date + (time ? ' ' + time : ''),
                temperature: null,
                pulse: null,
                respiration: null,
                systolic: null,
                diastolic: null,
                _sort: inpatientBaselineVisualVitalVisualSortValue(date, time, index)
            };

            const temperature = inpatientBaselineVisualVitalNumericValue(
                inpatientBaselineVisualVitalValue(row, ['tw', 'TW'])
            );
            const pulse = inpatientBaselineVisualVitalNumericValue(
                inpatientBaselineVisualVitalValue(row, ['mb', 'MB']) ||
                inpatientBaselineVisualVitalValue(row, ['xl', 'XL'])
            );
            const respiration = inpatientBaselineVisualVitalNumericValue(
                inpatientBaselineVisualVitalValue(row, ['hx', 'HX'])
            );
            const systolic = inpatientBaselineVisualVitalNumericValue(
                inpatientBaselineVisualVitalValue(row, ['xysz', 'XYSZ'])
            );
            const diastolic = inpatientBaselineVisualVitalNumericValue(
                inpatientBaselineVisualVitalValue(row, ['xyxz', 'XYXZ'])
            );

            if (temperature !== null) point.temperature = temperature;
            if (pulse !== null) point.pulse = pulse;
            if (respiration !== null) point.respiration = respiration;

            /* HIS偶见0/0血压占位：仅在收缩压、舒张压同时为0时忽略该组BP。 */
            const ignoreZeroBloodPressure =
                systolic === 0 && diastolic === 0;
            if (!ignoreZeroBloodPressure) {
                if (systolic !== null) point.systolic = systolic;
                if (diastolic !== null) point.diastolic = diastolic;
            }

            if (
                point.temperature !== null ||
                point.pulse !== null ||
                point.respiration !== null ||
                point.systolic !== null ||
                point.diastolic !== null
            ) {
                merged.set(mergeKey, point);
            }
        });

        const points = Array.from(merged.values()).sort(function (a, b) {
            return a._sort - b._sort;
        });
        if (!points.length) return null;

        const rangeObject = source.range && typeof source.range === 'object'
            ? source.range
            : {};
        const startDate = inpatientBaselineVisualVitalDate(rangeObject.startDate) ||
            points[0].date;
        const endDate = inpatientBaselineVisualVitalDate(rangeObject.endDate) ||
            points[points.length - 1].date;
        const rangeLabel = inpatientVisualOneLine(rangeObject.label) ||
            inpatientVisualOneLine(sourceRecord.baselineVitalSignsRange) ||
            (startDate && endDate ? startDate + ' 至 ' + endDate : '');

        return {
            schemaVersion: 1,
            kind: 'inpatient-vital-signs-visual',
            range: {
                label: rangeLabel,
                startDate: startDate,
                endDate: endDate
            },
            source: inpatientVisualOneLine(sourceRecord.baselineVitalSignsSource) ||
                'HIS DrawData',
            capturedAt: inpatientVisualOneLine(
                sourceRecord.baselineVitalSignsCapturedAt
            ),
            sourceCount: rows.length,
            count: points.length,
            points: points.map(function (point) {
                return {
                    date: point.date,
                    time: point.time,
                    label: point.label,
                    temperature: point.temperature,
                    pulse: point.pulse,
                    respiration: point.respiration,
                    systolic: point.systolic,
                    diastolic: point.diastolic,
                    _sort: point._sort
                };
            })
        };
    }

