    function inpatientBaselineVisualVitalVisualLatest(points, key) {
        const list = Array.isArray(points) ? points : [];
        for (let index = list.length - 1; index >= 0; index -= 1) {
            const value = list[index] && list[index][key];
            if (Number.isFinite(value)) {
                return {
                    value: value,
                    label: list[index].label || ''
                };
            }
        }
        return null;
    }

    function inpatientBaselineVisualVitalVisualChartHtml(points, config) {
        const source = Array.isArray(points) ? points : [];
        const settings = config && typeof config === 'object' ? config : {};
        const series = Array.isArray(settings.series) ? settings.series : [];
        const availableValues = [];
        series.forEach(function (item) {
            source.forEach(function (point) {
                const value = point && point[item.key];
                if (Number.isFinite(value)) availableValues.push(value);
            });
        });
        const title = inpatientVisualEscapeHtml(settings.title || '趋势');
        const unit = inpatientVisualEscapeHtml(settings.unit || '');
        if (!availableValues.length) {
            return '<section class="vital-visual-card">' +
                '<div class="vital-visual-card-head"><strong>' + title + '</strong><span>暂无有效记录</span></div>' +
                '<div class="vital-visual-empty">当前范围内没有可绘制的数值记录</div>' +
            '</section>';
        }

        const width = 720;
        const height = 230;
        const left = 54;
        const right = 16;
        const top = 18;
        const bottom = 42;
        const innerWidth = width - left - right;
        const innerHeight = height - top - bottom;
        let minValue = Math.min.apply(null, availableValues);
        let maxValue = Math.max.apply(null, availableValues);
        const padding = Number(settings.padding) || 1;
        if (maxValue === minValue) {
            minValue -= padding;
            maxValue += padding;
        } else {
            const dynamicPadding = Math.max(
                padding,
                (maxValue - minValue) * 0.12
            );
            minValue -= dynamicPadding;
            maxValue += dynamicPadding;
        }

        const xValues = source.map(function (point, index) {
            return Number(point && point._sort) || index;
        });
        let minX = Math.min.apply(null, xValues);
        let maxX = Math.max.apply(null, xValues);
        let useIndexScale = false;
        if (!Number.isFinite(minX) || !Number.isFinite(maxX) || minX === maxX) {
            useIndexScale = true;
            minX = 0;
            maxX = Math.max(1, source.length - 1);
        }
        function xOf(point, index) {
            if (source.length === 1) {
                return left + innerWidth / 2;
            }
            const xValue = Number(point && point._sort);
            const safeX = useIndexScale
                ? index
                : (Number.isFinite(xValue) ? xValue : index);
            return left + (safeX - minX) / (maxX - minX) * innerWidth;
        }
        function yOf(value) {
            return top + (maxValue - value) / (maxValue - minValue) * innerHeight;
        }

        const grid = [];
        for (let tick = 0; tick <= 4; tick += 1) {
            const ratio = tick / 4;
            const y = top + ratio * innerHeight;
            const value = maxValue - ratio * (maxValue - minValue);
            grid.push(
                '<line x1="' + left + '" y1="' + y.toFixed(2) + '" x2="' + (width - right) + '" y2="' + y.toFixed(2) + '" stroke="#e5eaee" stroke-width="1"/>' +
                '<text x="' + (left - 7) + '" y="' + (y + 4).toFixed(2) + '" text-anchor="end" font-size="10" fill="#7b8790">' +
                    inpatientVisualEscapeHtml((Math.round(value * 10) / 10).toString()) +
                '</text>'
            );
        }

        const xLabels = [];
        const labelCount = Math.min(6, source.length);
        const used = new Set();
        for (let labelIndex = 0; labelIndex < labelCount; labelIndex += 1) {
            const index = labelCount === 1
                ? 0
                : Math.round(labelIndex * (source.length - 1) / (labelCount - 1));
            if (used.has(index)) continue;
            used.add(index);
            const point = source[index];
            const x = xOf(point, index);
            const label = point
                ? String(point.date || '').slice(5) + (point.time ? ' ' + point.time : '')
                : '';
            xLabels.push(
                '<text x="' + x.toFixed(2) + '" y="' + (height - 13) + '" text-anchor="middle" font-size="9.5" fill="#7b8790">' +
                    inpatientVisualEscapeHtml(label) +
                '</text>'
            );
        }

        const seriesHtml = [];
        series.forEach(function (item) {
            const values = [];
            source.forEach(function (point, index) {
                const value = point && point[item.key];
                if (!Number.isFinite(value)) return;
                values.push({
                    point: point,
                    index: index,
                    value: value,
                    x: xOf(point, index),
                    y: yOf(value)
                });
            });
            const segments = [];
            for (let index = 1; index < values.length; index += 1) {
                const previous = values[index - 1];
                const current = values[index];
                const gap = Math.abs(
                    (Number(current.point && current.point._sort) || 0) -
                    (Number(previous.point && previous.point._sort) || 0)
                );
                if (gap > 36 * 60 * 60 * 1000) continue;
                segments.push(
                    '<line x1="' + previous.x.toFixed(2) + '" y1="' + previous.y.toFixed(2) + '" x2="' + current.x.toFixed(2) + '" y2="' + current.y.toFixed(2) + '" stroke="' + item.color + '" stroke-width="2.2" stroke-linecap="round"/>'
                );
            }
            values.forEach(function (entry) {
                segments.push(
                    '<circle cx="' + entry.x.toFixed(2) + '" cy="' + entry.y.toFixed(2) + '" r="3.5" fill="#fff" stroke="' + item.color + '" stroke-width="2">' +
                        '<title>' + inpatientVisualEscapeHtml(
                            (entry.point.label || '') + '　' +
                            (item.label || settings.title || '') + '：' +
                            entry.value + (settings.unit || '')
                        ) + '</title>' +
                    '</circle>'
                );
            });
            seriesHtml.push(segments.join(''));
        });

        const legends = series.map(function (item) {
            return '<span style="display:inline-flex;align-items:center;gap:4px;margin-left:8px;">' +
                '<i style="display:inline-block;width:10px;height:3px;background:' + item.color + ';border-radius:2px;"></i>' +
                inpatientVisualEscapeHtml(item.label || '') +
            '</span>';
        }).join('');

        const latestParts = series.map(function (item) {
            const latest = inpatientBaselineVisualVitalVisualLatest(source, item.key);
            return latest
                ? inpatientVisualEscapeHtml(item.label || '') + ' ' + inpatientVisualEscapeHtml(String(latest.value)) + unit
                : '';
        }).filter(Boolean);

        return '<section class="vital-visual-card">' +
            '<div class="vital-visual-card-head"><strong>' + title + legends + '</strong><span>' +
                inpatientVisualEscapeHtml(latestParts.join('　') || '暂无有效记录') +
            '</span></div>' +
            '<div class="vital-visual-chart">' +
                '<svg viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="' + title + '趋势图">' +
                    grid.join('') +
                    '<line x1="' + left + '" y1="' + (height - bottom) + '" x2="' + (width - right) + '" y2="' + (height - bottom) + '" stroke="#b9c4cb" stroke-width="1"/>' +
                    xLabels.join('') +
                    seriesHtml.join('') +
                '</svg>' +
            '</div>' +
        '</section>';
    }

    function inpatientBaselineVisualOpenVitalVisual(modal, directData, directRecord) {
        const section = directData
            ? null
            : inpatientVisualSection(modal, 'vitals');
        if (!directData && (!section || !section._baselineVitalData)) {
            throw new Error('请先点击“提取三测单”取得当前患者DrawData基线');
        }
        const data = directData || section._baselineVitalData;
        const record = directRecord ||
            (modal && modal._inpatientBaselineVisualRecord) || {};
        const payload = inpatientBaselineVisualVitalVisualPayload(data, record);
        if (!payload || !Array.isArray(payload.points) || !payload.points.length) {
            throw new Error('当前三测基线没有可渲染的T/P/R/BP数值记录');
        }

        inpatientBaselineVisualEnsureVitalVisualStyle();
        const old = document.getElementById(INPATIENT_BASELINE_VITAL_VISUAL_MODAL_ID);
        if (old) old.remove();
        const layer = document.createElement('div');
        layer.id = INPATIENT_BASELINE_VITAL_VISUAL_MODAL_ID;
        layer.className = 'show';
        layer.setAttribute('role', 'dialog');
        layer.setAttribute('aria-modal', 'true');
        layer.setAttribute('aria-label', '三测基线趋势可视化');
        layer.tabIndex = -1;

        const patientText = [
            inpatientVisualCleanBed(record && record.bedNo)
                ? inpatientVisualCleanBed(record.bedNo) + '床'
                : '',
            inpatientVisualOneLine(record && record.name),
            progressPlain(record && record.admissionNo)
                ? '住院号' + progressPlain(record.admissionNo)
                : ''
        ].filter(Boolean).join(' / ') || '当前患者';

        layer.innerHTML =
            '<div class="vital-visual-mask"></div>' +
            '<div class="vital-visual-dialog">' +
                '<div class="vital-visual-header">' +
                    '<strong>三测基线趋势可视化</strong>' +
                    '<button type="button" class="vital-visual-close" title="关闭">×</button>' +
                '</div>' +
                '<div class="vital-visual-meta">' +
                    '<div class="vital-visual-meta-main">' +
                        '<b>' + inpatientVisualEscapeHtml(patientText) + '</b>' +
                        '<span>来源：' + inpatientVisualEscapeHtml(payload.source || 'HIS DrawData') + '</span>' +
                        '<span>范围：' + inpatientVisualEscapeHtml(payload.range.label || '范围未返回') + '</span>' +
                        '<span>原始记录：' + inpatientVisualEscapeHtml(String(payload.sourceCount || 0)) + ' 条</span>' +
                        '<span>有效趋势点：' + inpatientVisualEscapeHtml(String(payload.count || 0)) + ' 个</span>' +
                    '</div>' +
                    '<div class="vital-visual-toolbar">' +
                        '<div class="vital-visual-range">' +
                            '<button type="button" data-vital-range="3">近3天</button>' +
                            '<button type="button" class="active" data-vital-range="7">近7天</button>' +
                            '<button type="button" data-vital-range="all">全部</button>' +
                        '</div>' +
                        '<div class="vital-visual-current"></div>' +
                    '</div>' +
                    '<div class="vital-visual-summary"></div>' +
                '</div>' +
                '<div class="vital-visual-body"><div class="vital-visual-grid"></div></div>' +
                '<div class="vital-visual-footer">只读趋势视图：严格从当前DrawData原始JSON解析T/P/R/BP实际记录点；不读取程序预处理文本或AI结果，不补造缺失数值；相邻实际记录间超过36小时自动断线。鼠标悬停数据点可查看日期、时间和原始数值。本视图不调用AI，不修改三测基线，不写回患者缓存或HIS。</div>' +
            '</div>';
        document.body.appendChild(layer);

        const close = function () { layer.remove(); };
        layer.querySelector('.vital-visual-close').addEventListener('click', close);
        layer.querySelector('.vital-visual-mask').addEventListener('click', close);
        layer.addEventListener('keydown', function (event) {
            if (event.key === 'Escape') close();
        });

        const summary = layer.querySelector('.vital-visual-summary');
        const grid = layer.querySelector('.vital-visual-grid');
        const current = layer.querySelector('.vital-visual-current');
        const rangeButtons = Array.from(
            layer.querySelectorAll('[data-vital-range]')
        );

        function filterPoints(mode) {
            if (mode === 'all') return payload.points.slice();
            const days = Math.max(1, Number(mode) || 7);
            const latest = payload.points[payload.points.length - 1];
            const latestDate = String(latest && latest.date || '').split('-').map(Number);
            if (latestDate.length !== 3 || latestDate.some(function (item) {
                return !Number.isFinite(item);
            })) {
                return payload.points.slice();
            }
            const latestDay = Date.UTC(
                latestDate[0],
                latestDate[1] - 1,
                latestDate[2]
            );
            const cutoff = latestDay - (days - 1) * 24 * 60 * 60 * 1000;
            return payload.points.filter(function (point) {
                const parts = String(point && point.date || '').split('-').map(Number);
                if (parts.length !== 3 || parts.some(function (item) {
                    return !Number.isFinite(item);
                })) return false;
                const day = Date.UTC(parts[0], parts[1] - 1, parts[2]);
                return day >= cutoff && day <= latestDay;
            });
        }

        function summaryCard(label, value) {
            return '<div class="vital-visual-summary-card"><span>' +
                inpatientVisualEscapeHtml(label) + '</span><strong>' +
                inpatientVisualEscapeHtml(value || '—') + '</strong></div>';
        }

        function render(mode) {
            const points = filterPoints(mode);
            const temperature = inpatientBaselineVisualVitalVisualLatest(points, 'temperature');
            const pulse = inpatientBaselineVisualVitalVisualLatest(points, 'pulse');
            const respiration = inpatientBaselineVisualVitalVisualLatest(points, 'respiration');
            const bloodPressure = points.slice().reverse().find(function (point) {
                return point.systolic !== null && point.diastolic !== null;
            });

            summary.innerHTML =
                summaryCard('最新体温', temperature ? temperature.value + '℃' : '—') +
                summaryCard('最新脉搏', pulse ? pulse.value + '次/分' : '—') +
                summaryCard('最新呼吸', respiration ? respiration.value + '次/分' : '—') +
                summaryCard('最新完整血压', bloodPressure
                    ? bloodPressure.systolic + '/' + bloodPressure.diastolic + 'mmHg'
                    : '—');

            const label = mode === 'all'
                ? '全部记录'
                : '近' + mode + '天';
            current.textContent = label + '：' + points.length + ' 个有效趋势时间点';

            grid.innerHTML =
                inpatientBaselineVisualVitalVisualChartHtml(points, {
                    title: '体温 T',
                    unit: '℃',
                    padding: 0.5,
                    series: [
                        { key: 'temperature', label: '体温', color: '#dc2626' }
                    ]
                }) +
                inpatientBaselineVisualVitalVisualChartHtml(points, {
                    title: '脉搏 P',
                    unit: '次/分',
                    padding: 5,
                    series: [
                        { key: 'pulse', label: '脉搏', color: '#2563eb' }
                    ]
                }) +
                inpatientBaselineVisualVitalVisualChartHtml(points, {
                    title: '呼吸 R',
                    unit: '次/分',
                    padding: 3,
                    series: [
                        { key: 'respiration', label: '呼吸', color: '#059669' }
                    ]
                }) +
                inpatientBaselineVisualVitalVisualChartHtml(points, {
                    title: '血压 BP',
                    unit: 'mmHg',
                    padding: 10,
                    series: [
                        { key: 'systolic', label: '收缩压', color: '#ea580c' },
                        { key: 'diastolic', label: '舒张压', color: '#7c3aed' }
                    ]
                });
        }

        rangeButtons.forEach(function (button) {
            button.addEventListener('click', function () {
                rangeButtons.forEach(function (item) {
                    item.classList.toggle('active', item === button);
                });
                render(button.dataset.vitalRange || '7');
            });
        });
        render('7');
        try { layer.focus(); } catch (error) {}
        return layer;
    }


