    function loadFirstCoursePrompt() {
        try {
            return localStorage.getItem(
                FIRST_COURSE_PROMPT_STORAGE_KEY
            ) || DEFAULT_FIRST_COURSE_PROMPT;
        } catch (error) {
            return DEFAULT_FIRST_COURSE_PROMPT;
        }
    }

    function saveFirstCoursePrompt(value) {
        try {
            localStorage.setItem(
                FIRST_COURSE_PROMPT_STORAGE_KEY,
                String(value || '')
            );
        } catch (error) {
            // 本地保存失败不阻止本次生成。
        }
    }

    function loadFirstCourseTargetPatient() {
        try {
            const value = JSON.parse(
                localStorage.getItem(
                    FIRST_COURSE_TARGET_PATIENT_STORAGE_KEY
                ) || 'null'
            );

            return value && typeof value === 'object'
                ? value
                : null;
        } catch (error) {
            return null;
        }
    }

    function saveFirstCourseTargetPatient(identity) {
        if (!identity || (!identity.name && !identity.inpatientNo)) return;

        try {
            localStorage.setItem(
                FIRST_COURSE_TARGET_PATIENT_STORAGE_KEY,
                JSON.stringify(identity)
            );
        } catch (error) {
            // 忽略。
        }
    }

    function loadFirstCourseAdmissionStore() {
        return inpatientLargeCacheReadStore(
            FIRST_COURSE_ADMISSION_CACHE_STORAGE_KEY
        );
    }

    function saveFirstCourseAdmissionCache(entry) {
        const key = patientIdentityKey(entry && entry.identity);

        if (!key) {
            throw new Error('无法生成患者身份缓存键');
        }

        const store = loadFirstCourseAdmissionStore();
        store[key] = entry;

        inpatientLargeCacheWriteStore(
            FIRST_COURSE_ADMISSION_CACHE_STORAGE_KEY,
            store
        );

        return key;
    }

    function findFirstCourseAdmissionCache(identity) {
        const store = loadFirstCourseAdmissionStore();
        const directKey = patientIdentityKey(identity);

        if (directKey && store[directKey]) {
            return store[directKey];
        }

        return Object.keys(store)
            .map(function (key) { return store[key]; })
            .find(function (entry) {
                return entry &&
                    patientIdentityMatches(entry.identity, identity);
            }) || null;
    }

    function clearFirstCourseAdmissionCache(identity) {
        const store = loadFirstCourseAdmissionStore();
        let changed = false;

        Object.keys(store).forEach(function (key) {
            const entry = store[key];
            if (
                entry &&
                patientIdentityMatches(entry.identity, identity)
            ) {
                delete store[key];
                changed = true;
            }
        });

        if (changed) {
            inpatientLargeCacheWriteStore(
                FIRST_COURSE_ADMISSION_CACHE_STORAGE_KEY,
                store
            );
        }

        return changed;
    }

    function firstCourseNormalizeDateTime(value) {
        const source = String(value || '')
            .replace(/[年\/.]/g, '-')
            .replace(/月/g, '-')
            .replace(/日/g, ' ')
            .replace(/T/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        const match = source.match(
            /(20\d{2})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/
        );

        if (!match) return '';

        return match[1] + '-' +
            pad2(match[2]) + '-' +
            pad2(match[3]) +
            (match[4] !== undefined
                ? ' ' + pad2(match[4]) + ':' +
                    pad2(match[5]) + ':' +
                    pad2(match[6] || '00')
                : '');
    }

    function firstCourseDateTimeToInput(value) {
        const normalized = firstCourseNormalizeDateTime(value);
        if (!normalized || normalized.length < 16) return '';
        return normalized.replace(' ', 'T').slice(0, 19);
    }

    function firstCourseInputToDateTime(value) {
        const source = String(value || '').trim();
        if (!source) return '';
        return firstCourseNormalizeDateTime(
            source.replace('T', ' ')
        );
    }

    function firstCourseParseDateTime(value) {
        const normalized = firstCourseNormalizeDateTime(value);
        if (!normalized) return null;

        const match = normalized.match(
            /^(20\d{2})-(\d{2})-(\d{2})(?:\s+(\d{2}):(\d{2}):(\d{2}))?$/
        );
        if (!match) return null;

        const date = new Date(
            Number(match[1]),
            Number(match[2]) - 1,
            Number(match[3]),
            Number(match[4] || 0),
            Number(match[5] || 0),
            Number(match[6] || 0)
        );

        return Number.isNaN(date.getTime()) ? null : date;
    }

    function firstCourseExtractLabelDateTime(textValue, label) {
        const text = String(textValue || '');
        const escaped = String(label || '')
            .replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const regex = new RegExp(
            escaped +
            '\\s*[：:]?\\s*' +
            '((?:20\\d{2})[年\\-\\/.]\\d{1,2}[月\\-\\/.]\\d{1,2}日?' +
            '(?:\\s+\\d{1,2}:\\d{2}(?::\\d{2})?)?)',
            'i'
        );
        const match = text.match(regex);

        return match
            ? firstCourseNormalizeDateTime(match[1])
            : '';
    }

    function looksLikeAdmissionRecordPreviewText(textValue, identity) {
        const text = String(textValue || '');
        const normalized = progressNormalize(text);

        if (text.length < 700) return false;
        if (!/入\s*院\s*记\s*录|入院记录/.test(text)) return false;
        if (!/主诉/.test(text) || !/现病史/.test(text)) return false;
        if (!/入院日期|入院时间/.test(text)) return false;

        if (identity) {
            if (
                identity.name &&
                !normalized.includes(progressNormalize(identity.name))
            ) {
                return false;
            }

            if (
                identity.inpatientNo &&
                !normalized.includes(progressNormalize(identity.inpatientNo))
            ) {
                return false;
            }
        }

        return true;
    }

    function collectCurrentAdmissionRecordSource(identity) {
        const candidates = [];

        getAllDocuments().forEach(function (doc) {
            const text = collectVisiblePageText(doc, 65000);

            if (!looksLikeAdmissionRecordPreviewText(text, identity)) {
                return;
            }

            const normalized = progressNormalize(text);
            let score = 0;

            if (/住院病历附页/.test(text)) score += 80;
            if (/入\s*院\s*记\s*录|入院记录/.test(text)) score += 140;
            if (/既往史/.test(text)) score += 25;
            if (/个人史/.test(text)) score += 15;
            if (/体格检查|查体/.test(text)) score += 35;
            if (/中医|舌|脉/.test(text)) score += 20;
            if (/初步诊断|入院诊断/.test(text)) score += 40;

            if (
                identity && identity.name &&
                normalized.includes(progressNormalize(identity.name))
            ) {
                score += 90;
            }

            if (
                identity && identity.inpatientNo &&
                normalized.includes(progressNormalize(identity.inpatientNo))
            ) {
                score += 120;
            }

            const admissionTime =
                firstCourseExtractLabelDateTime(text, '入院日期') ||
                firstCourseExtractLabelDateTime(text, '入院时间');
            const recordTime =
                firstCourseExtractLabelDateTime(text, '记录日期') ||
                firstCourseExtractLabelDateTime(text, '记录时间');

            if (admissionTime) score += 50;
            if (recordTime) score += 50;

            candidates.push({
                text: text,
                score: score,
                admissionTime: admissionTime,
                recordTime: recordTime
            });
        });

        candidates.sort(function (a, b) {
            return b.score - a.score;
        });

        if (!candidates.length || candidates[0].score < 180) {
            return {
                text: '',
                admissionTime: '',
                recordTime: '',
                score: 0
            };
        }

        return candidates[0];
    }

    function firstCourseOrderSnapshot(cache, cutoffValue) {
        const cutoff = firstCourseParseDateTime(cutoffValue);
        const records = cache && Array.isArray(cache.records)
            ? cache.records
            : [];

        if (!records.length) {
            return {
                text: String(cache && cache.orderText || ''),
                count: Number(cache && cache.orderCount || 0),
                excludedAfterCutoff: 0,
                maskedLaterStop: 0,
                legacy: true
            };
        }

        let excludedAfterCutoff = 0;
        let maskedLaterStop = 0;
        const selected = [];

        records.forEach(function (raw) {
            const record = Object.assign({}, raw || {});
            const startTime = firstCourseParseDateTime(record.startTime);

            if (cutoff && startTime && startTime > cutoff) {
                excludedAfterCutoff++;
                return;
            }

            const stopTime = firstCourseParseDateTime(record.stopTime);
            const lastExecutionTime =
                firstCourseParseDateTime(record.lastExecutionTime);

            if (cutoff && stopTime && stopTime > cutoff) {
                record.stopTime = '';
                record.stopDoctor = '';
                record.status = '执行（按首次病程记录时点截断；后续停止信息已屏蔽）';
                maskedLaterStop++;
            }

            if (
                cutoff &&
                lastExecutionTime &&
                lastExecutionTime > cutoff
            ) {
                record.lastExecutionTime = '';
            }

            selected.push(record);
        });

        const lines = [
            '【首次病程AI医嘱时点快照】',
            '快照时点：' + (firstCourseNormalizeDateTime(cutoffValue) || '未提供精确时点'),
            '说明：脚本已排除快照时点之后才开始的医嘱；快照之后的停止时间、停止医生和最后执行时间已屏蔽，不得倒推至首次病程记录。',
            '说明：“操作”列未提供给AI；医嘱状态必须依据此快照中的开始时间、停止时间及HIS状态判断。',
            ''
        ];

        selected.forEach(function (record, index) {
            lines.push('【医嘱' + (index + 1) + '】');

            PROGRESS_ORDER_FIELD_SPECS.forEach(function (spec) {
                const value = progressPlain(record[spec.key]);
                lines.push(spec.label + '：' + value);
            });

            lines.push(
                '医嘱状态判定：' +
                progressOrderStatusJudgement(record)
            );

            if (record._hiddenByClinicalPath) {
                lines.push(
                    '页面显示备注：该医嘱虽被临床路径脚本隐藏，仍已纳入真实医嘱快照'
                );
            }

            lines.push('');
        });

        return {
            text: lines.join('\n').trim().slice(0, 95000),
            count: selected.length,
            excludedAfterCutoff: excludedAfterCutoff,
            maskedLaterStop: maskedLaterStop,
            legacy: false
        };
    }

    /**
     * v2.24 首次病程专用“直接正文”请求。
     * 某些模型会把max_tokens大量消耗在reasoning_content，最终message.content为空，
     * 甚至finish_reason=length。该函数不要求JSON模式，优先用于自动降级重试，
     * 让模型直接返回首程正文，减少格式包装与推理额度对最终输出的挤占。
     */
    function progressDeepSeekPlainTextRequest(
        apiKey,
        model,
        systemPrompt,
        userPayload,
        maxTokens,
        timeoutMs,
        taskLabel
    ) {
        return new Promise(function (resolve, reject) {
            if (PROGRESS_GENERATION_ABORT.cancelled) {
                reject(createProgressAbortError());
                return;
            }

            let request = null;

            request = suiteGlobalAiXmlhttpRequest({
                method: 'POST',
                url: 'https://api.deepseek.com/chat/completions',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + apiKey
                },
                data: JSON.stringify({
                    model: model,
                    messages: [
                        {
                            role: 'system',
                            content: systemPrompt
                        },
                        {
                            role: 'user',
                            content: JSON.stringify(userPayload)
                        }
                    ],
                    temperature: 0.05,
                    max_tokens: maxTokens,
                    stream: false
                }),
                timeout: timeoutMs,
                onload: function (response) {
                    if (PROGRESS_GENERATION_ABORT.activeRequest === request) {
                        PROGRESS_GENERATION_ABORT.activeRequest = null;
                    }

                    if (PROGRESS_GENERATION_ABORT.cancelled) {
                        reject(createProgressAbortError());
                        return;
                    }

                    if (response.status < 200 || response.status >= 300) {
                        reject(new Error(
                            (taskLabel || 'DeepSeek直出请求') +
                            '失败（HTTP ' + response.status + '）：' +
                            String(response.responseText || '').slice(0, 1200)
                        ));
                        return;
                    }

                    try {
                        const body = JSON.parse(response.responseText || '{}');
                        const choice = body && body.choices && body.choices[0]
                            ? body.choices[0]
                            : null;
                        const message = choice && choice.message
                            ? choice.message
                            : null;
                        const content = progressMessageText(message) ||
                            String(body.output_text || choice && choice.text || '').trim();

                        if (!content) {
                            const finishReason = choice && choice.finish_reason
                                ? String(choice.finish_reason)
                                : '';
                            const reasoningLength = message &&
                                typeof message.reasoning_content === 'string'
                                ? message.reasoning_content.length
                                : 0;
                            const error = new Error(
                                'DeepSeek直出模式仍未返回最终正文' +
                                (finishReason ? '（finish_reason=' + finishReason + '）' : '') +
                                (reasoningLength
                                    ? '；检测到推理内容' + reasoningLength + '字符'
                                    : '')
                            );
                            error.name = 'ProgressAiEmptyContentError';
                            error.finishReason = finishReason;
                            error.reasoningLength = reasoningLength;
                            throw error;
                        }

                        resolve(
                            content
                                .replace(/^```(?:text|markdown|json)?\s*/i, '')
                                .replace(/\s*```$/i, '')
                                .trim()
                        );
                    } catch (error) {
                        if (error && error.name === 'ProgressAiEmptyContentError') {
                            reject(error);
                            return;
                        }
                        reject(new Error(
                            (taskLabel || 'DeepSeek直出请求') +
                            '结果解析失败：' + error.message
                        ));
                    }
                },
                onerror: function () {
                    if (PROGRESS_GENERATION_ABORT.activeRequest === request) {
                        PROGRESS_GENERATION_ABORT.activeRequest = null;
                    }
                    if (PROGRESS_GENERATION_ABORT.cancelled) {
                        reject(createProgressAbortError());
                        return;
                    }
                    reject(new Error(
                        (taskLabel || 'DeepSeek直出请求') + '网络请求失败'
                    ));
                },
                ontimeout: function () {
                    if (PROGRESS_GENERATION_ABORT.activeRequest === request) {
                        PROGRESS_GENERATION_ABORT.activeRequest = null;
                    }
                    if (PROGRESS_GENERATION_ABORT.cancelled) {
                        reject(createProgressAbortError());
                        return;
                    }
                    const error = new Error(
                        (taskLabel || 'DeepSeek直出请求') + '超时'
                    );
                    error.name = 'ProgressAiTimeoutError';
                    reject(error);
                },
                onabort: function () {
                    if (PROGRESS_GENERATION_ABORT.activeRequest === request) {
                        PROGRESS_GENERATION_ABORT.activeRequest = null;
                    }
                    reject(createProgressAbortError());
                }
            });

            PROGRESS_GENERATION_ABORT.activeRequest = request;

            if (PROGRESS_GENERATION_ABORT.cancelled) {
                abortProgressGeneration();
                reject(createProgressAbortError());
            }
        });
    }

    function firstCourseDirectSystemPrompt() {
        return [
            '你是中国医院住院病历“首次病程记录”整理助手。',
            '必须严格执行customPrompt中的全部规范，严格依据原始资料，不得虚构。',
            'admissionRecordText是当前患者入院记录预览正文；cachedOrderInformation是按firstCourseRecordTime截断后的真实医嘱快照。',
            '不得使用首次病程记录时点之后才获得的检查结果或之后才开立/停止/执行的医嘱信息。',
            '诊疗计划只能使用医嘱快照中能够确认在firstCourseRecordTime之前已经开立的内容。',
            '不要输出思考过程、分析过程、资料来源、JSON、Markdown或代码块。',
            '直接从“yyyy-mm-dd hh:mm　　　　　　首次病程记录”开始输出完整最终正文。',
            '必须完整包含：固定开头、病例特点1-6项、初步诊断、诊断依据、中医及西医鉴别诊断、诊疗计划、医师签名。',
            '各段不得缺失；完成“医师签名：”后立即结束。'
        ].join('\n');
    }

    function firstCourseSystemPrompt() {
        return [
            '你是中国医院住院病历“首次病程记录”整理助手。',
            '必须严格执行customPrompt中的全部规范。',
            'admissionRecordText是当前患者入院记录预览正文，是首程患者基本资料、主诉、现病史、既往史、查体、中医四诊和入院诊断的主要依据。',
            'cachedOrderInformation是脚本按firstCourseRecordTime生成的医嘱时点快照；不得使用快照时点之后才开始、停止或执行的信息。',
            '不得根据药物用途反推新增诊断，不得根据后来医嘱或后来检查倒改入院时诊断。',
            'supplementalInformation仅可作为人工补充资料。若其中检查/化验只有日期没有具体时间，且未明确写明“入院时已获得/首次病程前已回报”，不得擅自认定其在firstCourseRecordTime之前已经获得；入院记录正文自身已经明确记载的检查结果除外。',
            '若资料之间发生冲突，以入院记录正文和明确时间戳的原始资料为优先，不得自行调和或虚构。',
            '首次病程记录时间必须使用firstCourseRecordTime；入院时间必须使用入院记录中的实际入院时间。',
            '诊疗计划只能使用医嘱时点快照中能够确认在firstCourseRecordTime之前已经开立的内容。',
            '最终只输出首次病程记录正文，不得解释、不得分析、不得Markdown。',
            '只返回一层JSON对象：{"text":"首次病程记录正文"}。text字段直接放正文，禁止再次嵌套JSON，禁止把换行写成可见的\\n字符。'
        ].join('\n');
    }

    function firstCourseTextLooksComplete(textValue) {
        const text = String(textValue || '');

        return /首次病程记录/.test(text) &&
            /病例特点/.test(text) &&
            /初步诊断/.test(text) &&
            /诊断依据/.test(text) &&
            /鉴别诊断/.test(text) &&
            /诊疗计划/.test(text) &&
            /医师签名\s*[：:]/.test(text);
    }

    async function generateFirstCourseText(
        settings,
        payload,
        customPrompt,
        statusCallback
    ) {
        resetProgressGenerationAbort();
        const supplement = inpatientSupplementPrepare('firstCourse', payload, customPrompt);
        payload = supplement.payload;
        customPrompt = supplement.customPrompt;
        const supplementSystemPrompt = firstCourseSystemPrompt() + supplement.rules;
        const supplementDirectSystemPrompt = firstCourseDirectSystemPrompt() + supplement.rules;

        const runtime =
            buildMedicalAiRuntimeSettings(
                loadConfig(),
                settings
            );

        const systemPrompt =
            supplementSystemPrompt;

        const directSystemPrompt =
            supplementDirectSystemPrompt;

        const requestPayload =
            Object.assign(
                {},
                payload,
                {
                    customPrompt:
                        customPrompt
                }
            );

        let text = '';
        let primaryError = null;

        /*
         * v2.38默认auto：
         * 首次病程直接deepseek-chat输出正文，不再先让推理模型把额度耗尽。
         */
        if (
            runtime.mode !== 'reasoning'
        ) {
            if (
                typeof statusCallback ===
                'function'
            ) {
                statusCallback(
                    'AI病历模式=' +
                    medicalAiModeLabel(
                        runtime.mode
                    ) +
                    '；正在使用deepseek-chat直接生成首次病程记录……'
                );
            }

            try {
                text =
                    await progressDeepSeekPlainTextRequest(
                        runtime.apiKey,
                        'deepseek-chat',
                        directSystemPrompt,
                        Object.assign(
                            {},
                            requestPayload,
                            {
                                directOutputRequirement:
                                    '直接输出完整首次病程记录最终正文，不输出思考过程、JSON或Markdown。'
                            }
                        ),
                        runtime.plainMaxTokens,
                        285000,
                        '首次病程记录Chat直出'
                    );
            } catch (error) {
                primaryError = error;
                throw error;
            }

            text =
                progressUnwrapGeneratedText(
                    {
                        text: text
                    }
                ).trim();
        } else {
            if (
                typeof statusCallback ===
                'function'
            ) {
                statusCallback(
                    'AI病历模式=推理优先；正在使用' +
                    runtime.writingModel +
                    '生成首次病程记录……'
                );
            }

            try {
                const response =
                    await progressDeepSeekJsonRequest(
                        runtime.apiKey,
                        runtime.writingModel,
                        systemPrompt,
                        requestPayload,
                        runtime.reasoningMaxTokens,
                        285000,
                        '首次病程记录推理生成',
                        true
                    );

                text =
                    progressUnwrapGeneratedText(
                        response
                    ).trim();
            } catch (error) {
                primaryError = error;

                if (
                    !runtime.autoFallbackChat ||
                    !medicalAiRetryableError(
                        error
                    )
                ) {
                    throw error;
                }

                assertProgressGenerationNotAborted();

                if (
                    typeof statusCallback ===
                    'function'
                ) {
                    statusCallback(
                        medicalAiReasoningExhausted(
                            error
                        )
                            ? '当前推理模型输出额度被reasoning_content耗尽，正在按设置自动切换Chat直出……'
                            : '当前推理模型未正常完成正文（' +
                                error.message +
                                '），正在按设置自动切换Chat直出……'
                    );
                }

                text =
                    await progressDeepSeekPlainTextRequest(
                        runtime.apiKey,
                        'deepseek-chat',
                        directSystemPrompt,
                        Object.assign(
                            {},
                            requestPayload,
                            {
                                directOutputRequirement:
                                    '推理模式上一轮未取得完整正文。本轮禁止输出思考过程，直接输出完整首次病程记录最终正文。'
                            }
                        ),
                        runtime.plainMaxTokens,
                        300000,
                        '首次病程记录Chat降级'
                    );

                text =
                    progressUnwrapGeneratedText(
                        {
                            text: text
                        }
                    ).trim();
            }
        }

        if (
            !firstCourseTextLooksComplete(
                text
            )
        ) {
            assertProgressGenerationNotAborted();

            if (
                typeof statusCallback ===
                'function'
            ) {
                statusCallback(
                    '首次返回存在缺段，正在使用长文重试额度（' +
                    runtime.retryMaxTokens +
                    ' Token）从头完整重写……'
                );
            }

            const retryPayload =
                Object.assign(
                    {},
                    requestPayload,
                    {
                        retryRequirement:
                            '上一轮首次病程记录存在缺段。请从头完整重写，必须包含固定开头、病例特点6项、初步诊断、诊断依据、中西医鉴别诊断、诊疗计划和医师签名，不能省略任何章节；禁止输出思考过程。'
                    }
                );

            const retryModel =
                (
                    runtime.mode ===
                        'reasoning' &&
                    !runtime.autoFallbackChat
                )
                    ? runtime.writingModel
                    : 'deepseek-chat';

            const directText =
                await progressDeepSeekPlainTextRequest(
                    runtime.apiKey,
                    retryModel,
                    directSystemPrompt,
                    retryPayload,
                    runtime.retryMaxTokens,
                    360000,
                    '首次病程记录完整性重试'
                );

            text =
                progressUnwrapGeneratedText(
                    {
                        text: directText
                    }
                ).trim();
        }

        if (
            !firstCourseTextLooksComplete(
                text
            )
        ) {
            const detail =
                primaryError &&
                primaryError.reasoningLength
                    ? '；初始推理曾产生' +
                        primaryError.reasoningLength +
                        '字符reasoning_content'
                    : '';

            throw new Error(
                'DeepSeek已返回内容，但首次病程记录仍存在缺段' +
                detail +
                '。请检查输入资料或调整“默认值设置→AI病历Token”后重试。'
            );
        }

        return inpatientSupplementVerifyAndRepair(text, runtime, supplement,
            firstCourseDirectSystemPrompt(), firstCourseTextLooksComplete, statusCallback);
    }

