    function updateFirstCourseModalStatus(modal) {
        const currentIdentity = extractCurrentPatientIdentity();
        const target = loadFirstCourseTargetPatient();
        const unlocked = patientAiLoadUnlocked(
            FIRST_COURSE_PATIENT_UNLOCKED_STORAGE_KEY
        );
        const effectiveIdentity = target || currentIdentity;
        const admissionCache = effectiveIdentity
            ? findFirstCourseAdmissionCache(effectiveIdentity)
            : null;
        const orderCache = effectiveIdentity
            ? findProgressOrderCache(effectiveIdentity)
            : null;

        const patientBox = modal.querySelector('.first-current-patient');
        const admissionBox = modal.querySelector('.first-admission-cache');
        const orderBox = modal.querySelector('.first-order-cache');
        const timeInput = modal.querySelector('.first-record-time');

        if (patientBox) {
            const mismatch = Boolean(
                target &&
                (currentIdentity.name || currentIdentity.inpatientNo) &&
                !patientIdentityMatches(target, currentIdentity)
            );

            patientBox.textContent =
                '当前页面患者：' + patientIdentityLabel(currentIdentity) +
                (target
                    ? '；首次病程工作流目标：' + patientIdentityLabel(target)
                    : '') +
                (unlocked
                    ? '；已解锁：患者信息一致性校验已停用，请人工核对全部资料。'
                    : mismatch
                    ? '；当前页面与已锁定患者不一致，请确认后再提取。'
                    : '');
            patientBox.className =
                'first-status first-current-patient ' +
                (unlocked ? 'warn' : mismatch ? 'warn' : 'ok');
        }

        if (admissionBox) {
            if (!admissionCache) {
                admissionBox.textContent =
                    '尚未缓存当前目标患者入院记录。请先打开该患者“入院记录”预览页，再点击“提取并缓存当前入院记录”。';
                admissionBox.className =
                    'first-status first-admission-cache warn';
            } else {
                admissionBox.textContent =
                    '已缓存入院记录：' +
                    patientIdentityLabel(admissionCache.identity) +
                    '；正文' + String(admissionCache.text || '').length + '字符' +
                    (admissionCache.admissionTime
                        ? '；入院时间=' + admissionCache.admissionTime
                        : '') +
                    (admissionCache.recordTime
                        ? '；入院记录时间=' + admissionCache.recordTime
                        : '') +
                    '；提取时间=' + admissionCache.capturedAt;
                admissionBox.className =
                    'first-status first-admission-cache ok';

                if (
                    timeInput &&
                    !String(timeInput.value || '').trim() &&
                    admissionCache.recordTime
                ) {
                    timeInput.value =
                        firstCourseDateTimeToInput(
                            admissionCache.recordTime
                        );
                }
            }
        }

        if (orderBox) {
            if (!orderCache) {
                orderBox.textContent =
                    (modal.querySelector('.first-use-orders') &&
                    modal.querySelector('.first-use-orders').checked
                        ? '已开启“读取该患者医嘱信息”，但尚未缓存当前目标患者医嘱。请进入“医嘱管理→医嘱查询”，再点击“提取并缓存当前页医嘱”。'
                        : '当前未启用医嘱读取；生成时不会向AI提供医嘱缓存。如需结合医嘱生成，请勾选“读取该患者医嘱信息”并进入医嘱查询页提取。');
                orderBox.className =
                    'first-status first-order-cache warn';
            } else {
                const recordCount = Array.isArray(orderCache.records)
                    ? orderCache.records.length
                    : 0;
                orderBox.textContent =
                    '已缓存医嘱：' +
                    patientIdentityLabel(orderCache.identity) +
                    '；' + Number(orderCache.orderCount || 0) + '条' +
                    '；来源=' + inpatientOrderCacheSourceLabel(orderCache) +
                    inpatientOrderCacheFilterSuffix(orderCache) +
                    (orderCache.hiddenCount
                        ? '（含绕过临床路径隐藏读取' + orderCache.hiddenCount + '条）'
                        : '') +
                    (recordCount
                        ? '；可按首次病程时点精确截断'
                        : '；当前为旧缓存，建议重新提取以启用时点精确截断') +
                    '；提取时间=' + String(orderCache.capturedAt || '');
                orderBox.className =
                    'first-status first-order-cache ' +
                    (recordCount ? 'ok' : 'warn');
            }
        }
    }

