    function dischargeStatusIdentity(modal) {
        return dischargeLoadTargetPatient() || extractCurrentPatientIdentity();
    }

    function updateDischargeRecordModalStatus(modal) {
        const currentBox = modal.querySelector('.discharge-current-patient');
        const progressBox = modal.querySelector('.discharge-progress-cache');
        const orderBox = modal.querySelector('.discharge-order-cache');
        const current = extractCurrentPatientIdentity();
        const target = dischargeLoadTargetPatient();
        const unlocked = patientAiLoadUnlocked(
            DISCHARGE_RECORD_PATIENT_UNLOCKED_STORAGE_KEY
        );
        const identity = target || current;
        const firstCourseOnly =
            modal.querySelector(
                '.discharge-first-course-only'
            );

        if (target) {
            currentBox.textContent =
                '出院记录工作流目标患者：' + patientIdentityLabel(target) +
                (current.name || current.inpatientNo
                    ? '；当前页面识别：' + patientIdentityLabel(current)
                    : '') +
                (unlocked
                    ? '；已解锁：患者信息一致性校验已停用，请人工核对全部资料。'
                    : '');
            currentBox.className =
                'discharge-status discharge-current-patient ' +
                (unlocked ? 'warn' : 'ok');
        } else if (current.name || current.inpatientNo) {
            currentBox.textContent =
                '当前页面患者：' + patientIdentityLabel(current) +
                '；尚未锁定出院记录工作流患者。';
            currentBox.className = 'discharge-status discharge-current-patient warn';
        } else {
            currentBox.textContent = '当前页面暂未可靠识别患者身份。';
            currentBox.className = 'discharge-status discharge-current-patient warn';
        }

        if (typeof modal._renderDischargeClinical === 'function') {
            modal._renderDischargeClinical(identity);
        }
        if (!identity || (!identity.name && !identity.inpatientNo)) {
            progressBox.textContent = '尚无法按患者查找病程记录缓存。';
            progressBox.className = 'discharge-status discharge-progress-cache warn';
            orderBox.textContent = '尚无法按患者查找医嘱缓存。';
            orderBox.className = 'discharge-status discharge-order-cache warn';
            return;
        }

        const progressCache = dischargeProgressCache(identity);
        if (progressCache) {
            progressBox.textContent =
                '已缓存病程记录：' + patientIdentityLabel(progressCache.identity) +
                '；正文' + String(progressCache.progressText || '').length + '字符' +
                '；识别病程' + Number(progressCache.recordCount || 0) + '篇' +
                (progressCache.latestDate ? '；最后病程日期=' + progressCache.latestDate : '') +
                '；提取时间=' + (progressCache.capturedAt || '') +
                (
                    firstCourseOnly &&
                    firstCourseOnly.checked
                        ? '；生成模式=仅首次病程（会再次截断缓存）'
                        : '；生成模式=完整病程基线'
                );
            progressBox.className = 'discharge-status discharge-progress-cache ok';
        } else {
            progressBox.textContent =
                '当前患者暂无病程记录缓存。请先进入该患者病程记录预览页并点击“提取并缓存当前页病程记录”。';
            progressBox.className = 'discharge-status discharge-progress-cache warn';
        }

        const orderCache = dischargeOrderCache(identity);
        if (orderCache) {
            orderBox.textContent =
                '已缓存医嘱：' + patientIdentityLabel(orderCache.identity) +
                '；共' + Number(orderCache.orderCount || 0) + '条' +
                '；来源=' + inpatientOrderCacheSourceLabel(orderCache) +
                inpatientOrderCacheFilterSuffix(orderCache) +
                (orderCache.hiddenCount
                    ? '；其中' + orderCache.hiddenCount + '条虽被临床路径隐藏仍已纳入'
                    : '') +
                '；提取时间=' + (orderCache.capturedAt || '');
            orderBox.className = 'discharge-status discharge-order-cache ok';
        } else {
            const useOrders = modal.querySelector('.discharge-use-orders');
            orderBox.textContent =
                (useOrders && useOrders.checked)
                    ? '已开启“读取该患者医嘱信息”，但当前患者暂无医嘱缓存。请先进入医嘱管理→医嘱查询并点击“提取并缓存当前页医嘱”。'
                    : '当前未启用医嘱读取；生成时不会向AI提供医嘱缓存。如需结合医嘱生成，请勾选“读取该患者医嘱信息”并进入医嘱查询页提取。';
            orderBox.className = 'discharge-status discharge-order-cache warn';
        }
    }

    function closeDischargeRecordModal() {
        const modal = document.getElementById(DISCHARGE_RECORD_MODAL_ID);
        if (modal) modal.classList.remove('show');
    }

    function bindDischargeClinicalSections(modal) {
        const vitalRaw = modal.querySelector('.discharge-vital-raw');
        const vitalResult = modal.querySelector('.discharge-vital-result');
        const vitalStatus = modal.querySelector('.discharge-vital-status');
        const vitalPrompt = modal.querySelector('.discharge-vital-prompt-value');
        const solidify = modal.querySelector('.discharge-vital-solidify');
        const lisRaw = modal.querySelector('.discharge-lis-raw');
        const lisResult = modal.querySelector('.discharge-lis-result');
        const lisStatus = modal.querySelector('.discharge-lis-status');
        const extendedBox = modal.querySelector('.discharge-section .inpatient-lis-call-extended');
        const mergeBox = modal.querySelector('.discharge-section .inpatient-lis-merge-summary-title');
        vitalPrompt.value = loadProgressVitalSignsPrompt();
        solidify.checked = loadProgressVitalSignsSolidified();
        const options = inpatientLoadExtendedLisOptions();
        extendedBox.checked = options.callExtendedLis;
        mergeBox.checked = options.mergeSummaryTitle;
        mergeBox.disabled = !options.callExtendedLis;
        if (!options.callExtendedLis) mergeBox.parentElement.style.opacity = '.52';
        extendedBox.addEventListener('change', function () {
            inpatientSaveExtendedLisOptions(extendedBox.checked, mergeBox.checked);
        });
        mergeBox.addEventListener('change', function () {
            inpatientSaveExtendedLisOptions(extendedBox.checked, mergeBox.checked);
        });
        solidify.addEventListener('change', function () {
            saveProgressVitalSignsSolidified(solidify.checked);
        });
        function status(box, message, ok) {
            box.textContent = message;
            box.className = box === vitalStatus
                ? 'discharge-status discharge-vital-status ' + (ok ? 'ok' : 'warn')
                : 'discharge-status discharge-lis-status ' + (ok ? 'ok' : 'warn');
        }
        function identity() {return dischargeClinicalIdentity();}
        function stillCurrent(old) {
            const now = identity();
            if (!progressLisPacsPacsAdmissionMatches(
                now.inpatientNo, old.inpatientNo)) {
                throw new Error('读取期间已切换患者，本次结果未写入缓存');
            }
        }
        function stamp() {return new Date().toLocaleString();}
        function vitalCache(id) {
            return dischargeClinicalCache(DISCHARGE_RECORD_VITAL_SIGNS_CACHE_STORAGE_KEY,id);
        }
        function lisCache(id) {
            return dischargeClinicalCache(DISCHARGE_RECORD_LIS_PACS_CACHE_STORAGE_KEY,id);
        }
        function saveVital(entry) {
            return dischargeSaveClinicalCache(DISCHARGE_RECORD_VITAL_SIGNS_CACHE_STORAGE_KEY,entry);
        }
        function saveLis(entry) {
            return dischargeSaveClinicalCache(DISCHARGE_RECORD_LIS_PACS_CACHE_STORAGE_KEY,entry);
        }
        modal._renderDischargeClinical = function (id) {
            const vital = vitalCache(id), lis = lisCache(id);
            vitalRaw.value = vital ? String(vital.rawText || '') : '';
            vitalResult.value = vital ? String(vital.translatedText || '') : '';
            lisRaw.value = lis ? String(lis.rawText || '') : '';
            lisResult.value = lis ? String(lis.resultText || '') : '';
            status(vitalStatus, vital
                ? '当前患者三测单：' + (vital.rowCount || 0) + '条；范围' +
                  (vital.queryStart || '?') + '至' + (vital.queryEnd || '?') +
                  (vital.translatedText ? '；结果已保存' : '；请预处理/AI转义')
                : '当前患者暂无三测单缓存。', !!vital);
            status(lisStatus, lis
                ? '当前患者LIS' + Number(lis.lisReportCount || 0) + '份' +
                  (lis.extendedReportCount ? '；扩展LIS' + lis.extendedReportCount + '份' : '') +
                  '；金域申请' + progressLisPacsKingMedCachedCountLabel(lis) +
                  '；PACS申请' + Number(lis.pacsOrderCount || 0) +
                  '条/实际报告' + Number(lis.pacsReportCount || 0) +
                  '份；范围' + (lis.queryStart || '?') + '至' + (lis.queryEnd || '?') +
                  (lis.warnings && lis.warnings.length ? '；接口提示：' + lis.warnings.join('；') : '') +
                  (lis.resultText ? '；结果已保存' : '；请预处理')
                : '当前患者暂无LIS/PACS缓存。', !!lis);
        };
        function render(id) {modal._renderDischargeClinical(id || identity());}
        async function copy(box, label) {
            const copied = await copyProgressText(box.value);
            showStatus(label + (copied ? '结果已复制。' : '复制失败，请手工选择复制。'),
                copied ? 'success' : 'error');
        }
        modal.querySelector('.discharge-vital-copy').addEventListener('click',
            function () {copy(vitalResult,'三测单');});
        modal.querySelector('.discharge-lis-copy').addEventListener('click',
            function () {copy(lisResult,'LIS/PACS');});
        modal.querySelector('.discharge-vital-reset-prompt').addEventListener('click',function () {
            if (!window.confirm('确定恢复默认三测单TPRBP转义提示词吗？')) return;
            vitalPrompt.value = DEFAULT_PROGRESS_VITAL_SIGNS_PROMPT;
            document.querySelectorAll('.progress-vital-prompt, .discharge-vital-prompt-value')
                .forEach(function (box) {box.value = DEFAULT_PROGRESS_VITAL_SIGNS_PROMPT;});
            saveProgressVitalSignsPrompt(DEFAULT_PROGRESS_VITAL_SIGNS_PROMPT);
            showStatus('已恢复默认三测单TPRBP转义提示词。','success');
        });
        modal.querySelector('.discharge-vital-prompt').addEventListener('click',function () {
            openPatientAiManualEditor({title:'三测单AI转义提示词',value:vitalPrompt.value,
                saveLabel:'保存提示词',onSave:function (value) {
                    vitalPrompt.value = value;
                    saveProgressVitalSignsPrompt(value);
                }});
        });
        inpatientBindBaselineVisualButton(modal, '.discharge-vital-visual', function () {
            const id = identity();
            return {kind:'vital', value:vitalRaw.value, identity:id, cache:vitalCache(id)};
        });

        modal.querySelector('.discharge-vital-baseline').addEventListener('click',function () {
            try {
                const id = identity();
                openPatientAiManualEditor({baselineVisual:'vital', identity:id,
                    visualOptions:function () {return {cache:vitalCache(id)};},
                    title:'出院记录三测单原始基线',
                    hint:'目标：' + patientIdentityLabel(id) + '；修改原始数据后旧TPRBP结果清空。',
                    value:vitalRaw.value,saveLabel:'保存基线',
                    onSave:function (value) {
                        stillCurrent(id);
                        vitalRaw.value = value;
                        vitalRaw.dispatchEvent(new Event('change',{bubbles:true}));
                    }});
            } catch(error) {showStatus(error.message,'error');}
        });
        inpatientBindBaselineVisualButton(modal, '.discharge-lis-visual', function () {
            const id = identity(), cache = lisCache(id);
            return {kind:'lis', value:lisRaw.value, identity:id, cache:cache, extendedText:extendedBox.checked && cache ? cache.extendedText : ''};
        });

        modal.querySelector('.discharge-lis-baseline').addEventListener('click',function () {
            try {
                const id = identity();
                openPatientAiManualEditor({baselineVisual:'lis', identity:id,
                    visualOptions:function () {const cache = lisCache(id); return {cache:cache, extendedText:extendedBox.checked && cache ? cache.extendedText : ''};},
                    title:'出院记录LIS/PACS原始基线',
                    hint:'目标：' + patientIdentityLabel(id) + '；修改后旧结果和扩展LIS结果清空。',
                    value:lisRaw.value,saveLabel:'保存基线',
                    onSave:function (value) {
                        stillCurrent(id);
                        lisRaw.value = value;
                        lisRaw.dispatchEvent(new Event('change',{bubbles:true}));
                    }});
            } catch(error) {showStatus(error.message,'error');}
        });
        vitalRaw.addEventListener('change',function () {
            try {
                const id = identity();
                const raw = String(vitalRaw.value || '').trim();
                if (raw) {
                    const data = progressVitalSignsParseResponseText(raw);
                    progressVitalSignsValidatePatient(data,id);
                }
                saveVital(Object.assign({},vitalCache(id) || {},{
                    identity:id,rawText:raw,translatedText:'',processingMode:'',
                    manuallyEditedAt:stamp()}));
                vitalResult.value = '';
                render(id);
            } catch(error) {showStatus('三测单基线保存失败：' + error.message,'error');}
        });
        lisRaw.addEventListener('change',function () {
            try {
                const id = identity(), raw = String(lisRaw.value || '').trim();
                if (raw.length > PROGRESS_LIS_PACS_MAX_LIS_PACS_BASELINE_TEXT) {
                    throw new Error('原始JSON超过600000字符');
                }
                if (raw) {
                    const data = progressLisPacsLisPacsParseBaseline(raw);
                    if (data.patient && data.patient.inpatientNo &&
                        !progressLisPacsPacsAdmissionMatches(data.patient.inpatientNo,id.inpatientNo)) {
                        throw new Error('原始基线住院号与目标患者不一致');
                    }
                }
                saveLis(Object.assign({},lisCache(id) || {},{
                    identity:id,rawText:raw,extendedText:'',extendedReportCount:0,
                    resultText:'',processingMode:'',manuallyEditedAt:stamp()}));
                lisResult.value = '';
                render(id);
            } catch(error) {showStatus('LIS/PACS基线保存失败：' + error.message,'error');}
        });
        vitalResult.addEventListener('change',function () {
            try {
                const id = identity(), old = vitalCache(id) || {};
                const value = String(vitalResult.value || '').trim();
                if (value.length > 60000) throw new Error('结果超过60000字符');
                saveVital(Object.assign({},old,{identity:id,translatedText:value,
                    translatedEditedAt:stamp()}));
                render(id);
            } catch(error) {showStatus('三测单结果保存失败：' + error.message,'error');}
        });
        lisResult.addEventListener('change',function () {
            try {
                const id = identity(), old = lisCache(id) || {};
                const value = String(lisResult.value || '').trim();
                if (value.length > 60000) throw new Error('结果超过60000字符');
                saveLis(Object.assign({},old,{identity:id,resultText:value,
                    resultEditedAt:stamp()}));
                render(id);
            } catch(error) {showStatus('LIS/PACS结果保存失败：' + error.message,'error');}
        });
        modal.querySelector('.discharge-vital-clear').addEventListener('click',function () {
            try {
                const id = identity();
                dischargeClearClinicalCache(DISCHARGE_RECORD_VITAL_SIGNS_CACHE_STORAGE_KEY,id);
                render(id);
                showStatus('当前患者三测单缓存已清空。','success');
            } catch(error) {showStatus(error.message,'error');}
        });
        modal.querySelector('.discharge-lis-clear').addEventListener('click',function () {
            try {
                const id = identity();
                dischargeClearClinicalCache(DISCHARGE_RECORD_LIS_PACS_CACHE_STORAGE_KEY,id);
                render(id);
                showStatus('当前患者LIS/PACS缓存已清空。','success');
            } catch(error) {showStatus(error.message,'error');}
        });
        modal.querySelector('.discharge-vital-fetch').addEventListener('click',async function () {
            const button = this;
            try {
                const id = identity(), range = dischargeClinicalQueryRange(modal,id);
                if (!window.confirm('确认读取' + patientIdentityLabel(id) + '的三测单？\n' +
                    range.start + ' 至 ' + range.end + '；仅更新本机缓存。')) return;
                button.disabled = true;
                status(vitalStatus,'正在按住院号读取三测单……',false);
                const data = await progressVitalSignsRequestApi(id,range.start,range.end);
                progressVitalSignsValidatePatient(data,id);
                stillCurrent(id);
                const currentRange = dischargeClinicalQueryRange(modal,id);
                if (currentRange.start !== range.start || currentRange.end !== range.end) {
                    throw new Error('读取期间患者住院日期范围已变更，请重新读取');
                }
                const filtered = data.list.filter(function (row) {
                    const date = progressVitalSignsExtractDate(row &&
                        (row.rq || row.RQ || row.date || row.Date));
                    return date && date >= range.start && date <= range.end;
                });
                const omitted = data.list.length - filtered.length;
                const raw = JSON.stringify(Object.assign({},data,{list:filtered}),null,2);
                saveVital({identity:id,rawText:raw,translatedText:'',processingMode:'',
                    queryStart:range.start,queryEnd:range.end,
                    queryStartSource:range.source,queryEndSource:range.endSource,rowCount:filtered.length,
                    omittedOutsideRange:omitted,capturedAt:stamp()});
                render(id);
                showStatus('三测单读取完成：' + filtered.length + '条；范围外或日期缺失已排除' +
                    omitted + '条。请预处理或AI转义。','success');
            } catch(error) {status(vitalStatus,'三测单读取失败：' + error.message,false);
                showStatus(error.message,'error');}
            finally {button.disabled = false;}
        });
        modal.querySelector('.discharge-vital-preprocess').addEventListener('click',function () {
            try {
                const id = identity(), raw = String(vitalRaw.value || '').trim();
                const text = progressVitalSignsProgramPreprocess(raw);
                if (text.length > 60000) throw new Error('结果超过60000字符');
                saveVital(Object.assign({},vitalCache(id) || {},{
                    identity:id,rawText:raw,translatedText:text,
                    processingMode:'program-preprocess',translatedAt:stamp()}));
                render(id);
                showStatus('三测单TPRBP预处理完成；本次未调用AI。','success');
            } catch(error) {showStatus('三测单预处理失败：' + error.message,'error');}
        });
        modal.querySelector('.discharge-vital-ai').addEventListener('click',async function () {
            const button = this;
            try {
                const id = identity(), raw = String(vitalRaw.value || '').trim();
                if (!raw) throw new Error('请先读取三测单原始基线');
                const prompt = String(vitalPrompt.value || DEFAULT_PROGRESS_VITAL_SIGNS_PROMPT);
                saveProgressVitalSignsPrompt(prompt);
                button.disabled = true;
                status(vitalStatus,'正在调用AI转义TPRBP……',false);
                const result = await requestProgressVitalSignsAI(raw,prompt,solidify.checked);
                stillCurrent(id);
                if (raw !== String(vitalRaw.value || '').trim() ||
                    !vitalCache(id) || String(vitalCache(id).rawText || '').trim() !== raw) {
                    throw new Error('AI转义期间三测单基线已改变，请重新转义');
                }
                if (result.length > 60000) throw new Error('结果超过60000字符');
                saveVital(Object.assign({},vitalCache(id) || {},{
                    identity:id,rawText:raw,translatedText:result,
                    processingMode:'ai',promptMode:solidify.checked ? 'solidified' : 'flexible',
                    translatedAt:stamp()}));
                render(id);
                showStatus('三测单AI转义完成，结果已保存。','success');
            } catch(error) {status(vitalStatus,'三测单AI转义失败：' + error.message,false);
                showStatus(error.message,'error');}
            finally {button.disabled = false;}
        });
        const abort = modal.querySelector('.discharge-lis-abort');
        abort.addEventListener('click',function () {
            modal._lisPacsAbortRequested = true;
            status(lisStatus,'正在中止LIS/PACS读取……',false);
        });
        modal.querySelector('.discharge-lis-fetch').addEventListener('click',async function () {
            const button = this;
            try {
                const id = identity();
                let startInfo = null;
                try { startInfo = dischargeClinicalStartDate(id); } catch (error) {}
                modal._lisPacsAbortRequested = false;
                button.disabled = true;
                abort.disabled = false;
                const interfaceRecord = await progressLisPacsResolveInterfacePatient({
                    admissionNo:id.inpatientNo,name:id.name,
                    admissionDate:startInfo && startInfo.date || '',
                    admissionDateSource:startInfo && startInfo.source || '',
                    queryEnd:dischargeClinicalEndDate(id).date},modal);
                stillCurrent(id);
                const range = dischargeLisPacsQueryRange(modal,id,interfaceRecord);
                interfaceRecord.admissionDate = range.start;
                interfaceRecord.queryEnd = range.end;
                if (!window.confirm('确认读取' + patientIdentityLabel(
                    Object.assign({},id,{name:interfaceRecord.name})) + '的LIS/PACS？\n' +
                    range.start + ' 至 ' + range.end +
                    (extendedBox.checked ? '；同时调用扩展LIS。' : '。') +
                    '\n仅更新本机缓存。')) return;
                progressLisPacsThrowIfAborted(modal);
                status(lisStatus,'正在读取LIS/PACS申请及实际报告、金域申请目录……',false);
                const core = await progressLisPacsReadLisPacsInterfaceBaseline(interfaceRecord,modal);
                progressLisPacsThrowIfAborted(modal);
                stillCurrent(id);
                let ext = null, extWarning = '';
                if (extendedBox.checked) {
                    try {
                        status(lisStatus,'院内LIS/PACS已读取，正在调用扩展LIS……',false);
                        ext = await inpatientReadExtendedLisFromExternalInterface(interfaceRecord,modal);
                        progressLisPacsThrowIfAborted(modal);
                    } catch(error) {
                        if (progressLisPacsAbortRequested(modal)) throw error;
                        extWarning = '扩展LIS接口：' + error.message;
                    }
                }
                stillCurrent(id);
                const currentRange = dischargeLisPacsQueryRange(modal,id,interfaceRecord);
                if (currentRange.start !== range.start || currentRange.end !== range.end ||
                    core.data.range.endDate !== range.end) {
                    throw new Error('读取期间患者住院日期范围已变更，请重新读取');
                }
                saveLis({identity:id,rawText:core.text,resultText:'',
                    extendedText:ext ? ext.text : '',
                    extendedReportCount:ext ? ext.reportCount : 0,
                    queryStart:range.start,queryEnd:range.end,
                    queryStartSource:range.source,queryEndSource:range.endSource,
                    lisOrderCount:core.lisOrderCount,lisReportCount:core.lisReportCount,
                    pacsOrderCount:core.pacsCount,pacsReportCount:core.pacsReportCount,
                    warnings:(core.warnings || []).concat(ext ? ext.warnings || [] :
                        extWarning ? [extWarning] : []),capturedAt:stamp()});
                render(id);
                showStatus('LIS/PACS基线已保存，请预处理；' +
                    (extWarning || '报告和申请请分别核对。'),'success');
            } catch(error) {status(lisStatus,'LIS/PACS读取失败：' + error.message,false);
                showStatus(error.message,'error');}
            finally {button.disabled = false;abort.disabled = true;
                modal._lisPacsAbortRequested = false;}
        });
        function processLis(full) {
            try {
                const id = identity(), raw = String(lisRaw.value || '').trim();
                const data = progressLisPacsLisPacsParseBaseline(raw);
                if (data.patient && data.patient.inpatientNo &&
                    !progressLisPacsPacsAdmissionMatches(data.patient.inpatientNo,id.inpatientNo)) {
                    throw new Error('基线住院号与目标患者不一致');
                }
                const old = lisCache(id) || {};
                const warnings = Array.isArray(old.warnings) ? old.warnings.filter(Boolean) : [];
                const output = (warnings.length
                    ? '【接口读取不完整】\n' + warnings.join('；') +
                      '\n缺失接口或报告不能视为阴性结果。\n' : '') +
                    inpatientLisPacsOutputWithExtended(data,old.extendedText,
                        full,extendedBox.checked,mergeBox.checked);
                if (output.length > 60000) throw new Error('结果超过60000字符');
                saveLis(Object.assign({},old,{identity:id,rawText:raw,
                    resultText:output,processingMode:full ? 'full' : 'program-preprocess',
                    processedAt:stamp()}));
                render(id);
                showStatus('LIS/PACS' + (full ? '完整基线' : '预处理') +
                    '已保存；本次未调用AI。','success');
            } catch(error) {showStatus('LIS/PACS预处理失败：' + error.message,'error');}
        }
        modal.querySelector('.discharge-lis-preprocess').addEventListener('click',
            function () {processLis(false);});
        modal.querySelector('.discharge-lis-full').addEventListener('click',
            function () {processLis(true);});
    }

