    function admissionRecordAiFindCache(storageKey, identity) {
        return dischargeFindPatientCache(storageKey, identity);
    }

    function admissionRecordAiSaveOrderCacheQuotaSafe(entry) {
        /*
         * 保留旧函数名以兼容既有调用点；实际持久化已经改为GM大容量存储。
         */
        const key = patientIdentityKey(entry && entry.identity);
        if (!key) throw new Error('无法生成患者身份缓存键');

        const store = dischargeLoadCacheStore(
            ADMISSION_RECORD_AI_ORDER_CACHE_STORAGE_KEY
        );

        store[key] = Object.assign({}, entry || {}, {
            savedAtMs: Date.now(),
            storageMode: 'tampermonkey-gm'
        });

        inpatientLargeCacheWriteStore(
            ADMISSION_RECORD_AI_ORDER_CACHE_STORAGE_KEY,
            store
        );

        return key;
    }

    function admissionRecordAiSaveCache(storageKey, entry) {
        if (
            storageKey ===
            ADMISSION_RECORD_AI_ORDER_CACHE_STORAGE_KEY
        ) {
            return admissionRecordAiSaveOrderCacheQuotaSafe(entry);
        }
        return dischargeSavePatientCache(storageKey, entry);
    }

    function admissionRecordAiClearCache(storageKey, identity) {
        return dischargeClearPatientCache(storageKey, identity);
    }

    function admissionRecordAiSameName(first, second) {
        const firstName = progressNormalize(
            progressCleanPatientName(first && first.name)
        );
        const secondName = progressNormalize(
            progressCleanPatientName(second && second.name)
        );
        return Boolean(
            firstName &&
            secondName &&
            firstName === secondName
        );
    }

    function admissionRecordAiSourceIdentityCompatible(
        target,
        sourceIdentity,
        allowHistoricalAdmission
    ) {
        const targetItem = target || {};
        const sourceItem = sourceIdentity || {};
        const targetName = progressNormalize(
            progressCleanPatientName(targetItem.name)
        );
        const sourceName = progressNormalize(
            progressCleanPatientName(sourceItem.name)
        );
        const targetNo = progressNormalize(targetItem.inpatientNo);
        const sourceNo = progressNormalize(sourceItem.inpatientNo);

        if (targetName && sourceName && targetName !== sourceName) {
            return false;
        }

        if (
            !allowHistoricalAdmission &&
            targetNo &&
            sourceNo &&
            targetNo !== sourceNo
        ) {
            return false;
        }

        if (targetName && sourceName) {
            return true;
        }

        if (targetNo && sourceNo) {
            return allowHistoricalAdmission || targetNo === sourceNo;
        }

        return true;
    }

    function admissionRecordAiLineEnd(text, index) {
        const lineEnd = String(text || '').indexOf('\n', index);
        return lineEnd >= 0 ? lineEnd : String(text || '').length;
    }

    function admissionRecordAiIsolateAdmissionText(textValue) {
        const source = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        if (!source) return '';

        const mainMarker = source.search(
            /(?:^|\n)\s*(?:主诉|现病史)\s*[：:]/
        );

        let startIndex = 0;

        if (mainMarker >= 0) {
            const lookBehindStart =
                Math.max(0, mainMarker - 1800);
            const lookBehind = source.slice(
                lookBehindStart,
                mainMarker
            );

            const titleMatches = Array.from(
                lookBehind.matchAll(/入\s*院\s*记\s*录|入院记录/g)
            );
            const titleMatch = titleMatches.length
                ? titleMatches[titleMatches.length - 1]
                : null;

            const nameMatches = Array.from(
                lookBehind.matchAll(/姓名\s*[：:]/g)
            );
            const nameMatch = nameMatches.length
                ? nameMatches[nameMatches.length - 1]
                : null;

            if (nameMatch) {
                startIndex =
                    lookBehindStart + nameMatch.index;
            } else if (titleMatch) {
                startIndex =
                    lookBehindStart + titleMatch.index;
            }
        }

        const signatureTail = source.slice(startIndex);
        const signatureMatch = signatureTail.match(
            /(?:^|\n)[^\n]*医师签名\s*[：:]/
        );
        const signatureIndex = signatureMatch
            ? startIndex + signatureMatch.index +
                (signatureMatch[0].startsWith('\n') ? 1 : 0)
            : -1;

        let endIndex = source.length;

        if (signatureIndex >= startIndex) {
            endIndex = admissionRecordAiLineEnd(
                source,
                signatureIndex
            );
        }

        return source.slice(startIndex, endIndex).trim();
    }

    function admissionRecordAiReadControlValue(control) {
        if (!control) return '';

        if (control.tagName === 'SELECT') {
            const option = control.options && control.selectedIndex >= 0
                ? control.options[control.selectedIndex]
                : null;
            const selectedText = progressPlain(
                option
                    ? option.textContent || option.value
                    : control.value
            );

            return /^(?:请选择|---请选择---|全部|===全部===)$/
                .test(selectedText)
                    ? ''
                    : selectedText;
        }

        if (control.isContentEditable) {
            return progressPlain(
                control.innerText || control.textContent || ''
            );
        }

        return progressPlain(control.value || '');
    }

    function admissionRecordAiCollectOutpatientStructuredText(doc) {
        if (!doc || !doc.body) return '';

        let controls = [];

        try {
            controls = Array.from(doc.querySelectorAll([
                'input:not([type="hidden"]):not([type="button"]):not([type="submit"]):not([type="reset"]):not([type="radio"]):not([type="checkbox"])',
                'textarea',
                'select',
                '[contenteditable="true"]',
                '[role="textbox"]'
            ].join(','))).filter(function (control) {
                return isVisible(control) &&
                    !control.closest('#' + PANEL_ID) &&
                    !control.closest('#' + MODAL_ID) &&
                    !control.closest('#' + SETTINGS_MODAL_ID) &&
                    !control.closest('#' + PROGRESS_MODAL_ID) &&
                    !control.closest('#medical-inpatient-first-course-ai-modal') &&
                    !control.closest('#medical-inpatient-discharge-record-ai-modal') &&
                    !control.closest('#medical-inpatient-condition-disclosure-ai-modal') &&
                    !control.closest('#medical-inpatient-admission-record-ai-modal');
            });
        } catch (error) {
            controls = [];
        }

        if (!controls.length) return '';

        const definitions = [
            { label: '患者姓名', aliases: ['患者姓名', '姓名'] },
            { label: '门诊号', aliases: ['门诊号'] },
            { label: '就诊科室', aliases: ['就诊科室', '科室'] },
            { label: '就诊医生', aliases: ['就诊医生', '接诊医生'] },
            { label: '就诊日期', aliases: ['就诊日期', '就诊时间'] },
            { label: '发病日期', aliases: ['发病日期'] },
            { label: '身高', aliases: ['身高'] },
            { label: '体重', aliases: ['体重'] },
            { label: '体温', aliases: ['体温'] },
            { label: '脉搏', aliases: ['脉搏'] },
            { label: '呼吸', aliases: ['呼吸'] },
            { label: '血糖', aliases: ['血糖'] },
            { label: '收缩压', aliases: ['收缩压'] },
            { label: '舒张压', aliases: ['舒张压'] },
            { label: '婚姻', aliases: ['婚姻'] },
            { label: '主诉', aliases: ['主诉'] },
            {
                label: '现病史',
                aliases: ['现病史', '简要病史', '病史摘要']
            },
            { label: '既往史', aliases: ['既往史', '既往病史'] },
            { label: '月经史', aliases: ['月经史'] },
            { label: '过敏史', aliases: ['过敏史'] },
            {
                label: '查体',
                aliases: ['查体', '体格检查', '专科检查']
            },
            { label: '辅助检查', aliases: ['辅助检查'] },
            {
                label: '诊断',
                aliases: ['诊断', '门诊诊断', '中医诊断', '西医诊断']
            },
            {
                label: '处理',
                aliases: ['处理', '处置', '治疗意见', '诊疗意见']
            },
            { label: '病历内容', aliases: ['病历内容'] }
        ];

        const usedControls = new Set();
        const lines = [];

        function isUsableControl(control) {
            return Boolean(
                control &&
                controls.includes(control) &&
                !usedControls.has(control) &&
                admissionRecordAiReadControlValue(control)
            );
        }

        /*
         * 先沿标签所在的表单容器、相邻单元格和label[for]寻找控件。
         * 该HIS的“开立处方—病历”页大量使用宽textarea；只按中心点
         * 计算距离时，textarea中心会落到下一行，从而被误判为无对应字段。
         */
        function collectSemanticCandidates(label, definition) {
            const candidates = [];
            const seen = new Set();

            function add(control, priority) {
                if (!isUsableControl(control) || seen.has(control)) {
                    return;
                }

                seen.add(control);

                const labelRect = label.getBoundingClientRect();
                const controlRect = control.getBoundingClientRect();
                const sameRowDistance = Math.abs(
                    controlRect.top - labelRect.top
                );
                const horizontalPenalty = controlRect.right < labelRect.left
                    ? 1200 + Math.abs(controlRect.left - labelRect.left)
                    : Math.max(0, controlRect.left - labelRect.right);

                if (
                    priority > 0 &&
                    (
                        sameRowDistance > 110 ||
                        controlRect.right < labelRect.left - 30 ||
                        horizontalPenalty > 1100
                    )
                ) {
                    return;
                }

                candidates.push({
                    control: control,
                    score:
                        priority * 100000 +
                        sameRowDistance * 80 +
                        horizontalPenalty
                });
            }

            function addScope(scope, priority) {
                if (!scope || !scope.querySelectorAll) return;

                controls.forEach(function (control) {
                    if (scope === control || scope.contains(control)) {
                        add(control, priority);
                    }
                });
            }

            const labelFor = label.getAttribute &&
                label.getAttribute('for');

            if (labelFor) {
                add(doc.getElementById(labelFor), 0);
            }

            addScope(label, 0);
            addScope(label.nextElementSibling, 1);

            let cell = label.closest && label.closest('td,th');

            if (cell) {
                addScope(cell, 1);

                let sibling = cell.nextElementSibling;

                for (let index = 0;
                    sibling && index < 3;
                    index += 1) {
                    addScope(sibling, 1 + index);
                    sibling = sibling.nextElementSibling;
                }

                addScope(cell.closest('tr'), 5);
            }

            let parent = label.parentElement;

            for (let level = 0;
                parent && level < 5;
                level += 1) {
                addScope(parent, 2 + level);
                addScope(parent.nextElementSibling, 3 + level);
                parent = parent.parentElement;
            }

            const normalizedAliases = definition.aliases
                .map(normalize)
                .filter(Boolean);

            controls.forEach(function (control) {
                if (!isUsableControl(control)) return;

                const attributeText = normalize([
                    control.getAttribute('aria-label'),
                    control.getAttribute('placeholder'),
                    control.getAttribute('title'),
                    control.getAttribute('name'),
                    control.id
                ].filter(Boolean).join(' '));

                if (normalizedAliases.some(function (alias) {
                    return attributeText.includes(alias);
                })) {
                    add(control, 1);
                }
            });

            candidates.sort(function (first, second) {
                return first.score - second.score;
            });

            return candidates.map(function (item) {
                return item.control;
            });
        }

        definitions.forEach(function (definition) {
            const labels = findTextElements(doc, definition.aliases);
            let selected = null;
            let selectedValue = '';

            for (const label of labels) {
                const semanticCandidates =
                    collectSemanticCandidates(label, definition);

                for (const control of semanticCandidates) {
                    const value =
                        admissionRecordAiReadControlValue(control);

                    if (!value || value === definition.label) {
                        continue;
                    }

                    selected = control;
                    selectedValue = value;
                    break;
                }

                if (selected) break;
            }

            /*
             * 个别组件不渲染独立标签节点，只把字段名放在
             * aria-label/placeholder/name中；作为最后一层兼容读取。
             */
            if (!selected) {
                const normalizedAliases = definition.aliases
                    .map(normalize)
                    .filter(Boolean);

                for (const control of controls) {
                    if (!isUsableControl(control)) continue;

                    const attributeText = normalize([
                        control.getAttribute('aria-label'),
                        control.getAttribute('placeholder'),
                        control.getAttribute('title'),
                        control.getAttribute('name'),
                        control.id
                    ].filter(Boolean).join(' '));

                    if (!normalizedAliases.some(function (alias) {
                        return attributeText.includes(alias);
                    })) {
                        continue;
                    }

                    selected = control;
                    selectedValue =
                        admissionRecordAiReadControlValue(control);
                    break;
                }
            }

            if (!selected || !selectedValue) return;

            usedControls.add(selected);
            lines.push(
                definition.label + '：' + selectedValue
            );
        });

        return lines.join('\n');
    }

    function admissionRecordAiCollectOutpatientViewerText(doc) {
        /* v2.41.1：停用PDF/文本层门诊读取，只保留开立处方病历页DOM读取。 */
        return '';
    }

    function admissionRecordAiCountStructuredClinicalFields(textValue) {
        return [
            /^主诉：.+$/m,
            /^现病史：.+$/m,
            /^既往史：.+$/m,
            /^过敏史：.+$/m,
            /^查体：.+$/m,
            /^辅助检查：.+$/m,
            /^诊断：.+$/m,
            /^处理：.+$/m,
            /^病历内容：.+$/m
        ].filter(function (pattern) {
            return pattern.test(String(textValue || ''));
        }).length;
    }

    function admissionRecordAiDetectOutpatientPageType(
        textValue,
        structuredText
    ) {
        const text = String(textValue || '');
        const structured = String(structuredText || '');
        const structuredClinicalHits =
            admissionRecordAiCountStructuredClinicalFields(structured);
        const structuredHasCoreHistory =
            /^(?:主诉|现病史|病历内容)：.+$/m.test(structured);

        /*
         * 页面实际表单字段及其值比全局导航菜单更可靠。只要已经从
         * 当前可见文档读取到主诉/现病史等核心字段和至少两个临床字段，
         * 即确认是“开立处方—病历”，不再要求固定菜单项全部出现。
         */
        const strongMedicalRecordForm =
            structuredHasCoreHistory &&
            structuredClinicalHits >= 2;

        /*
         * 左侧导航会在所有门诊页面同时出现“开立处方”等菜单文字，
         * 不能仅凭菜单命中判断当前页。先排除另外两类页面独有的主体标记。
         */
        const visitQueryHits = [
            /就诊类型/,
            /结算状态/,
            /就诊医生/,
            /医保卡/
        ].filter(function (pattern) {
            return pattern.test(text);
        }).length;

        if (
            (/门诊病历列表/.test(text) && /历史病历记录/.test(text)) ||
            (visitQueryHits >= 3 && !strongMedicalRecordForm)
        ) {
            return '';
        }

        const prescriptionPageHits = [
            /患者列表/,
            /西药处方/,
            /常规项目/,
            /发病日期/,
            /病历详情/
        ].filter(function (pattern) {
            return pattern.test(text);
        }).length;

        const visibleClinicalHits = [
            /主诉\s*[：:]?/,
            /现病史\s*[：:]?/,
            /既往史\s*[：:]?/,
            /过敏史\s*[：:]?/,
            /查体\s*[：:]?/,
            /辅助检查\s*[：:]?/
        ].filter(function (pattern) {
            return pattern.test(text);
        }).length;

        if (
            strongMedicalRecordForm ||
            (
                /发病日期/.test(text) &&
                visibleClinicalHits >= 3 &&
                (
                    /开立处方|病历详情/.test(text) ||
                    prescriptionPageHits >= 2
                )
            )
        ) {
            return '开立处方—病历';
        }

        return '';
    }

    function admissionRecordAiIsolateOutpatientText(textValue) {
        const source = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        if (!source) return '';

        const clinicalMatch = source.match(
            /(?:主诉|现病史|简要病史|病史摘要|病历内容)\s*[：:]?/
        );
        const anchorIndex = clinicalMatch
            ? clinicalMatch.index
            : source.length;
        const lookBehindStart = Math.max(0, anchorIndex - 1800);
        const lookBehind = source.slice(lookBehindStart, anchorIndex);
        const markerMatches = Array.from(
            lookBehind.matchAll(
                /开立处方|病历详情/g
            )
        );
        const nameMatches = Array.from(
            lookBehind.matchAll(/(?:患者姓名|姓名)\s*[：:]/g)
        );

        let startIndex = clinicalMatch ? clinicalMatch.index : 0;

        if (nameMatches.length) {
            startIndex =
                lookBehindStart +
                nameMatches[nameMatches.length - 1].index;
        } else if (markerMatches.length) {
            /*
             * 左侧导航栏也包含多个门诊入口，因此取临床正文之前最近的
             * 页面标题，而不是整页出现的第一个菜单文字。
             */
            startIndex =
                lookBehindStart +
                markerMatches[markerMatches.length - 1].index;
        }

        const tail = source.slice(startIndex);
        const signatureMatch = tail.match(
            /(?:^|\n)[^\n]*(?:医师签名|医生签名|接诊医师)\s*[：:]/
        );

        let endIndex = source.length;

        if (signatureMatch) {
            const signatureIndex =
                startIndex + signatureMatch.index +
                (signatureMatch[0].startsWith('\n') ? 1 : 0);
            endIndex =
                admissionRecordAiLineEnd(
                    source,
                    signatureIndex
                );
        }

        return source.slice(startIndex, endIndex).trim();
    }

    function admissionRecordAiLooksLikeAdmissionText(textValue) {
        const text = String(textValue || '');

        if (text.length < 420) return false;

        const sectionHits = [
            /主诉\s*[：:]/,
            /现病史\s*[：:]/,
            /既往史\s*[：:]/,
            /个人史\s*[：:]/,
            /体\s*格\s*检\s*查|专科查体\s*[：:]/,
            /初步诊断\s*[：:]/
        ].filter(function (pattern) {
            return pattern.test(text);
        }).length;

        return sectionHits >= 4 &&
            /入院日期|入院时间|入\s*院\s*记\s*录|住院病历附页/.test(text);
    }

    function admissionRecordAiCollectCurrentSource(
        kind,
        target,
        skipIdentityValidation
    ) {
        const candidates = [];
        const activePageIdentity = kind === 'outpatient'
            ? extractCurrentPatientIdentity()
            : null;

        const targetNumber = progressNormalize(
            target && target.inpatientNo
        );
        const activeNumber = progressNormalize(
            activePageIdentity && activePageIdentity.inpatientNo
        );
        const activePageMatchesTarget = Boolean(
            skipIdentityValidation ||
            admissionRecordAiSameName(target, activePageIdentity) ||
            (
                targetNumber &&
                activeNumber &&
                targetNumber === activeNumber
            )
        );

        getVisibleDocuments().forEach(function (doc, docIndex) {
            const standardVisibleText =
                collectVisiblePageText(doc, 150000);
            const viewerText = '';
            const viewerProbe =
                progressNormalize(viewerText).slice(0, 160);
            const visiblePageText = [
                standardVisibleText,
                viewerText &&
                viewerProbe &&
                !progressNormalize(standardVisibleText)
                    .includes(viewerProbe)
                    ? viewerText
                    : ''
            ].filter(Boolean).join('\n');
            const structuredOutpatientText =
                kind === 'outpatient'
                    ? admissionRecordAiCollectOutpatientStructuredText(doc)
                    : '';
            const pageText = [
                structuredOutpatientText,
                visiblePageText
            ].filter(Boolean).join('\n');

            if (
                !pageText ||
                pageText.length < (kind === 'outpatient' ? 40 : 120)
            ) {
                return;
            }

            let sourceIdentity =
                extractPatientIdentityFromText(pageText);

            /*
             * 病历字段有时位于内层iframe，而患者蓝色标题位于其父页面。
             * 子iframe正文没有姓名时，只在活动页身份已经与锁定患者一致
             * 的前提下合并父页身份，既能读取又不会跨患者串用资料。
             */
            if (
                kind === 'outpatient' &&
                activePageMatchesTarget &&
                activePageIdentity &&
                (activePageIdentity.name || activePageIdentity.inpatientNo)
            ) {
                sourceIdentity = mergePatientIdentity(
                    sourceIdentity,
                    activePageIdentity
                );
            }

            const allowHistorical =
                kind === 'priorAdmission' ||
                kind === 'priorDischarge' ||
                kind === 'outpatient';

            if (
                !skipIdentityValidation &&
                !admissionRecordAiSourceIdentityCompatible(
                    target,
                    sourceIdentity,
                    allowHistorical
                )
            ) {
                return;
            }

            let score = 0;
            let isolatedText = '';
            let sourcePageType = '';

            if (kind === 'outpatient') {
                const hasOutpatientMarker =
                    /开立处方|病历详情|发病日期/.test(
                        pageText
                    );

                const structuredDetailHits =
                    admissionRecordAiCountStructuredClinicalFields(
                        structuredOutpatientText
                    );

                const hasCoreHistory =
                    /主诉\s*[：:]?|现病史\s*[：:]?|简要病史\s*[：:]?|病史摘要\s*[：:]?|病历内容\s*[：:]?/.test(
                        pageText
                    );

                const detailHits = [
                    /主诉\s*[：:]?/,
                    /现病史\s*[：:]?|简要病史\s*[：:]?|病史摘要\s*[：:]?|病历内容\s*[：:]?/,
                    /既往史\s*[：:]?|既往病史\s*[：:]?/,
                    /查体\s*[：:]?|体格检查\s*[：:]?|专科检查\s*[：:]?/,
                    /诊断\s*[：:]?|中医诊断\s*[：:]?|西医诊断\s*[：:]?/,
                    /处理意见|处置|治疗意见|诊疗意见|诊疗计划/
                ].filter(function (pattern) {
                    return pattern.test(pageText);
                }).length;

                if (
                    !hasCoreHistory ||
                    (
                        structuredDetailHits < 2 &&
                        detailHits < 3
                    ) ||
                    (
                        !hasOutpatientMarker &&
                        structuredDetailHits < 2 &&
                        detailHits < 4
                    )
                ) {
                    return;
                }

                sourcePageType =
                    admissionRecordAiDetectOutpatientPageType(
                        pageText,
                        structuredOutpatientText
                    );

                if (sourcePageType !== '开立处方—病历') {
                    return;
                }

                score = 240 +
                    detailHits * 35 +
                    structuredDetailHits * 55;

                if (sourcePageType === '开立处方—病历') {
                    score += 140;
                }

                const isolatedVisibleText =
                    admissionRecordAiIsolateOutpatientText(
                        visiblePageText
                    );

                const structuredIsReliable =
                    structuredDetailHits >= 2;

                isolatedText = [
                    '来源页面：' + sourcePageType,
                    structuredOutpatientText
                        ? '【页面结构化字段】\n' +
                            structuredOutpatientText
                        : '',
                    !structuredIsReliable && isolatedVisibleText
                        ? '【页面可见原文】\n' +
                            isolatedVisibleText
                        : ''
                ].filter(Boolean).join('\n');
            } else if (
                kind === 'priorAdmission' ||
                kind === 'draft'
            ) {
                if (!admissionRecordAiLooksLikeAdmissionText(pageText)) {
                    return;
                }

                score = 280;
                if (/入\s*院\s*记\s*录|入院记录/.test(pageText)) {
                    score += 130;
                }
                if (/姓名\s*[：:]/.test(pageText)) score += 40;
                if (/医师签名\s*[：:]/.test(pageText)) score += 40;

                isolatedText =
                    admissionRecordAiIsolateAdmissionText(pageText);
            } else if (kind === 'priorDischarge') {
                if (
                    !looksLikeProgressReferenceDischargeRecord(
                        pageText,
                        null
                    )
                ) {
                    return;
                }

                score = 360;
                isolatedText =
                    isolateProgressReferenceDischargeRecordText(
                        pageText
                    );
            } else {
                return;
            }

            if (!isolatedText) return;

            const normalizedPage =
                progressNormalize(pageText);

            const targetName =
                progressNormalize(target && target.name);
            const sourceName =
                progressNormalize(sourceIdentity.name);
            const targetNo =
                progressNormalize(target && target.inpatientNo);
            const sourceNo =
                progressNormalize(sourceIdentity.inpatientNo);

            if (
                !skipIdentityValidation &&
                targetName &&
                !sourceName &&
                !normalizedPage.includes(targetName) &&
                !(targetNo && sourceNo && targetNo === sourceNo)
            ) {
                return;
            }

            if (
                target &&
                target.name &&
                normalizedPage.includes(
                    progressNormalize(target.name)
                )
            ) {
                score += 120;
            }

            if (
                target &&
                target.inpatientNo &&
                normalizedPage.includes(
                    progressNormalize(target.inpatientNo)
                )
            ) {
                score += kind === 'draft' ? 170 : 35;
            }

            if (
                !skipIdentityValidation &&
                kind === 'draft' &&
                target &&
                target.inpatientNo &&
                sourceIdentity.inpatientNo &&
                progressNormalize(target.inpatientNo) !==
                    progressNormalize(sourceIdentity.inpatientNo)
            ) {
                return;
            }

            score -= docIndex * 3;

            candidates.push({
                text: isolatedText.slice(0, 100000),
                fullTextLength: pageText.length,
                identity: sourceIdentity,
                score: score,
                admissionTime:
                    firstCourseExtractLabelDateTime(
                        pageText,
                        '入院日期'
                    ) ||
                    firstCourseExtractLabelDateTime(
                        pageText,
                        '入院时间'
                    ),
                recordTime:
                    firstCourseExtractLabelDateTime(
                        pageText,
                        '记录日期'
                    ) ||
                    firstCourseExtractLabelDateTime(
                        pageText,
                        '记录时间'
                    ),
                dischargeDate:
                    kind === 'priorDischarge'
                        ? extractProgressReferenceDischargeDate(pageText)
                        : '',
                sourcePageType: sourcePageType
            });
        });

        candidates.sort(function (first, second) {
            if (first.score !== second.score) {
                return second.score - first.score;
            }
            return second.text.length - first.text.length;
        });

        return candidates[0] || {
            text: '',
            fullTextLength: 0,
            identity: {},
            score: 0,
            admissionTime: '',
            recordTime: '',
            dischargeDate: '',
            sourcePageType: ''
        };
    }

    async function admissionRecordAiCaptureSource(
        kind,
        target,
        skipIdentityValidation
    ) {
        const storageMap = {
            outpatient:
                ADMISSION_RECORD_AI_OUTPATIENT_CACHE_STORAGE_KEY,
            priorAdmission:
                ADMISSION_RECORD_AI_PRIOR_ADMISSION_CACHE_STORAGE_KEY,
            priorDischarge:
                ADMISSION_RECORD_AI_PRIOR_DISCHARGE_CACHE_STORAGE_KEY,
            draft:
                ADMISSION_RECORD_AI_DRAFT_CACHE_STORAGE_KEY
        };

        const storageKey = storageMap[kind];

        if (!storageKey) {
            throw new Error('未知资料类型');
        }

        const source =
            admissionRecordAiCollectCurrentSource(
                kind,
                target,
                skipIdentityValidation
            );

        if (!source.text) {
            const messages = {
                outpatient:
                    '当前页面未识别到可靠的门诊信息。请在“开立处方—病历”页面读取，或使用“手动录入/修改门诊信息”。',
                priorAdmission:
                    '未识别到可靠的既往入院记录。请打开该患者既往住院的“入院记录”预览页。',
                priorDischarge:
                    '未识别到可靠的既往出院记录。请打开该患者既往住院的“出院记录”预览页。',
                draft:
                    '未识别到可靠的当前入院记录初稿。请打开当前患者“入院记录”预览页，不要停留在画布式编辑器。'
            };
            throw new Error(messages[kind] || '未识别到资料正文');
        }

        const sourceLabelMap = {
            outpatient: '入院记录AI－门诊信息',
            priorAdmission: '入院记录AI－既往入院记录',
            priorDischarge: '入院记录AI－既往出院记录',
            draft: '入院记录AI－当前入院记录初稿'
        };

        const preprocessResult =
            await inpatientApplyGlobalMedicalRecordPreprocess(
                source.text,
                sourceLabelMap[kind] ||
                    '入院记录AI－病历正文'
            );

        source.text =
            preprocessResult.text;

        const entry = {
            schemaVersion: 1,
            identity: target,
            sourceIdentity: source.identity,
            text: source.text,
            admissionTime: source.admissionTime || '',
            recordTime: source.recordTime || '',
            dischargeDate: source.dischargeDate || '',
            capturedAt: new Date().toLocaleString(),
            pageUrl: location.href,
            captureMode: 'page',
            sourcePageType: source.sourcePageType || ''
        };

        inpatientAttachMedicalRecordPreprocessMeta(
            entry,
            preprocessResult
        );

        admissionRecordAiSaveCache(storageKey, entry);
        return entry;
    }

    function admissionRecordAiCacheSummary(entry, label) {
        if (!entry || !entry.text) {
            return '尚未读取' + label + '。';
        }

        const sourceIdentity =
            entry.sourceIdentity &&
            (entry.sourceIdentity.name ||
             entry.sourceIdentity.inpatientNo)
                ? patientIdentityLabel(entry.sourceIdentity)
                : '未单独识别来源患者号';

        return '已读取' + label + '：正文' +
            String(entry.text || '').length + '字符' +
            '；来源=' + sourceIdentity +
            (entry.captureMode === 'manual'
                ? '；方式=手动录入/修改'
                : '；方式=当前页读取') +
            (entry.sourcePageType
                ? '；页面=' + entry.sourcePageType
                : '') +
            (entry.admissionTime
                ? '；入院时间=' + entry.admissionTime
                : '') +
            (entry.dischargeDate
                ? '；出院日期=' + entry.dischargeDate
                : '') +
            '；提取时间=' +
            String(entry.capturedAt || '');
    }

    async function admissionRecordAiJumpToAdmissionPage(
        targetOverride,
        createIfMissing
    ) {
        const target =
            targetOverride ||
            admissionRecordAiLoadTargetPatient() ||
            extractCurrentPatientIdentity();

        const medicalRecordTab =
            findProgressNavigationTarget(['病历管理']);

        if (medicalRecordTab) {
            realClick(medicalRecordTab);
            await sleep(1000);
        }

        if (target && (target.name || target.inpatientNo)) {
            const selected =
                await selectProgressPatientFromLeftList(target);

            if (!selected) {
                showStatus(
                    '已进入病历管理，但未能在左侧患者列表中选择“' +
                    patientIdentityLabel(target) + '”。',
                    'error'
                );
                return false;
            }
        }

        const activeIdentity =
            extractCurrentPatientIdentity();

        if (
            target &&
            (target.name || target.inpatientNo) &&
            !patientIdentityMatches(target, activeIdentity)
        ) {
            showStatus(
                '页面尚未稳定到目标患者“' +
                patientIdentityLabel(target) +
                '”，为避免打开其他患者入院病历，已停止跳转。',
                'error'
            );
            return false;
        }

        let record =
            findChildRecordRowAfterCategory('入院病历');

        if (!record) {
            const category =
                findMedicalRecordCategoryRow('入院病历');

            if (
                category &&
                expandMedicalRecordCategoryRow(category)
            ) {
                await sleep(600);
                record =
                    findChildRecordRowAfterCategory('入院病历');
            }
        }

        if (record) {
            showStatus('已定位当前患者入院病历，正在打开预览……');
            realDoubleClick(record.element);
            await sleep(1000);
            return true;
        }

        if (
            createIfMissing !== false &&
            clickMedicalRecordNewButton()
        ) {
            showStatus(
                '当前患者尚未找到已有入院病历，已点击“病历新建”。请在新建界面选择/创建入院记录。',
                'success'
            );
            await sleep(700);
            return true;
        }

        showStatus(
            '未找到当前患者已有入院病历，也未能定位“病历新建”按钮。',
            'error'
        );
        return false;
    }

    function admissionRecordAiNormalizeFormatRules(rawRules) {
        const defaults =
            medicalFormatClone(
                DEFAULT_ADMISSION_RECORD_FORMAT_RULES
            );

        const source =
            rawRules && typeof rawRules === 'object'
                ? rawRules
                : {};

        function booleanValue(value, fallback) {
            if (value == null) return fallback;
            return value !== false &&
                String(value).toLowerCase() !== 'false' &&
                String(value) !== '0';
        }

        return {
            historyIndent:
                medicalFormatClampInteger(
                    source.historyIndent,
                    defaults.historyIndent,
                    0,
                    60
                ),
            examinationTitleIndent:
                medicalFormatClampInteger(
                    source.examinationTitleIndent,
                    defaults.examinationTitleIndent,
                    0,
                    60
                ),
            vitalSignsIndent:
                medicalFormatClampInteger(
                    source.vitalSignsIndent,
                    defaults.vitalSignsIndent,
                    0,
                    60
                ),
            examinationIndent:
                medicalFormatClampInteger(
                    source.examinationIndent,
                    defaults.examinationIndent,
                    0,
                    60
                ),
            specialtyIndent:
                medicalFormatClampInteger(
                    source.specialtyIndent,
                    defaults.specialtyIndent,
                    0,
                    60
                ),
            auxiliaryTitleIndent:
                medicalFormatClampInteger(
                    source.auxiliaryTitleIndent,
                    defaults.auxiliaryTitleIndent,
                    0,
                    60
                ),
            auxiliaryIndent:
                medicalFormatClampInteger(
                    source.auxiliaryIndent,
                    defaults.auxiliaryIndent,
                    0,
                    60
                ),
            initialDiagnosisIndent:
                medicalFormatClampInteger(
                    source.initialDiagnosisIndent,
                    defaults.initialDiagnosisIndent,
                    0,
                    60
                ),
            westernDiagnosisIndent:
                medicalFormatClampInteger(
                    source.westernDiagnosisIndent,
                    defaults.westernDiagnosisIndent,
                    0,
                    60
                ),
            westernContinuationIndent:
                medicalFormatClampInteger(
                    source.westernContinuationIndent,
                    defaults.westernContinuationIndent,
                    0,
                    60
                ),
            signatureIndent:
                medicalFormatClampInteger(
                    source.signatureIndent,
                    defaults.signatureIndent,
                    0,
                    80
                ),
            removeBlankLines:
                booleanValue(
                    source.removeBlankLines,
                    defaults.removeBlankLines
                ),
            normalizeColons:
                booleanValue(
                    source.normalizeColons,
                    defaults.normalizeColons
                ),
            normalizeSectionTitles:
                booleanValue(
                    source.normalizeSectionTitles,
                    defaults.normalizeSectionTitles
                )
        };
    }

    function admissionRecordAiLoadFormatRules() {
        return loadMedicalFormatRules(
            ADMISSION_RECORD_AI_FORMAT_RULES_STORAGE_KEY,
            DEFAULT_ADMISSION_RECORD_FORMAT_RULES,
            admissionRecordAiNormalizeFormatRules
        );
    }

    function admissionRecordAiTrimAfterSignature(textValue) {
        const source = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        const match = source.match(
            /(?:^|\n)[^\n]*医师签名\s*[：:]/
        );

        if (!match) return source;

        const index = match.index +
            (match[0].startsWith('\n') ? 1 : 0);

        const endIndex =
            admissionRecordAiLineEnd(source, index);

        return source.slice(0, endIndex).trim();
    }

    function normalizeGeneratedAdmissionRecordFormatting(
        textValue,
        rulesOverride
    ) {
        const rules =
            admissionRecordAiNormalizeFormatRules(
                rulesOverride ||
                admissionRecordAiLoadFormatRules()
            );

        let source =
            progressUnwrapGeneratedText({
                text: textValue
            });

        source =
            admissionRecordAiTrimAfterSignature(source);

        let lines = String(source || '')
            .replace(/\r\n?/g, '\n')
            .split('\n')
            .map(function (line) {
                return String(line || '')
                    .replace(/[ \t　]+$/g, '');
            });

        if (rules.removeBlankLines) {
            lines = lines.filter(function (line) {
                return String(line || '').trim() !== '';
            });
        }

        const historyIndent =
            '　'.repeat(rules.historyIndent);
        const examinationTitleIndent =
            '　'.repeat(rules.examinationTitleIndent);
        const vitalSignsIndent =
            '　'.repeat(rules.vitalSignsIndent);
        const examinationIndent =
            '　'.repeat(rules.examinationIndent);
        const specialtyIndent =
            '　'.repeat(rules.specialtyIndent);
        const auxiliaryTitleIndent =
            '　'.repeat(rules.auxiliaryTitleIndent);
        const auxiliaryIndent =
            '　'.repeat(rules.auxiliaryIndent);
        const initialDiagnosisIndent =
            '　'.repeat(rules.initialDiagnosisIndent);
        const westernDiagnosisIndent =
            '　'.repeat(rules.westernDiagnosisIndent);
        const westernContinuationIndent =
            '　'.repeat(rules.westernContinuationIndent);
        const signatureIndent =
            '　'.repeat(rules.signatureIndent);

        let section = 'basic';
        let examinationBodyStarted = false;

        const output = [];

        lines.forEach(function (rawLine) {
            let value = String(rawLine || '').trim();

            if (!value) {
                if (!rules.removeBlankLines) {
                    output.push('');
                }
                return;
            }

            if (rules.normalizeColons) {
                value = value
                    .replace(/^(姓名|出生地|性别|职业|年龄|入院日期|婚姻|记录日期|民族|病史陈述者|主诉|现病史|入院症见|既往史|个人史|月经史|婚育史|家族史|中医望闻切诊|专科查体|辅助检查|初步诊断|中医诊断|西医诊断|医师签名)\s*:/, '$1：');
            }

            if (/^体\s*格\s*检\s*查$/.test(value)) {
                section = 'examination';
                examinationBodyStarted = false;
                output.push(
                    examinationTitleIndent +
                    (
                        rules.normalizeSectionTitles
                            ? '体  格  检  查'
                            : value
                    )
                );
                return;
            }

            if (/^辅\s*助\s*检\s*查$/.test(value)) {
                section = 'auxiliary';
                output.push(
                    auxiliaryTitleIndent +
                    (
                        rules.normalizeSectionTitles
                            ? '辅  助  检  查'
                            : value
                    )
                );
                return;
            }

            if (/^初步诊断\s*[：:]/.test(value)) {
                section = 'diagnosis';
                output.push(
                    initialDiagnosisIndent + value
                );
                return;
            }

            if (/^医师签名\s*[：:]/.test(value)) {
                output.push(
                    signatureIndent +
                    value.replace(/^[ \t　]+/, '')
                );
                section = 'signature';
                return;
            }

            if (
                /^(主诉|现病史|既往史|个人史|月经史|婚育史|家族史|中医望闻切诊)\s*[：:]/.test(
                    value
                )
            ) {
                output.push(historyIndent + value);
                section = 'history';
                return;
            }

            if (section === 'examination') {
                if (/^[TＴ]\s*[：:]?\s*\d/i.test(value)) {
                    output.push(vitalSignsIndent + value);
                    examinationBodyStarted = true;
                    return;
                }

                if (/^专科查体\s*[：:]/.test(value)) {
                    output.push(specialtyIndent + value);
                    return;
                }

                output.push(
                    (examinationBodyStarted
                        ? examinationIndent
                        : '') +
                    value
                );
                examinationBodyStarted = true;
                return;
            }

            if (section === 'auxiliary') {
                output.push(auxiliaryIndent + value);
                return;
            }

            if (section === 'diagnosis') {
                if (/^西医诊断\s*[：:]/.test(value)) {
                    output.push(
                        westernDiagnosisIndent + value
                    );
                    return;
                }

                if (/^\d+[.、．]/.test(value)) {
                    output.push(
                        westernContinuationIndent + value
                    );
                    return;
                }
            }

            output.push(value);
        });

        return output.join('\n')
            .replace(/^\n+|\n+$/g, '');
    }

    function admissionRecordAiTextLooksComplete(textValue) {
        const text = String(textValue || '');

        return /姓名\s*[：:]/.test(text) &&
            /主诉\s*[：:]/.test(text) &&
            /现病史\s*[：:]/.test(text) &&
            /既往史\s*[：:]/.test(text) &&
            /中医望闻切诊\s*[：:]/.test(text) &&
            /体\s*格\s*检\s*查/.test(text) &&
            /专科查体\s*[：:]/.test(text) &&
            /辅\s*助\s*检\s*查/.test(text) &&
            /初步诊断\s*[：:]/.test(text) &&
            /医师签名\s*[：:]/.test(text);
    }

    function admissionRecordAiInitialSystemPrompt(
        supplementValidationEnabled,
        supplementHighPriorityEnabled
    ) {
        const lines = [
            '你是中国医院住院病历“入院记录”整理助手。',
            '必须逐条执行customPrompt中的全部规则。',
            'outpatientRecordText是本次入院的门诊记录，是主诉、现病史和本次入院原因的主要来源。',
            'currentAdmissionOrderInformation是可选的当前住院结构化医嘱，只能作为入院时诊疗背景；不得根据药物用途反推疾病，不得把住院后才开立、停止、执行或回报的内容倒写进入院记录。',
            'priorAdmissionRecordText和priorDischargeRecordText仅是可选既往资料；可用于核实既往史、既往诊治和历史明确诊断，不得把既往住院的生命体征、当前症状、查体或检查结果冒充为本次入院资料。'
        ];

        if (!supplementValidationEnabled) {
            lines.push(
                'supplementalInformation是用户人工补充的个人信息、诊断、辅助检查、护理评估及其他原始资料；其中有明确日期和来源的正式资料优先。',
                '不同来源冲突时按customPrompt中的优先级处理；无法确定时写“资料记录不一致，具体待核实”。'
            );
        } else {
            lines.push(
                'supplementalInformation是医生在本次生成前人工补充并确认的个人信息、诊断、辅助检查、护理评估及其他原始资料，不得把它降格为可自由取舍的普通建议。',
                'confirmedSupplementChecklist是脚本从补充资料中结构化提取的强制清单：confirmedDiagnosisItems中的每项诊断必须以原名称逐字出现在“初步诊断”，不得遗漏、改名、升级、降级或改变分级/分期/危险分层；personalFacts、auxiliaryFacts及otherFacts必须逐项写入对应段落，并保留数字、日期、侧别和限定语。',
                supplementHighPriorityEnabled
                    ? '补充资料具有最高权重；与任何其他来源不一致时，必须直接以补充资料替换冲突内容，正文不得说明冲突、资料来源或修改过程，也不得出现“资料记录不一致”“具体待核实”“根据补充资料”等说明。'
                    : '不同来源冲突时，不得静默删除或改写医生确认清单；应保留清单原文，并写“资料记录不一致，具体待核实”。'
            );
        }

        lines.push(
            '最终必须从“姓名：”开始，完整输出到“医师签名：”结束。',
            '不得继续输出诊断依据、鉴别诊断、诊疗计划、解释、资料来源、JSON、Markdown或代码块。'
        );

        return lines.join('\n');
    }

    function admissionRecordAiSupplementRepairSystemPrompt(
        supplementHighPriorityEnabled
    ) {
        return [
            '你是中国医院住院病历“入院记录”补充资料一致性修复助手。',
            'sourceAdmissionRecordText是结构完整的入院记录初稿；本次只能修复confirmedSupplementChecklist及missingSupplementItems所指出的遗漏或擅自改写，以及highPriorityConflictExplanationDetected所指出的高权重冲突说明。',
            '必须保留初稿中未涉及本次修复的全部段落、事实、日期、检查、查体和诊断，不得借机重写或删减。',
            'confirmedDiagnosisItems由医生人工确认：每一项必须以原名称逐字写入“初步诊断”，包括分级、分期、危险分层、侧别、并发症及“待查”等限定语；不得使用近义诊断替代，也不得把“极高危”改成“高危”。',
            'personalFacts必须分别写入既往史、个人史、婚育史、家族史或中医望闻切诊等适当段落；auxiliaryFacts必须保留日期、项目及结论原文；otherFacts必须写入合适段落。',
            supplementHighPriorityEnabled
                ? '若医生确认清单与初稿或其他来源冲突，必须直接以医生确认清单内容替换冲突内容；正文不得说明冲突、资料来源或修改过程，也不得出现“资料记录不一致”“具体待核实”“根据补充资料”等说明。'
                : '若医生确认清单与初稿或其他来源冲突，保留医生确认原文并标注“资料记录不一致，具体待核实”，不得静默舍弃。',
            '最终仍须从“姓名：”开始，完整输出到“医师签名：”结束，不得输出解释、核对表、JSON、Markdown或代码块。'
        ].join('\n');
    }

    function admissionRecordAiExpansionSystemPrompt(
        type,
        positiveSimulationOptions
    ) {
        const requirements = {
            presentIllness:
                '只返回“现病史：……入院症见：……”完整段落。',
            pastHistory:
                '只返回“既往史：……”完整段落。',
            examination:
                '只返回“体  格  检  查”标题、生命体征、一般查体和“专科查体：……”。'
        };
        const options = Object.assign(
            {
                specialtyExamination: false,
                generalExamination: false,
                presentIllness: false,
                pastHistory: false,
                strategy: 'conservative'
            },
            positiveSimulationOptions || {}
        );
        const aggressive = options.strategy === 'aggressive';
        const policy = [];

        if (type === 'presentIllness') {
            policy.push(
                options.presentIllness
                    ? (
                        aggressive
                            ? '【阳性现病史：已开启｜激进策略】本次仅用于标准化患者/测试病例模拟。允许在不覆盖初稿明确事实的前提下，根据首位西医诊断、主诉及整体病情生成真实患者风格的精确阳性细节；可无原文依据地模拟具体病程年限、加重天数、症状程度评分（如NRS）、发作频率、持续时间、步行/站立耐量、放射或累及范围、诱发/缓解因素及必要侧别，使时间轴与诊断自洽。若初稿已有时间、侧别、程度、症状或阴性描述，必须优先保留，不得冲突；不得新增另一种疾病诊断、伪造真实医院或把模拟检查结果写成既有事实。'
                            : '【阳性现病史：已开启｜保守策略】本次用于标准化患者模拟。允许依据初稿中已有的首位西医诊断、主诉、症状和侧别，补充典型、非危急、前后自洽的阳性症状特点与伴随表现；新增内容属于模拟值。不得新增新的疾病诊断、检查结果、药物、医院、手术、精确时间或数值。'
                    )
                    : '【阳性现病史：未开启】采用事实保守策略。除sourceAdmissionRecordText已经明确存在的阳性症状外，不得新增新的阳性症状、伴随症状、功能障碍或加重表现；允许补充中性的医学化连接语句。'
            );
        }

        if (type === 'pastHistory') {
            policy.push(
                options.pastHistory
                    ? (
                        aggressive
                            ? '【阳性既往史：已开启｜激进策略】本次仅用于标准化患者/测试病例模拟。只围绕初稿中已经存在的慢性基础病、既往明确诊断或术后状态，可无原文依据地生成具体且临床常见的模拟细节，例如病程年限、既往最高血压/血糖、常见药物名称与剂量、控制水平、某年接受与已知术后状态相符的常见手术方式等，使既往史呈现真实患者风格。不得新增初稿中不存在的新疾病或过敏原；不得覆盖初稿已有明确年份、数值、药物、术式；具体医院名称原则上不虚构，可写“外院”。'
                            : '【阳性既往史：已开启｜保守策略】只允许围绕初稿中已经存在的慢性基础病、既往明确诊断或术后状态扩展阳性既往史；未知的病程年限、最高数值、药名、剂量、医院、手术方式和过敏原仍必须写“不详”，不得新增初稿中没有的疾病。'
                    )
                    : '【阳性既往史：未开启】采用事实保守策略。不得把初步诊断或医学常识反向改造成没有原文依据的既往病史；缺失事实使用“不详/治疗情况不详/控制情况不详”等表述。'
            );
        }

        if (type === 'examination') {
            policy.push(
                options.generalExamination
                    ? (
                        aggressive
                            ? '【阳性一般查体：已开启｜激进策略】本次仅用于标准化患者/测试病例模拟。允许根据首位西医诊断与整体病情生成具体阳性一般查体，包括可量化或分级的压痛范围、活动受限、水肿分级、杂音级别、啰音分布等。已有T/P/R/BP及初稿明确查体必须原样保留；模拟值不得与已知事实冲突，不得无逻辑地制造休克、昏迷、重度呼吸衰竭等危急状态。'
                            : '【阳性一般查体：已开启｜保守策略】可依据首位西医诊断及已有症状，在一般查体中加入少量典型、非危急且逻辑一致的阳性体征；不得生成新的生命体征数值，不得覆盖初稿已有查体事实。'
                    )
                    : '【阳性一般查体：未开启】一般查体未知项目只能补充常规正常/阴性结果；除初稿已明确存在者外，禁止新增黄疸、淋巴结肿大、啰音、杂音、腹部压痛、水肿、活动受限等阳性体征。',
                options.specialtyExamination
                    ? (
                        aggressive
                            ? '【阳性专科查体：已开启｜激进策略】本次仅用于标准化患者/测试病例模拟。允许根据首位西医诊断、主诉和已有症状生成真实患者风格的精确阳性专科查体；可无原文依据地模拟具体活动角度、直腿抬高角度、肌力MRC分级、肌张力、腱反射分级、感觉减退范围、诱发试验阳性、病理征、步态及功能受限程度等。侧别未知时可选择与整体症状最自洽的一侧。已有侧别、角度、肌力、感觉、反射、病理征等明确事实必须原样保留；不得形成互相矛盾的神经定位，也不要为了“更阳性”而机械堆砌全部异常项目。'
                            : '【阳性专科查体：已开启｜保守策略】可根据首位西医诊断、主诉、已有症状和侧别生成典型、非危急的专科阳性体征，使专科查体与诊断相互支持。原文未提供时不得编造精确角度、肌力分级、感觉平面、反射等级等数值；侧别不明不得自行指定。'
                    )
                    : '【阳性专科查体：未开启】专科查体未知项目只能补充常规正常/阴性结果；除初稿已有明确事实外，不得为了支持诊断新增压痛、诱发试验阳性、肌力下降、感觉减退、病理征阳性等专科阳性体征。'
            );
        }

        return [
            '你是中国医院住院病历定向扩充助手。',
            'sourceAdmissionRecordText是当前患者完整入院记录初稿。',
            'customExpansionPrompt规定本次唯一允许扩充的部分，必须严格执行。',
            'positiveSimulationOptions是标准化患者模拟开关；strategy只在对应阳性开关为true时生效：conservative=保守，aggressive=激进。',
            aggressive
                ? '【激进策略总则】允许在“已勾选的阳性目标段落”中生成没有原始资料依据的精确模拟值，以构造前后自洽的标准化患者。所有此类新增精确值都视为虚拟测试数据。初稿中任何已经明确的姓名、日期、诊断、检查、药物、数值、侧别及阳性/阴性事实均为不可覆盖约束。未勾选的段落仍严格按真实事实保守处理。'
                : '【保守策略总则】沿用受控阳性模拟：可补充合理阳性表现，但不凭空生成精确角度、分级、具体年限、具体数值等。',
            '必须保留初稿中已有的姓名、日期、主诉事实、疾病、检查结果、生命体征和既有阳性体征，不得改动未选择段落。',
            requirements[type] || '',
            policy.join('\n'),
            '所有由阳性开关新增的内容均属于标准化患者模拟值，只用于测试/教学模拟；尤其“激进”策略会主动生成无原文依据的精确值，不得直接作为真实患者病历事实使用。',
            '不得返回完整入院记录，不得输出解释、JSON、Markdown或代码块。'
        ].join('\n');
    }

    function admissionRecordAiExpansionLooksComplete(
        type,
        textValue
    ) {
        const text = String(textValue || '');

        if (type === 'presentIllness') {
            return /现病史\s*[：:]/.test(text) &&
                /入院症见\s*[：:]/.test(text);
        }

        if (type === 'pastHistory') {
            return /既往史\s*[：:]/.test(text);
        }

        if (type === 'examination') {
            return /体\s*格\s*检\s*查/.test(text) &&
                /专科查体\s*[：:]/.test(text);
        }

        return false;
    }

    /*
     * v2.41.17：生成区“主诉优化”定向复核 + 严格模式。
     *
     * 普通模式延续v2.41.16：目标约20字，但以事实完整和时间一致为先；
     * 严格模式由用户临时勾选后启用“≤20字”激进压缩，并在脚本层对
     * 有效字符数再次硬校验。若AI首次超限，现有完整性重试链会自动要求
     * 从头压缩；重试后仍超限则停止替换，原主诉保持不变。
     *
     * 与“生成初版入院记录”分离：AI读取当前完整初版，只复核主诉是否
     * 突出本次主要住院问题、时间轴是否与现病史一致、表达是否简洁规范。
     * AI只返回优化后的“主诉”及复核说明；脚本随后仅替换正文首个
     * “主诉：”行，现病史、入院症见、查体、诊断及其他段落保持原样。
     */
    function admissionRecordAiChiefComplaintEffectiveText(value) {
        return String(value || '')
            .replace(/^\s*主诉\s*[：:]\s*/, '')
            .replace(/[\s\u3000]/g, '')
            .replace(/[，。；;、,.!?！？：:"“”'‘’（）()《》【】\[\]〈〉—–-]/g, '');
    }

    function admissionRecordAiChiefComplaintCount(value) {
        return Array.from(
            admissionRecordAiChiefComplaintEffectiveText(value)
        ).length;
    }

    /*
     * v2.41.19：主诉字符数检测。
     * 与“严格模式≤20字”共用完全相同的有效字符计数口径，避免界面检测
     * 与主诉优化硬校验出现不一致。这里只读取当前结果框中的第一处独立
     * “主诉：”行，不调用AI、不修改正文，也不创建/覆盖定向修改还原快照。
     */
    function admissionRecordAiChiefComplaintDetect(sourceValue) {
        const source = String(sourceValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        if (!source) {
            throw new Error('当前初版入院记录为空。');
        }

        const match = source.match(
            /(?:^|\n)\s*主诉\s*[：:]\s*([^\n]+)/m
        );

        if (!match || !String(match[1] || '').trim()) {
            throw new Error(
                '当前入院记录中未找到可识别的独立“主诉：”行。'
            );
        }

        const complaint = String(match[1] || '')
            .trim();
        const effectiveCount =
            admissionRecordAiChiefComplaintCount(complaint);

        return {
            complaint: complaint,
            effectiveCount: effectiveCount,
            withinStrictLimit: effectiveCount <= 20
        };
    }

    function admissionRecordAiChiefComplaintSystemPrompt(strictMode) {
        const strict = Boolean(strictMode);
        const lines = [
            '你是中国医院住院病历“入院记录”主诉规范化复核助手。',
            'sourceAdmissionRecordText是当前已经生成或由医生手工粘贴的完整入院记录。你必须结合其中现有主诉、现病史、入院症见、既往史、查体和初步诊断，判断当前主诉是否准确概括本次住院最主要问题，并在必要时进行最小幅度规范化优化。',
            '主诉必须以本次住院最主要的真实症状、体征或功能障碍为核心，通常写“主要症状＋病程时间”；不得为了与诊断对应而新增原文未出现的症状、侧别、部位、严重程度、诱因、伴随症状、病程时间或发作频率。',
            '主诉中的所有时间必须能从当前入院记录中直接得到明确依据，并与现病史时间轴一致。不得自行换算、推测或把疾病总病程误写成本次症状病程。',
            '若原文明确存在“长期反复＋近期加重”的时间结构，可规范为“反复×××年，加重×天。”或“反复×××年，加重伴×××天。”；只有一个明确起病时间时，不得擅自改造成“两段式病程”。',
            '原则上不直接以疾病诊断名称、检查结果、治疗目的或住院目的作为主诉；但原始资料明确属于已确诊疾病复诊、治疗且缺乏可替代的症状性主诉时，可保守保留原有疾病性表述，不得自行杜撰症状。',
            '主诉应突出1～2个最核心症状，删除与本次住院关系较弱的次要症状堆砌，不写检查结果、既往疾病清单、治疗经过或诊断依据。'
        ];

        if (strict) {
            lines.push(
                '【严格模式已开启】必须执行激进压缩策略：最终“主诉：”正文强制不超过20个有效字符。脚本按去除空白和标点后的字符数计数，汉字、数字、英文字母均按1个字符计算。',
                '≤20字是本次任务的硬性约束，而不是建议。必须主动删除次要症状、重复修饰、非必要程度描述和可由现病史承载的细节；优先保留最核心症状/功能障碍以及最有依据的病程时间。',
                '若原文明确存在“长期反复＋近期加重”，应尽量在20字内保留两段时间；确因字数冲突无法同时保留所有次要信息时，可以牺牲次要症状或冗余修饰，但不得改变核心事实、时间含义、侧别等仍被保留的信息，也不得制造新事实。',
                '不得通过删除必要数字中的位数、改变时间单位、模糊时间、使用未经原文支持的缩写或改成疾病诊断名称来规避20字限制。'
            );
        } else {
            lines.push(
                '当前为普通模式：语言使用规范医学中文，通常控制为一句，约20个汉字左右；在不损失已有关键事实、侧别、部位和时间信息的前提下尽量简洁。字数不是硬限制。'
            );
        }

        lines.push(
            '如果当前主诉已经合理、规范且与现病史一致，应原样保留或仅做标点、语序等最小调整；但严格模式下即使原主诉合理，只要超过20个有效字符也必须在不虚构事实的前提下进一步压缩至≤20字。',
            '只输出两行纯文本，不得输出Markdown、JSON、序号、解释性前言或其他内容：',
            '主诉：优化后的主诉。',
            '复核说明：用1～2句说明是否调整，以及调整依据；不得补造患者事实。'
        );

        return lines.join('\n');
    }

    function admissionRecordAiChiefComplaintLooksComplete(
        textValue,
        strictMode
    ) {
        const text = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        const complaintMatch = text.match(
            /(?:^|\n)\s*主诉\s*[：:]\s*([^\n]+)/
        );
        const reviewMatched =
            /(?:^|\n)\s*复核说明\s*[：:]\s*\S+/.test(text);

        if (!complaintMatch || !complaintMatch[1] || !reviewMatched) {
            return false;
        }

        if (
            strictMode &&
            admissionRecordAiChiefComplaintCount(
                complaintMatch[1]
            ) > 20
        ) {
            return false;
        }

        return true;
    }

    function admissionRecordAiParseChiefComplaint(
        textValue,
        strictMode
    ) {
        const text = progressUnwrapGeneratedText({
            text: textValue
        })
            .replace(/\r\n?/g, '\n')
            .trim();

        const complaintMatch = text.match(
            /(?:^|\n)\s*主诉\s*[：:]\s*([^\n]+)/
        );
        const reviewMatch = text.match(
            /(?:^|\n)\s*复核说明\s*[：:]\s*([^\n]+)/
        );

        if (!complaintMatch || !complaintMatch[1]) {
            throw new Error('AI未返回可识别的“主诉：……”。');
        }

        let complaint = String(complaintMatch[1] || '')
            .trim()
            .replace(/^主诉\s*[：:]\s*/, '')
            .replace(/[。；;]+$/g, '')
            .trim();

        if (!complaint) {
            throw new Error('AI返回的优化主诉为空。');
        }

        const effectiveCount =
            admissionRecordAiChiefComplaintCount(complaint);

        if (strictMode && effectiveCount > 20) {
            throw new Error(
                '严格模式要求主诉≤20字，AI返回' +
                effectiveCount +
                '字，已停止替换原主诉。'
            );
        }

        if (complaint.length > 120) {
            throw new Error('AI返回的优化主诉异常过长，已停止替换。');
        }

        complaint += '。';

        return {
            complaint: complaint,
            effectiveCount: effectiveCount,
            review: String(
                reviewMatch && reviewMatch[1] || ''
            ).trim()
        };
    }

    function admissionRecordAiReplaceChiefComplaint(
        sourceValue,
        complaintValue
    ) {
        const source = String(sourceValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();
        const complaint = String(complaintValue || '')
            .replace(/^\s*主诉\s*[：:]\s*/, '')
            .trim();

        if (!source) {
            throw new Error('当前初版入院记录为空。');
        }

        if (!complaint) {
            throw new Error('主诉优化结果为空。');
        }

        const existingPattern =
            /(^|\n)([ \t　]*主诉\s*[：:]\s*)([^\n]*)/m;

        if (!existingPattern.test(source)) {
            throw new Error(
                '当前入院记录中未找到独立“主诉：”行，无法安全定向替换。'
            );
        }

        return source.replace(
            existingPattern,
            function (full, leading, prefix) {
                return leading + prefix + complaint;
            }
        ).trim();
    }

    /*
     * v2.41.9：生成区“中医辨病辨证”定向复核。
     *
     * 与“生成初版入院记录”分离：这里只根据当前已经生成/手工粘贴的
     * 完整入院记录复核“中医病名＋证型”，脚本随后只确定性替换
     * “初步诊断→中医诊断”这一处文字。中医望闻切诊、入院症见、
     * 现病史、查体、西医诊断等其他内容均不会被本按钮反向改写。
     */
    function admissionRecordAiTcmDifferentiationSystemPrompt(
        supplementValidationEnabled,
        supplementHighPriorityEnabled
    ) {
        const lines = [
            '你是中国医院住院病历“入院记录”中医辨病辨证复核助手。',
            'sourceAdmissionRecordText是当前已经生成或由医生手工粘贴的完整入院记录；其中原有“中医诊断”仅作为待复核候选，不得因为它已经存在就机械照抄。',
            '必须优先依据本次入院真实的主诉、现病史、入院症见以及中医望闻切诊中的舌象、苔象、脉象等资料进行辨病辨证，并结合与本次主病直接相关的既往史和入院前辅助检查综合判断。',
            '不得仅根据西医诊断名称机械映射中医病名或证型；不得为了迎合某个证型而反向补造、修改或假设舌象、苔象、脉象、寒热、饮食、睡眠、二便或其他症状。',
            '本任务只允许提出一个最符合本次主要住院问题的中医主病名和一个主证型；不要罗列多个互斥候选。',
            '若现有资料不足以支持非常具体的证型，应选择证据最充分、表述相对保守的规范证型，并在辨证依据中明确指出资料不足之处，不得虚构缺失四诊。'
        ];

        if (supplementValidationEnabled) {
            lines.push(
                supplementHighPriorityEnabled
                    ? 'supplementalInformation中的补充诊断属于医生已确认且高权重的本次资料；如其中明确给出中医病名或证型，必须优先采用，不得另行改成其他病名或证型。若只给出病名或只给出证型，可结合当前真实资料补全缺失部分。'
                    : 'supplementalInformation中的补充诊断属于医生已确认的本次资料；如其中明确给出中医病名或证型，应优先保留并结合当前真实资料核对。若只给出病名或只给出证型，可补全缺失部分。'
            );
        } else {
            lines.push(
                'supplementalInformation如有内容，只按普通参考资料使用；应结合当前入院记录中的本次症状和真实四诊综合辨证。'
            );
        }

        lines.push(
            '只输出两行纯文本，不得输出Markdown、JSON、序号、解释性前言或其他内容：',
            '中医诊断：病名（证型）',
            '辨证依据：用1～3句简洁说明主症、兼症及真实舌苔脉与病机之间的对应关系；不得补造未提供的四诊。'
        );

        return lines.join('\n');
    }

    function admissionRecordAiTcmDifferentiationLooksComplete(textValue) {
        const text = String(textValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        return /(?:^|\n)\s*中医诊断\s*[：:]\s*[^\n]{1,80}[（(][^\n）)]{1,50}[）)]/.test(text) &&
            /(?:^|\n)\s*辨证依据\s*[：:]\s*\S+/.test(text);
    }

    function admissionRecordAiParseTcmDifferentiation(textValue) {
        const text = progressUnwrapGeneratedText({
            text: textValue
        })
            .replace(/\r\n?/g, '\n')
            .trim();

        const diagnosisMatch = text.match(
            /(?:^|\n)\s*中医诊断\s*[：:]\s*([^\n]+)/
        );
        const basisMatch = text.match(
            /(?:^|\n)\s*辨证依据\s*[：:]\s*([^\n]+)/
        );

        if (!diagnosisMatch || !diagnosisMatch[1]) {
            throw new Error('AI未返回可识别的“中医诊断：病名（证型）”。');
        }

        const diagnosis = String(diagnosisMatch[1] || '')
            .trim()
            .replace(/[；;。]+$/g, '');
        const basis = String(
            basisMatch && basisMatch[1] || ''
        ).trim();

        if (!/[（(][^）)]{1,50}[）)]/.test(diagnosis)) {
            throw new Error('AI返回的中医诊断缺少“病名（证型）”结构。');
        }

        return {
            diagnosis: diagnosis,
            basis: basis
        };
    }

    function admissionRecordAiReplaceTcmDiagnosis(
        sourceValue,
        diagnosisValue
    ) {
        const source = String(sourceValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();
        const diagnosis = String(diagnosisValue || '')
            .replace(/^\s*中医诊断\s*[：:]\s*/, '')
            .trim();

        if (!source) {
            throw new Error('当前初版入院记录为空。');
        }

        if (!diagnosis) {
            throw new Error('中医辨病辨证结果为空。');
        }

        const existingPattern =
            /(中医诊断\s*[：:]\s*)(.*?)(?=\n\s*西医诊断\s*[：:]|[ \t　]+西医诊断\s*[：:])/s;

        if (existingPattern.test(source)) {
            return source.replace(
                existingPattern,
                function (full, prefix) {
                    return prefix + diagnosis;
                }
            ).trim();
        }

        const westernMatch = source.match(
            /(?:^|\n)\s*西医诊断\s*[：:]/m
        );

        if (!westernMatch) {
            throw new Error(
                '当前入院记录中未找到“西医诊断：”，无法确定性插入中医诊断。'
            );
        }

        const insertAt = westernMatch.index +
            (westernMatch[0].startsWith('\n') ? 1 : 0);

        return (
            source.slice(0, insertAt).replace(/[ \t　]*$/, '') +
            '中医诊断：' + diagnosis + '\n' +
            source.slice(insertAt).replace(/^\s*/, '')
        ).trim();
    }

    async function admissionRecordAiGenerateText(
        payload,
        systemPrompt,
        completenessCheck,
        statusCallback,
        taskLabel
    ) {
        resetProgressGenerationAbort();

        const runtime =
            buildMedicalAiRuntimeSettings(loadConfig());

        if (!suiteGlobalAiHasApiKey(runtime.apiKey)) {
            throw new Error(
                '尚未配置当前AI服务所需API Key，请在“自动填写住院信息→默认值设置”或悬浮框管理器中配置。'
            );
        }

        let model =
            runtime.mode === 'reasoning'
                ? runtime.writingModel
                : 'deepseek-chat';

        if (typeof statusCallback === 'function') {
            statusCallback(
                'AI病历模式=' +
                medicalAiModeLabel(runtime.mode) +
                '；正在使用' + model +
                '生成' + taskLabel + '……'
            );
        }

        let text = '';

        try {
            text = await progressDeepSeekPlainTextRequest(
                runtime.apiKey,
                model,
                systemPrompt,
                payload,
                runtime.mode === 'reasoning'
                    ? runtime.reasoningMaxTokens
                    : runtime.plainMaxTokens,
                300000,
                taskLabel
            );
        } catch (error) {
            if (
                runtime.mode !== 'reasoning' ||
                !runtime.autoFallbackChat ||
                !medicalAiRetryableError(error)
            ) {
                throw error;
            }

            assertProgressGenerationNotAborted();

            if (typeof statusCallback === 'function') {
                statusCallback(
                    '推理模式未取得完整正文（' +
                    error.message +
                    '），正在自动切换deepseek-chat直出……'
                );
            }

            model = 'deepseek-chat';

            text = await progressDeepSeekPlainTextRequest(
                runtime.apiKey,
                model,
                systemPrompt,
                Object.assign({}, payload, {
                    fallbackRequirement:
                        '上一轮未取得可用正文。本轮禁止输出思考过程，直接输出最终内容。'
                }),
                runtime.plainMaxTokens,
                320000,
                taskLabel + 'Chat降级'
            );
        }

        text = progressUnwrapGeneratedText({
            text: text
        }).trim();

        if (!completenessCheck(text)) {
            assertProgressGenerationNotAborted();

            if (typeof statusCallback === 'function') {
                statusCallback(
                    '首次返回缺少必要段落，正在使用长文额度从头重试……'
                );
            }

            const retryModel =
                runtime.mode === 'reasoning' &&
                !runtime.autoFallbackChat
                    ? runtime.writingModel
                    : 'deepseek-chat';

            text = await progressDeepSeekPlainTextRequest(
                runtime.apiKey,
                retryModel,
                systemPrompt,
                Object.assign({}, payload, {
                    retryRequirement:
                        '上一轮输出缺段或超出允许范围。请从头生成，严格满足全部固定段落和结束位置；不要输出思考过程、JSON或Markdown。'
                }),
                runtime.retryMaxTokens,
                360000,
                taskLabel + '完整性重试'
            );

            text = progressUnwrapGeneratedText({
                text: text
            }).trim();
        }

        if (!completenessCheck(text)) {
            const error = new Error(
                'DeepSeek已返回内容，但仍未满足必要段落结构。请检查资料或提高“AI病历Token”后重试。'
            );
            error.name = 'ProgressAiIncompleteContentError';
            throw error;
        }

        return text;
    }

    function admissionRecordAiNormalizeExpansionSection(
        type,
        textValue
    ) {
        let text = progressUnwrapGeneratedText({
            text: textValue
        })
            .replace(/\r\n?/g, '\n')
            .trim();

        let startMatch = null;
        let endPattern = null;

        if (type === 'presentIllness') {
            startMatch = text.match(/现病史\s*[：:]/);
            endPattern =
                /(?:^|\n)\s*既往史\s*[：:]/m;
        } else if (type === 'pastHistory') {
            startMatch = text.match(/既往史\s*[：:]/);
            endPattern =
                /(?:^|\n)\s*(?:个人史|月经史|婚育史|家族史|中医望闻切诊)\s*[：:]/m;
        } else if (type === 'examination') {
            startMatch = text.match(/体\s*格\s*检\s*查/);
            endPattern =
                /(?:^|\n)\s*辅\s*助\s*检\s*查/m;
        }

        if (!startMatch) {
            throw new Error('AI返回内容缺少目标段落标题');
        }

        text = text.slice(startMatch.index).trim();

        const endMatch = text.match(endPattern);
        if (endMatch) {
            text = text.slice(0, endMatch.index).trim();
        }

        if (
            !admissionRecordAiExpansionLooksComplete(type, text)
        ) {
            throw new Error('AI返回的扩充段落不完整');
        }

        return text;
    }

    function admissionRecordAiFindSectionRange(
        source,
        startPattern,
        endPattern
    ) {
        const startMatch = String(source || '').match(startPattern);

        if (!startMatch) return null;

        const start = startMatch.index +
            (startMatch[0].startsWith('\n') ? 1 : 0);

        const tail = String(source || '').slice(
            start + startMatch[0].length
        );

        const endMatch = tail.match(endPattern);

        if (!endMatch) return null;

        const end =
            start + startMatch[0].length +
            endMatch.index +
            (endMatch[0].startsWith('\n') ? 1 : 0);

        return {
            start: start,
            end: end
        };
    }

    function admissionRecordAiReplaceSection(
        sourceValue,
        type,
        replacementValue
    ) {
        const source = String(sourceValue || '')
            .replace(/\r\n?/g, '\n')
            .trim();

        const replacement =
            String(replacementValue || '').trim();

        let range = null;

        if (type === 'presentIllness') {
            range = admissionRecordAiFindSectionRange(
                source,
                /(?:^|\n)\s*现病史\s*[：:]/m,
                /(?:^|\n)\s*既往史\s*[：:]/m
            );
        } else if (type === 'pastHistory') {
            range = admissionRecordAiFindSectionRange(
                source,
                /(?:^|\n)\s*既往史\s*[：:]/m,
                /(?:^|\n)\s*(?:个人史|月经史|婚育史|家族史|中医望闻切诊)\s*[：:]/m
            );
        } else if (type === 'examination') {
            range = admissionRecordAiFindSectionRange(
                source,
                /(?:^|\n)\s*体\s*格\s*检\s*查\s*(?:\n|$)/m,
                /(?:^|\n)\s*辅\s*助\s*检\s*查\s*(?:\n|$)/m
            );
        }

        if (!range) {
            throw new Error(
                '初稿中未找到可安全替换的目标段落边界，请确认初稿包含完整固定标题。'
            );
        }

        return (
            source.slice(0, range.start).replace(/\s+$/, '') +
            (range.start > 0 ? '\n' : '') +
            replacement +
            '\n' +
            source.slice(range.end).replace(/^\s+/, '')
        ).trim();
    }

