    function updateAdmissionRecordAiModalStatus(modal) {
        const current = extractCurrentPatientIdentity();
        const target = admissionRecordAiLoadTargetPatient();
        const unlocked = patientAiLoadUnlocked(
            ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY
        );
        const effective = target || current;

        const patientBox =
            modal.querySelector('.admission-ai-current-patient');

        if (patientBox) {
            const sameNameDifferentAdmission =
                target &&
                admissionRecordAiSameName(target, current) &&
                target.inpatientNo &&
                current.inpatientNo &&
                progressNormalize(target.inpatientNo) !==
                    progressNormalize(current.inpatientNo);

            const mismatch =
                target &&
                (current.name || current.inpatientNo) &&
                !patientIdentityMatches(target, current) &&
                !sameNameDifferentAdmission;

            patientBox.textContent =
                '当前页面患者：' + patientIdentityLabel(current) +
                (target
                    ? '；入院记录AI目标：' +
                        patientIdentityLabel(target)
                    : '；尚未锁定目标患者。') +
                (sameNameDifferentAdmission
                    ? '；当前为同名不同住院号页面，可读取既往资料，但不可提取当前医嘱或当前初稿。'
                    : '') +
                (unlocked
                    ? '；已解锁：患者信息一致性校验已停用，请人工核对全部资料。'
                    : mismatch
                    ? '；患者姓名/身份不一致，请勿提取。'
                    : '');

            patientBox.className =
                'admission-ai-status admission-ai-current-patient ' +
                (unlocked ? 'warn' : mismatch ? 'error' :
                    sameNameDifferentAdmission ? 'warn' : 'ok');
        }

        const definitions = [
            {
                selector: '.admission-ai-outpatient-status',
                storageKey:
                    ADMISSION_RECORD_AI_OUTPATIENT_CACHE_STORAGE_KEY,
                label: '门诊信息',
                required: true
            },
            {
                selector: '.admission-ai-prior-admission-status',
                storageKey:
                    ADMISSION_RECORD_AI_PRIOR_ADMISSION_CACHE_STORAGE_KEY,
                label: '既往入院记录',
                enabled:
                    modal.querySelector('.admission-ai-use-prior-admission')
                        .checked
            },
            {
                selector: '.admission-ai-prior-discharge-status',
                storageKey:
                    ADMISSION_RECORD_AI_PRIOR_DISCHARGE_CACHE_STORAGE_KEY,
                label: '既往出院记录',
                enabled:
                    modal.querySelector('.admission-ai-use-prior-discharge')
                        .checked
            }
        ];

        definitions.forEach(function (definition) {
            const box = modal.querySelector(definition.selector);
            const cache = effective
                ? admissionRecordAiFindCache(
                    definition.storageKey,
                    effective
                )
                : null;

            box.textContent =
                admissionRecordAiCacheSummary(
                    cache,
                    definition.label
                );

            box.className =
                'admission-ai-status ' +
                definition.selector.replace('.', '') + ' ' +
                (cache
                    ? 'ok'
                    : definition.required || definition.enabled
                        ? 'warn'
                        : 'ok');
        });

        const orderBox =
            modal.querySelector('.admission-ai-order-status');
        const orderCache = effective
            ? admissionRecordAiFindCache(
                ADMISSION_RECORD_AI_ORDER_CACHE_STORAGE_KEY,
                effective
            )
            : null;
        const useOrders =
            modal.querySelector('.admission-ai-use-orders').checked;

        orderBox.textContent = orderCache
            ? '已缓存当前住院医嘱：' +
                Number(orderCache.orderCount || 0) + '条' +
                '；来源=' + inpatientOrderCacheSourceLabel(orderCache) +
                inpatientOrderCacheFilterSuffix(orderCache) +
                (orderCache.hiddenCount
                    ? '（含读取临床路径隐藏医嘱' +
                        orderCache.hiddenCount + '条）'
                    : '') +
                '；提取时间=' +
                String(orderCache.capturedAt || '')
            : useOrders
                ? '已开启医嘱读取，但尚未缓存当前目标患者医嘱。'
                : '当前未启用医嘱读取；生成时不会向AI提供医嘱。';

        orderBox.className =
            'admission-ai-status admission-ai-order-status ' +
            (orderCache ? 'ok' : useOrders ? 'warn' : 'ok');

        const draftBox =
            modal.querySelector('.admission-ai-draft-status');
        const draftSource =
            modal.querySelector('.admission-ai-draft-source');
        const draftCache = effective
            ? admissionRecordAiFindCache(
                ADMISSION_RECORD_AI_DRAFT_CACHE_STORAGE_KEY,
                effective
            )
            : null;

        draftBox.textContent = draftCache
            ? admissionRecordAiCacheSummary(
                draftCache,
                '当前入院记录初稿'
            )
            : '尚未提取当前页入院记录初稿，也未使用上方生成结果。';

        draftBox.className =
            'admission-ai-status admission-ai-draft-status ' +
            (draftCache ? 'ok' : 'warn');

        draftSource.value =
            draftCache && draftCache.text
                ? draftCache.text
                : '';
    }

