                            '</details>' +
                            '<div class="admission-ai-row" style="margin-top:10px;">' +
                                '<button type="button" class="primary admission-ai-expand-button" data-expand-type="presentIllness">扩充现病史</button>' +
                                '<button type="button" class="primary admission-ai-expand-button" data-expand-type="pastHistory">扩充既往史</button>' +
                                '<button type="button" class="primary admission-ai-expand-button" data-expand-type="examination">扩充查体及专科查体</button>' +
                                '<button type="button" class="secondary admission-ai-copy-expanded" disabled>复制完整扩充结果</button>' +
                                '<button type="button" class="secondary admission-ai-clear-expanded">清空扩充结果</button>' +
                                '<button type="button" class="danger admission-ai-expand-abort" disabled>中止</button>' +
                                '<label class="admission-ai-positive-strategy" title="仅对已勾选的阳性扩充项目生效；激进模式会生成无原文依据的精确模拟值，仅用于标准化患者/测试">阳性策略<select class="admission-ai-positive-strategy-select"><option value="conservative" selected>保守</option><option value="aggressive">激进</option></select></label>' +
                                '<label class="admission-ai-positive-option" title="仅在点击“扩充查体及专科查体”时生效；允许按首位西医诊断模拟专科阳性体征；具体精确程度由阳性策略决定"><input type="checkbox" class="admission-ai-positive-specialty-examination">阳性专科查体</label>' +
                                '<label class="admission-ai-positive-option" title="仅在点击“扩充查体及专科查体”时生效；允许按诊断模拟一般查体阳性体征；具体精确程度由阳性策略决定"><input type="checkbox" class="admission-ai-positive-general-examination">阳性一般查体</label>' +
                                '<label class="admission-ai-positive-option" title="仅在点击“扩充现病史”时生效；用于标准化患者模拟阳性症状；激进策略可生成具体年限、评分、频率等"><input type="checkbox" class="admission-ai-positive-present-illness">阳性现病史</label>' +
                                '<label class="admission-ai-positive-option" title="仅在点击“扩充既往史”时生效；仅围绕初稿已有疾病/术后状态模拟；激进策略可生成具体年限、数值、常见用药等"><input type="checkbox" class="admission-ai-positive-past-history">阳性既往史</label>' +
                            '</div>' +
                            '<div class="admission-ai-warning">未勾选阳性项目时始终采用事实保守扩充。勾选阳性项目后，“保守”沿用v2.41.11受控模拟，不生成无依据的精确数值；“激进”允许标准化患者/测试病例中生成与诊断自洽的无依据精确模拟值，如具体角度、肌力/反射/水肿等分级、病程年限、最高血压/血糖、症状评分与活动耐量等。激进模式属于虚拟病例生成，不得直接作为真实患者病历事实使用；未选择段落保持原样。</div>' +
                            '<div class="admission-ai-status admission-ai-expansion-status warn">尚未执行扩充。</div>' +
                            '<textarea class="admission-ai-expand-result" placeholder="扩充后仍输出完整入院记录；可依次扩充多个段落，后一次会保留前一次扩充结果。"></textarea>' +
                        '</div>' +
                    '</div>' +
                '</div>' +
            '</div>';

        document.body.appendChild(modal);

        const promptBox =
            modal.querySelector('.admission-ai-prompt');
        const outpatientEditorPanel =
            modal.querySelector('.admission-ai-outpatient-editor');
        const outpatientEditorBox =
            modal.querySelector('.admission-ai-outpatient-editor-box');
        const outpatientSecondaryEditorBox =
            modal.querySelector(
                '.admission-ai-outpatient-secondary-editor'
            );
        const supplementBoxes = {
            personal:
                modal.querySelector(
                    '.admission-ai-supplement-personal'
                ),
            diagnosis:
                modal.querySelector(
                    '.admission-ai-supplement-diagnosis'
                ),
            auxiliary:
                modal.querySelector(
                    '.admission-ai-supplement-auxiliary'
                ),
            other:
                modal.querySelector(
                    '.admission-ai-supplement-other'
                )
        };
        const supplementValidationBox =
            modal.querySelector(
                '.admission-ai-supplement-validation'
            );
        const supplementHighPriorityBox =
            modal.querySelector(
                '.admission-ai-supplement-high-priority'
            );
        const supplementHighPriorityOption =
            modal.querySelector(
                '.admission-ai-supplement-high-priority-option'
            );
        const formatBox =
            modal.querySelector('.admission-ai-format-normalize');
        const useOrdersBox =
            modal.querySelector('.admission-ai-use-orders');
        const usePriorAdmissionBox =
            modal.querySelector('.admission-ai-use-prior-admission');
        const usePriorDischargeBox =
            modal.querySelector('.admission-ai-use-prior-discharge');
        const resultBox =
            modal.querySelector('.admission-ai-result');
        const expansionResultBox =
            modal.querySelector('.admission-ai-expand-result');
        const generationStatus =
            modal.querySelector('.admission-ai-generation-status');
        const expansionStatus =
            modal.querySelector('.admission-ai-expansion-status');
        const generateButton =
            modal.querySelector('.admission-ai-generate');
        const abortButton =
            modal.querySelector('.admission-ai-abort');
        const tcmDifferentiationButton =
            modal.querySelector('.admission-ai-tcm-differentiation');
        const chiefComplaintOptimizeButton =
            modal.querySelector('.admission-ai-chief-complaint-optimize');
        const chiefComplaintCountButton =
            modal.querySelector('.admission-ai-chief-complaint-count');
        const chiefComplaintStrictBox =
            modal.querySelector('.admission-ai-chief-complaint-strict');
        const restorePreRevisionButton =
            modal.querySelector('.admission-ai-restore-pre-revision');
        const copyButton =
            modal.querySelector('.admission-ai-copy');
        const expandAbortButton =
            modal.querySelector('.admission-ai-expand-abort');
        const copyExpandedButton =
            modal.querySelector('.admission-ai-copy-expanded');
        const expandButtons =
            Array.from(
                modal.querySelectorAll('.admission-ai-expand-button')
            );
        const positiveSpecialtyExaminationBox =
            modal.querySelector('.admission-ai-positive-specialty-examination');
        const positiveGeneralExaminationBox =
            modal.querySelector('.admission-ai-positive-general-examination');
        const positivePresentIllnessBox =
            modal.querySelector('.admission-ai-positive-present-illness');
        const positivePastHistoryBox =
            modal.querySelector('.admission-ai-positive-past-history');
        const positiveStrategySelect =
            modal.querySelector('.admission-ai-positive-strategy-select');
        const positiveSimulationBoxes = [
            positiveSpecialtyExaminationBox,
            positiveGeneralExaminationBox,
            positivePresentIllnessBox,
            positivePastHistoryBox
        ].filter(Boolean);

        function readPositiveSimulationOptions() {
            return {
                specialtyExamination:
                    Boolean(
                        positiveSpecialtyExaminationBox &&
                        positiveSpecialtyExaminationBox.checked
                    ),
                generalExamination:
                    Boolean(
                        positiveGeneralExaminationBox &&
                        positiveGeneralExaminationBox.checked
                    ),
                presentIllness:
                    Boolean(
                        positivePresentIllnessBox &&
                        positivePresentIllnessBox.checked
                    ),
                pastHistory:
                    Boolean(
                        positivePastHistoryBox &&
                        positivePastHistoryBox.checked
                    ),
                strategy:
                    positiveStrategySelect &&
                    positiveStrategySelect.value === 'aggressive'
                        ? 'aggressive'
                        : 'conservative'
            };
        }

        function positiveSimulationSummary(type, options) {
            const source = options || {};
            const labels = [];

            if (type === 'presentIllness' && source.presentIllness) {
                labels.push('阳性现病史');
            }
            if (type === 'pastHistory' && source.pastHistory) {
                labels.push('阳性既往史');
            }
            if (type === 'examination') {
                if (source.generalExamination) {
                    labels.push('阳性一般查体');
                }
                if (source.specialtyExamination) {
                    labels.push('阳性专科查体');
                }
            }

            return labels;
        }

        function positiveSimulationStrategyLabel(options) {
            return options && options.strategy === 'aggressive'
                ? '激进'
                : '保守';
        }

        let rawGeneratedAdmissionRecord = '';
        let rawExpandedAdmissionRecord = '';

        /*
         * v2.41.18：入院记录定向修改前快照。
         *
         * “中医辨病辨证”和“主诉优化”都属于对已经生成/手工粘贴的
         * 初版入院记录进行局部替换。首次成功替换前保存一份完整快照；
         * 后续连续执行任意次数这两个按钮均不覆盖该快照，因此“还原”
         * 始终回到这一轮首次定向修改之前，而不是仅撤销上一步。
         *
         * 快照只存在当前页面内存，不写localStorage/WebDAV；重新生成初版、
         * 清空结果或切换患者时立即失效，避免旧患者/旧初稿误还原。
         */
        let admissionRecordAiPreRevisionSnapshot = '';

        function updateAdmissionRecordAiRestoreButton() {
            if (!restorePreRevisionButton) return;
            restorePreRevisionButton.disabled =
                !String(admissionRecordAiPreRevisionSnapshot || '').trim();
        }

        function resetAdmissionRecordAiPreRevisionSnapshot() {
            admissionRecordAiPreRevisionSnapshot = '';
            updateAdmissionRecordAiRestoreButton();
        }

        function captureAdmissionRecordAiPreRevisionSnapshot(sourceValue) {
            if (String(admissionRecordAiPreRevisionSnapshot || '').trim()) {
                updateAdmissionRecordAiRestoreButton();
                return;
            }

            const source = String(sourceValue || '')
                .replace(/\r\n?/g, '\n')
                .trim();

            if (!source) return;

            admissionRecordAiPreRevisionSnapshot = source;
            updateAdmissionRecordAiRestoreButton();
        }

        promptBox.value =
            admissionRecordAiLoadPrompt();

        const savedSupplements =
            admissionRecordAiLoadSupplementSections();

        Object.keys(supplementBoxes).forEach(function (key) {
            supplementBoxes[key].value =
                savedSupplements[key] || '';
        });

        supplementValidationBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_SUPPLEMENT_VALIDATION_STORAGE_KEY,
                false
            );

        supplementHighPriorityBox.checked =
            supplementValidationBox.checked &&
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_SUPPLEMENT_HIGH_PRIORITY_STORAGE_KEY,
                false
            );

        function updateSupplementPolicyControls() {
            const validationEnabled =
                Boolean(supplementValidationBox.checked);

            if (!validationEnabled) {
                supplementHighPriorityBox.checked = false;
            }

            supplementHighPriorityBox.disabled =
                !validationEnabled;
            supplementHighPriorityOption.style.opacity =
                validationEnabled ? '1' : '.55';
            supplementHighPriorityOption.title =
                validationEnabled
                    ? '补充资料冲突时直接以补充资料为准'
                    : '须先勾选补充资料校验';
        }

        updateSupplementPolicyControls();

        useOrdersBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_USE_ORDERS_STORAGE_KEY,
                false
            );

        outpatientSecondaryEditorBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_OUTPATIENT_SECONDARY_EDITOR_STORAGE_KEY,
                false
            );

        usePriorAdmissionBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_USE_PRIOR_ADMISSION_STORAGE_KEY,
                false
            );

        usePriorDischargeBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_USE_PRIOR_DISCHARGE_STORAGE_KEY,
                false
            );

        formatBox.checked =
            admissionRecordAiLoadBoolean(
                ADMISSION_RECORD_AI_FORMAT_STORAGE_KEY,
                true
            );

        const expansionPrompts =
            admissionRecordAiLoadExpansionPrompts();

        modal.querySelector('.admission-ai-present-prompt').value =
            expansionPrompts.presentIllness;
        modal.querySelector('.admission-ai-past-prompt').value =
            expansionPrompts.pastHistory;
        modal.querySelector('.admission-ai-examination-prompt').value =
            expansionPrompts.examination;

        function readExpansionPromptsFromModal() {
            return {
                presentIllness:
                    String(
                        modal.querySelector(
                            '.admission-ai-present-prompt'
                        ).value || ''
                    ),
                pastHistory:
                    String(
                        modal.querySelector(
                            '.admission-ai-past-prompt'
                        ).value || ''
                    ),
                examination:
                    String(
                        modal.querySelector(
                            '.admission-ai-examination-prompt'
                        ).value || ''
                    )
            };
        }

        function applyCurrentFormatting() {
            if (rawGeneratedAdmissionRecord) {
                resultBox.value = formatBox.checked
                    ? normalizeGeneratedAdmissionRecordFormatting(
                        rawGeneratedAdmissionRecord
                    )
                    : rawGeneratedAdmissionRecord;
            }

            if (rawExpandedAdmissionRecord) {
                expansionResultBox.value = formatBox.checked
                    ? normalizeGeneratedAdmissionRecordFormatting(
                        rawExpandedAdmissionRecord
                    )
                    : rawExpandedAdmissionRecord;
            }

            copyButton.disabled =
                !String(resultBox.value || '').trim();
            copyExpandedButton.disabled =
                !String(expansionResultBox.value || '').trim();
        }

        const rulesModal =
            admissionRecordAiCreateFormatRulesModal(
                modal,
                applyCurrentFormatting
            );

        function closeModal() {
            outpatientEditorPanel.hidden = true;
            modal.classList.remove('show');
        }

        modal.querySelector('.admission-ai-close')
            .addEventListener('click', closeModal);
        modal.querySelector('.admission-ai-mask')
            .addEventListener('click', closeModal);

        promptBox.addEventListener('input', function () {
            admissionRecordAiSavePrompt(promptBox.value);
        });

        function readSupplementSectionsFromModal() {
            return {
                personal:
                    String(supplementBoxes.personal.value || ''),
                diagnosis:
                    String(supplementBoxes.diagnosis.value || ''),
                auxiliary:
                    String(supplementBoxes.auxiliary.value || ''),
                other:
                    String(supplementBoxes.other.value || '')
            };
        }

        Object.keys(supplementBoxes).forEach(function (key) {
            supplementBoxes[key].addEventListener(
                'input',
                function () {
                    admissionRecordAiSaveSupplementSections(
                        readSupplementSectionsFromModal()
                    );
                }
            );
        });

        supplementValidationBox.addEventListener(
            'change',
            function () {
                if (!supplementValidationBox.checked) {
                    supplementHighPriorityBox.checked = false;
                    admissionRecordAiSaveBoolean(
                        ADMISSION_RECORD_AI_SUPPLEMENT_HIGH_PRIORITY_STORAGE_KEY,
                        false
                    );
                }

                admissionRecordAiSaveBoolean(
                    ADMISSION_RECORD_AI_SUPPLEMENT_VALIDATION_STORAGE_KEY,
                    supplementValidationBox.checked
                );
                updateSupplementPolicyControls();
            }
        );

        supplementHighPriorityBox.addEventListener(
            'change',
            function () {
                if (!supplementValidationBox.checked) {
                    supplementHighPriorityBox.checked = false;
                }

                admissionRecordAiSaveBoolean(
                    ADMISSION_RECORD_AI_SUPPLEMENT_HIGH_PRIORITY_STORAGE_KEY,
                    supplementHighPriorityBox.checked
                );
                updateSupplementPolicyControls();
            }
        );

        [
            modal.querySelector('.admission-ai-present-prompt'),
            modal.querySelector('.admission-ai-past-prompt'),
            modal.querySelector('.admission-ai-examination-prompt')
        ].forEach(function (box) {
            box.addEventListener('input', function () {
                admissionRecordAiSaveExpansionPrompts(
                    readExpansionPromptsFromModal()
                );
            });
        });

        useOrdersBox.addEventListener('change', function () {
            admissionRecordAiSaveBoolean(
                ADMISSION_RECORD_AI_USE_ORDERS_STORAGE_KEY,
                useOrdersBox.checked
            );
            updateAdmissionRecordAiModalStatus(modal);
        });

        outpatientSecondaryEditorBox.addEventListener(
            'change',
            function () {
                admissionRecordAiSaveBoolean(
                    ADMISSION_RECORD_AI_OUTPATIENT_SECONDARY_EDITOR_STORAGE_KEY,
                    outpatientSecondaryEditorBox.checked
                );

                if (outpatientSecondaryEditorBox.checked) {
                    outpatientEditorPanel.hidden = true;
                }
            }
        );

        usePriorAdmissionBox.addEventListener('change', function () {
            admissionRecordAiSaveBoolean(
                ADMISSION_RECORD_AI_USE_PRIOR_ADMISSION_STORAGE_KEY,
                usePriorAdmissionBox.checked
            );
            updateAdmissionRecordAiModalStatus(modal);
        });

        usePriorDischargeBox.addEventListener('change', function () {
            admissionRecordAiSaveBoolean(
                ADMISSION_RECORD_AI_USE_PRIOR_DISCHARGE_STORAGE_KEY,
                usePriorDischargeBox.checked
            );
            updateAdmissionRecordAiModalStatus(modal);
        });

        formatBox.addEventListener('change', function () {
            admissionRecordAiSaveBoolean(
                ADMISSION_RECORD_AI_FORMAT_STORAGE_KEY,
                formatBox.checked
            );

            if (!rawGeneratedAdmissionRecord) {
                rawGeneratedAdmissionRecord =
                    String(resultBox.value || '').trim();
            }

            if (!rawExpandedAdmissionRecord) {
                rawExpandedAdmissionRecord =
                    String(expansionResultBox.value || '').trim();
            }

            applyCurrentFormatting();
        });

        modal.querySelector('.admission-ai-format-rules-open')
            .addEventListener('click', function () {
                rulesModal._openFormatRules();
            });

        modal.querySelector('.admission-ai-reset-prompt')
            .addEventListener('click', function () {
                if (
                    !window.confirm(
                        '确定恢复默认入院记录提示词吗？'
                    )
                ) {
                    return;
                }

                promptBox.value =
                    DEFAULT_ADMISSION_RECORD_PROMPT;
                admissionRecordAiSavePrompt(promptBox.value);
                showStatus(
                    '已恢复入院记录默认提示词。',
                    'success'
                );
            });

        modal.querySelector('.admission-ai-reset-expand-prompts')
            .addEventListener('click', function () {
                if (
                    !window.confirm(
                        '确定恢复三类默认扩充提示词吗？'
                    )
                ) {
                    return;
                }

                modal.querySelector(
                    '.admission-ai-present-prompt'
                ).value =
                    DEFAULT_ADMISSION_RECORD_EXPANSION_PROMPTS.presentIllness;
                modal.querySelector(
                    '.admission-ai-past-prompt'
                ).value =
                    DEFAULT_ADMISSION_RECORD_EXPANSION_PROMPTS.pastHistory;
                modal.querySelector(
                    '.admission-ai-examination-prompt'
                ).value =
                    DEFAULT_ADMISSION_RECORD_EXPANSION_PROMPTS.examination;

                admissionRecordAiSaveExpansionPrompts(
                    readExpansionPromptsFromModal()
                );

                showStatus(
                    '已恢复默认扩充提示词。',
                    'success'
                );
            });

        modal.querySelector('.admission-ai-lock-patient')
            .addEventListener('click', function () {
                const identity =
                    extractCurrentPatientIdentity();

                if (!identity.name && !identity.inpatientNo) {
                    showStatus(
                        '当前页面未可靠识别患者身份。',
                        'error'
                    );
                    return;
                }

                const previous =
                    admissionRecordAiLoadTargetPatient();

                if (
                    previous &&
                    !patientIdentityMatches(previous, identity) &&
                    !window.confirm(
                        '当前入院记录AI目标为“' +
                        patientIdentityLabel(previous) +
                        '”。\n\n确定切换为当前患者“' +
                        patientIdentityLabel(identity) +
                        '”吗？旧患者缓存不会删除。'
                    )
                ) {
                    return;
                }

                admissionRecordAiSaveTargetPatient(identity);
                patientAiSaveUnlocked(
                    ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY,
                    false
                );
                rawGeneratedAdmissionRecord = '';
                rawExpandedAdmissionRecord = '';
                resetAdmissionRecordAiPreRevisionSnapshot();
                resultBox.value = '';
                expansionResultBox.value = '';
                outpatientEditorPanel.hidden = true;
                outpatientEditorBox.value = '';
                updateAdmissionRecordAiModalStatus(modal);

                showStatus(
                    '已锁定入院记录AI目标患者：' +
                    patientIdentityLabel(identity) + '。',
                    'success'
                );
            });

        modal.querySelector('.admission-ai-custom-patient')
            .addEventListener('click', function () {
                openPatientAiCustomEditor(ADMISSION_RECORD_AI_MODAL_ID);
            });

        modal.querySelector('.admission-ai-unlock-patient')
            .addEventListener('click', function () {
                const target =
                    admissionRecordAiLoadTargetPatient() ||
                    extractCurrentPatientIdentity();

                if (!target || (!target.name && !target.inpatientNo)) {
                    showStatus('尚未识别患者，无法进入解锁状态。', 'error');
                    return;
                }

                if (!admissionRecordAiLoadTargetPatient()) {
                    admissionRecordAiSaveTargetPatient(target);
                }

                if (!window.confirm(
                    '解锁后，入院记录AI将停止校验当前页面、门诊信息、医嘱及既往资料是否属于同一患者。\n\n仅在已人工核对资料时使用，是否继续？'
                )) return;

                patientAiSaveUnlocked(
                    ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY,
                    true
                );
                updateAdmissionRecordAiModalStatus(modal);
                showStatus(
                    '入院记录AI已解锁；患者信息一致性校验已停用。重新锁定可恢复校验。',
                    'error'
                );
            });

        modal.querySelector('.admission-ai-jump-admission')
            .addEventListener('click', async function () {
                const target =
                    admissionRecordAiLoadTargetPatient() ||
                    extractCurrentPatientIdentity();

                if (!target.name && !target.inpatientNo) {
                    showStatus(
                        '请先锁定当前患者。',
                        'error'
                    );
                    return;
                }

                modal.classList.remove('show');
                await admissionRecordAiJumpToAdmissionPage(
                    target,
                    true
                );
            });

        function targetOrThrow() {
            const target =
                admissionRecordAiLoadTargetPatient() ||
                extractCurrentPatientIdentity();

            if (!target.name && !target.inpatientNo) {
                throw new Error(
                    '尚未锁定入院记录AI目标患者'
                );
            }

            if (!admissionRecordAiLoadTargetPatient()) {
                admissionRecordAiSaveTargetPatient(target);
            }

            return target;
        }

        function saveManualOutpatientText(value) {
            const target = targetOrThrow();
            const textValue = String(value || '')
                .replace(/\r\n?/g, '\n')
                .trim();

            if (!textValue) {
                throw new Error(
                    '门诊信息为空，请键入内容后再保存。'
                );
            }

            const entry = {
                schemaVersion: 1,
                identity: target,
                sourceIdentity: target,
                text: textValue.slice(0, 100000),
                admissionTime: '',
                recordTime: '',
                dischargeDate: '',
                capturedAt: new Date().toLocaleString(),
                pageUrl: location.href,
                captureMode: 'manual',
                sourcePageType: ''
            };

            admissionRecordAiSaveCache(
                ADMISSION_RECORD_AI_OUTPATIENT_CACHE_STORAGE_KEY,
                entry
            );
            outpatientEditorBox.value = entry.text;
            outpatientEditorPanel.hidden = true;
            updateAdmissionRecordAiModalStatus(modal);

            showStatus(
                '已保存当前患者门诊信息：' +
                    entry.text.length + '字符。',
                'success'
            );

            return entry;
        }

        modal.querySelector('.admission-ai-edit-outpatient')
            .addEventListener('click', function () {
                try {
                    const target = targetOrThrow();
                    const cache = admissionRecordAiFindCache(
                        ADMISSION_RECORD_AI_OUTPATIENT_CACHE_STORAGE_KEY,
                        target
                    );
                    const cachedText =
                        cache && cache.text
                            ? String(cache.text)
                            : '';

                    if (outpatientSecondaryEditorBox.checked) {
                        outpatientEditorPanel.hidden = true;
                        openPatientAiManualEditor({
                            title: '手动录入/修改门诊信息',
                            hint: '可直接键入门诊信息；已有提取或手动保存内容会自动载入。保存后覆盖当前患者的本机门诊信息缓存，不修改HIS原记录。',
                            placeholder: '可录入或修改：门诊号、就诊日期、主诉、现病史、既往史、过敏史、查体、辅助检查、诊断、处理等门诊信息。',
                            value: cachedText,
                            onSave: function (value) {
                                saveManualOutpatientText(value);
                            }
                        });
                        return;
                    }

                    outpatientEditorBox.value =
                        cachedText;
                    outpatientEditorPanel.hidden = false;

                    window.requestAnimationFrame(function () {
                        outpatientEditorBox.focus();
                        outpatientEditorBox.setSelectionRange(
                            outpatientEditorBox.value.length,
                            outpatientEditorBox.value.length
                        );
                    });
                } catch (error) {
                    showStatus(error.message, 'error');
                }
            });

