        function bindSourceCapture(
            selector,
            kind,
            useBox
        ) {
            modal.querySelector(selector)
                .addEventListener('click', async function () {
                    try {
                        const target = targetOrThrow();
                        const entry =
                            await admissionRecordAiCaptureSource(
                                kind,
                                target,
                                patientAiLoadUnlocked(
                                    ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY
                                )
                            );

                        if (kind === 'outpatient') {
                            outpatientEditorBox.value =
                                String(entry.text || '');
                            outpatientEditorPanel.hidden = true;
                        }

                        if (useBox) {
                            useBox.checked = true;
                            useBox.dispatchEvent(
                                new Event('change', {
                                    bubbles: true
                                })
                            );
                        }

                        if (kind === 'draft') {
                            rawExpandedAdmissionRecord = '';
                            expansionResultBox.value = '';
                            copyExpandedButton.disabled = true;
                        }

                        updateAdmissionRecordAiModalStatus(modal);

                        showStatus(
                            '已读取' +
                            ({
                                outpatient: '门诊信息',
                                priorAdmission: '既往入院记录',
                                priorDischarge: '既往出院记录',
                                draft: '当前页入院记录初稿'
                            }[kind] || '资料') +
                            '：' +
                            String(entry.text || '').length +
                            '字符。',
                            'success'
                        );
                    } catch (error) {
                        showStatus(
                            '读取失败：' + error.message,
                            'error'
                        );
                    }
                });
        }

