        modal.querySelector('.admission-ai-extract-orders')
            .addEventListener('click', function () {
                try {
                    const target = targetOrThrow();
                    const current =
                        extractCurrentPatientIdentity();

                    if (
                        !patientAiLoadUnlocked(
                            ADMISSION_RECORD_AI_PATIENT_UNLOCKED_STORAGE_KEY
                        ) &&
                        !patientIdentityMatches(target, current)
                    ) {
                        throw new Error(
                            '当前医嘱页患者为“' +
                            patientIdentityLabel(current) +
                            '”，与目标患者“' +
                            patientIdentityLabel(target) +
                            '”不一致。既往住院页面不能作为本次医嘱来源。'
                        );
                    }

                    const orders =
                        collectCurrentOrderQueryText();

                    if (


                        (!orders.count && !orders.filteredVoidedTemporaryCount && !orders.filteredNoPrintCount && !orders.filteredCustomCount && !orders.filteredPendingReviewCount) ||


                        !orders.text


                    ) {
                        throw new Error(
                            '未识别到医嘱查询表。请进入当前患者“医嘱管理→医嘱查询”，并等待表格加载完成。'
                        );
                    }

                    admissionRecordAiSaveCache(
                        ADMISSION_RECORD_AI_ORDER_CACHE_STORAGE_KEY,
                        {
                            schemaVersion: 3,
                            identity: target,
                            sourceIdentity: current,
                            orderText: orders.text,
                            orderCount: orders.count,
                            filteredVoidedTemporaryCount:
                                orders.filteredVoidedTemporaryCount || 0,
                            filterVoidedTemporaryOrders:
                                Boolean(orders.filterVoidedTemporaryOrders),
                            filteredNoPrintCount:
                                orders.filteredNoPrintCount || 0,
                            filteredCustomCount:
                                orders.filteredCustomCount || 0,
                            filterNoPrintOrders:
                                Boolean(orders.filterNoPrintOrders),
                            filterCustomOrders:
                                Boolean(orders.filterCustomOrders),
                            customOrderPatterns: orders.customOrderPatterns || '',
                            filteredRecords: orders.filteredRecords || [],
                            includePendingOrders:
                                Boolean(orders.includePendingOrders),
                            pendingReviewCount:
                                orders.pendingReviewCount || 0,
                            filteredPendingReviewCount:
                                orders.filteredPendingReviewCount || 0,
                            hiddenCount:
                                orders.hiddenCount || 0,
                            records:
                                Array.isArray(orders.records)
                                    ? orders.records
                                    : [],
                            capturedAt:
                                new Date().toLocaleString(),
                            pageUrl: location.href,
                            captureMode: 'page-dom'
                        }
                    );

                    useOrdersBox.checked = true;
                    useOrdersBox.dispatchEvent(
                        new Event('change', {
                            bubbles: true
                        })
                    );

                    updateAdmissionRecordAiModalStatus(modal);

                    showStatus(
                        '已结构化缓存当前住院医嘱：' +
                        orders.count + '条' +
                        inpatientOrderFilterResultSuffix(orders) + '。',
                        'success'
                    );
                } catch (error) {
                    showStatus(
                        '提取医嘱失败：' + error.message,
                        'error'
                    );
                }
            });

