    function inpatientCacheManagementDescriptorById(id) {
        return INPATIENT_CACHE_MANAGEMENT_DESCRIPTORS
            .find(function (item) {
                return item.id === String(id || '');
            }) || null;
    }

    function inpatientCacheManagementDescriptorByStorageKey(storageKey) {
        return INPATIENT_CACHE_MANAGEMENT_DESCRIPTORS
            .find(function (item) {
                return item.storageKey === String(storageKey || '');
            }) || null;
    }

    function inpatientCacheManagementSelected(ids) {
        const requested = Array.isArray(ids)
            ? new Set(ids.map(function (item) { return String(item || ''); }))
            : null;

        return INPATIENT_CACHE_MANAGEMENT_DESCRIPTORS
            .filter(function (item) {
                return !requested || requested.has(item.id);
            });
    }

    function inpatientCacheManagementListCaches() {
        return INPATIENT_CACHE_MANAGEMENT_DESCRIPTORS
            .map(function (descriptor) {
                const stats =
                    inpatientLargeCacheStats(
                        descriptor.storageKey
                    );
                return Object.assign(
                    {},
                    descriptor,
                    stats
                );
            });
    }

    function inpatientCacheManagementExportCaches(ids) {
        const caches = {};

        inpatientCacheManagementSelected(ids)
            .forEach(function (descriptor) {
                const store =
                    inpatientLargeCacheReadStore(
                        descriptor.storageKey
                    );
                caches[descriptor.id] = {
                    storageKey: descriptor.storageKey,
                    name: descriptor.name,
                    policy: descriptor.policy,
                    data: store
                };
            });

        return {
            schemaVersion: 1,
            adapterKey: 'inpatient',
            scriptVersion: '2.41.35',
            exportedAt: new Date().toISOString(),
            caches: caches
        };
    }

    function inpatientCacheManagementValidateCaches(data) {
        if (
            !data ||
            typeof data !== 'object' ||
            Array.isArray(data)
        ) {
            return '住院信息缓存备份不是有效对象。';
        }

        const caches = data.caches;
        if (
            !caches ||
            typeof caches !== 'object' ||
            Array.isArray(caches)
        ) {
            return '住院信息缓存备份缺少caches对象。';
        }

        const invalidId = Object.keys(caches)
            .find(function (id) {
                const descriptor =
                    inpatientCacheManagementDescriptorById(id);
                if (!descriptor) return true;

                const item = caches[id];
                return !(
                    item &&
                    typeof item === 'object' &&
                    !Array.isArray(item) &&
                    item.data &&
                    typeof item.data === 'object' &&
                    !Array.isArray(item.data)
                );
            });

        return invalidId
            ? '缓存备份中包含未知或无效项目：' + invalidId
            : true;
    }

    function inpatientCacheManagementImportCaches(data) {
        const validation =
            inpatientCacheManagementValidateCaches(data);

        if (validation !== true) {
            throw new Error(String(validation));
        }

        const restored = [];
        Object.keys(data.caches)
            .forEach(function (id) {
                const descriptor =
                    inpatientCacheManagementDescriptorById(id);
                const item = data.caches[id];
                if (!descriptor || !item) return;

                inpatientLargeCacheWriteStore(
                    descriptor.storageKey,
                    inpatientLargeCachePlainStore(item.data)
                );
                restored.push(id);
            });

        return {
            restored: restored
        };
    }

    function inpatientCacheManagementClearCaches(ids) {
        const cleared = [];
        inpatientCacheManagementSelected(ids)
            .forEach(function (descriptor) {
                inpatientLargeCacheDeleteStore(
                    descriptor.storageKey
                );
                cleared.push(descriptor.id);
            });
        return {
            cleared: cleared
        };
    }

    function inpatientCacheManagementMigrateLegacyStores() {
        const migrated = [];

        INPATIENT_CACHE_MANAGEMENT_DESCRIPTORS
            .forEach(function (descriptor) {
                const before =
                    inpatientLargeCacheReadSerializedFromGmOnly(
                        descriptor.storageKey
                    );
                try {
                    inpatientLargeCacheReadStore(
                        descriptor.storageKey
                    );
                    const after =
                        inpatientLargeCacheReadSerializedFromGmOnly(
                            descriptor.storageKey
                        );
                    if (!before && after) {
                        migrated.push(descriptor.id);
                    }
                } catch (error) {
                    console.warn(
                        '[住院信息GM缓存迁移失败]',
                        descriptor.storageKey,
                        error
                    );
                }
            });

        return migrated;
    }

    function inpatientCacheManagementPageWindow() {
        try {
            if (
                typeof unsafeWindow !== 'undefined' &&
                unsafeWindow
            ) {
                return unsafeWindow;
            }
        } catch (error) {
            // 回退window。
        }
        return window;
    }

    function inpatientCacheManagementRegister() {
        /*
         * 启动后立即迁移现存旧患者缓存，从根源释放localStorage空间。
         */
        const migrated =
            inpatientCacheManagementMigrateLegacyStores();

        if (migrated.length) {
            console.log(
                '[住院信息GM缓存迁移] 已迁移：',
                migrated.join('、')
            );
        }

        const adapter = {
            key: 'inpatient',
            name: '住院信息自动填写',
            version: '2.41.43',
            adapterVersion: 2,
            containsPatientData: true,
            listCaches: inpatientCacheManagementListCaches,
            exportCaches: inpatientCacheManagementExportCaches,
            validateCaches: inpatientCacheManagementValidateCaches,
            importCaches: inpatientCacheManagementImportCaches,
            clearCaches: inpatientCacheManagementClearCaches,
            readLegacyStorageKey: function (storageKey) {
                const descriptor =
                    inpatientCacheManagementDescriptorByStorageKey(
                        storageKey
                    );
                if (!descriptor) return null;

                /*
                 * 仅直接读取GM，绝不回读localStorage，避免管理器兼容桥
                 * 与本脚本懒迁移形成递归。
                 */
                return inpatientLargeCacheReadSerializedFromGmOnly(
                    descriptor.storageKey
                );
            },
            isBusy: function () {
                return false;
            }
        };

        const page =
            inpatientCacheManagementPageWindow();

        function registerNow() {
            try {
                if (
                    page[INPATIENT_CACHE_MANAGEMENT_API_NAME] &&
                    typeof page[INPATIENT_CACHE_MANAGEMENT_API_NAME]
                        .register === 'function'
                ) {
                    page[INPATIENT_CACHE_MANAGEMENT_API_NAME]
                        .register(adapter);
                    return true;
                }
            } catch (error) {
                console.warn(
                    '[统一缓存管理适配] 直接注册失败：',
                    error
                );
            }
            return false;
        }

        if (!registerNow()) {
            try {
                const queue = Array.isArray(
                    page[INPATIENT_CACHE_MANAGEMENT_QUEUE_NAME]
                )
                    ? page[INPATIENT_CACHE_MANAGEMENT_QUEUE_NAME]
                    : [];
                queue.push(adapter);
                page[INPATIENT_CACHE_MANAGEMENT_QUEUE_NAME] = queue;
            } catch (error) {
                console.warn(
                    '[统一缓存管理适配] 排队注册失败：',
                    error
                );
            }
        }

        if (!inpatientCacheManagementRegister._readyBound) {
            inpatientCacheManagementRegister._readyBound = true;
            document.addEventListener(
                INPATIENT_CACHE_MANAGEMENT_READY_EVENT_NAME,
                registerNow,
                false
            );
        }
    }

